import { useEffect, useState } from "react";

import { API_BASE_URL } from "@/config/api";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { toast } from "@/components/ui/sonner";
import { useAuth } from "@/contexts/AuthContext";
import { Switch } from "@/components/ui/switch";

export default function PengurusForm({ open, onOpenChange, pengurus, onSaved }) {
  const { token } = useAuth(); // 🔐 JWT
  const [loading, setLoading] = useState(false);

  const [form, setForm] = useState({
    nama_lengkap: "",
    nama_jabatan: "",
    aktif: true,
    mulai_jabatan: "",
    sampai_jabatan: "",
  });

  // --------------------------------------------------
  // LOAD DATA SAAT EDIT
  // --------------------------------------------------
  useEffect(() => {
    if (pengurus) {
      setForm({
        nama_lengkap: pengurus.nama_lengkap || "",
        nama_jabatan: pengurus.nama_jabatan || "",
        aktif: pengurus.aktif !== undefined ? pengurus.aktif : true,
        mulai_jabatan: pengurus.mulai_jabatan || "",
        sampai_jabatan: pengurus.sampai_jabatan || "",
      });
    } else {
      setForm({
        nama_lengkap: "",
        nama_jabatan: "",
        aktif: true,
        mulai_jabatan: "",
        sampai_jabatan: "",
      });
    }
  }, [pengurus]);

  // --------------------------------------------------
  // SAVE
  // --------------------------------------------------
  const save = async () => {
    if (!form.nama_lengkap.trim()) {
      toast.error("Nama lengkap harus diisi");
      return;
    }

    if (!form.nama_jabatan.trim()) {
      toast.error("Nama jabatan harus diisi");
      return;
    }

    setLoading(true);

    const url = pengurus
      ? `${API_BASE_URL}/api/pengurus/${pengurus.id}`
      : `${API_BASE_URL}/api/pengurus`;

    const method = pengurus ? "PUT" : "POST";

    try {
      const payload = {
        ...form,
      };

      const res = await fetch(url, {
        method,
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify(payload),
      });

      if (!res.ok) {
        toast.error("Gagal menyimpan data pengurus");
        setLoading(false);
        return;
      }

      toast.success(pengurus ? "Data pengurus berhasil diperbarui!" : "Pengurus baru ditambahkan!");
      onSaved();
      onOpenChange(false);

    } catch (err) {
      toast.error("Tidak dapat terhubung ke server");
      console.error(err);
    }

    setLoading(false);
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl dark:bg-gray-900 dark:text-gray-100 max-h-screen overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{pengurus ? "Edit Pengurus" : "Tambah Pengurus"}</DialogTitle>
        </DialogHeader>

        <div className="space-y-3">

          {/* ROW 1: NAMA LENGKAP & NAMA JABATAN */}
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">
                Nama Lengkap
              </label>
              <Input
                placeholder="Nama Lengkap"
                value={form.nama_lengkap}
                onChange={(e) => setForm({ ...form, nama_lengkap: e.target.value })}
                className="dark:bg-gray-800 dark:text-gray-100"
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">
                Nama Jabatan
              </label>
              <Input
                placeholder="Nama Jabatan"
                value={form.nama_jabatan}
                onChange={(e) => setForm({ ...form, nama_jabatan: e.target.value })}
                className="dark:bg-gray-800 dark:text-gray-100"
              />
            </div>
          </div>

          {/* ROW 2: PERIODE JABATAN */}
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">
                Mulai Jabatan
              </label>
              <Input
                type="date"
                value={form.mulai_jabatan}
                onChange={(e) => setForm({ ...form, mulai_jabatan: e.target.value })}
                className="dark:bg-gray-800 dark:text-gray-100"
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">
                Sampai Jabatan
              </label>
              <Input
                type="date"
                value={form.sampai_jabatan}
                onChange={(e) => setForm({ ...form, sampai_jabatan: e.target.value })}
                className="dark:bg-gray-800 dark:text-gray-100"
              />
            </div>
          </div>

          {/* ROW 3: STATUS AKTIF */}
          <div>
            <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">
              Status Aktif
            </label>
            <div className="flex items-center gap-3 p-3 rounded-md border border-gray-300 dark:border-gray-700 bg-[var(--rw-bg-card-alt)] dark:bg-gray-800">
              <Switch
                checked={form.aktif}
                onCheckedChange={(checked) => setForm({ ...form, aktif: checked })}
              />
              <span className="text-sm font-medium dark:text-gray-200">
                {form.aktif ? "✓ Aktif" : "✗ Tidak Aktif"}
              </span>
            </div>
          </div>

          {/* BUTTONS */}
          <div className="flex gap-3 justify-end pt-4">
            <Button
              variant="outline"
              onClick={() => onOpenChange(false)}
              className="dark:border-gray-700 dark:text-gray-200 dark:hover:bg-gray-800"
            >
              Batal
            </Button>
            <Button
              onClick={save}
              disabled={loading}
              className="bg-[var(--rw-primary)] hover:bg-[var(--rw-primary-hover)] text-white"
            >
              {loading ? "Menyimpan..." : "Simpan"}
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}
