import React, { useEffect, useState } from "react";
import { createPortal } from 'react-dom';
import { useAuth } from "../../contexts/AuthContext";
import { API_BASE_URL } from "../../config/api";
import { CreditCard, CheckCircle, Clock, XCircle, Plus, AlertTriangle, RefreshCw } from "lucide-react";

const fmt = (n) => new Intl.NumberFormat("id-ID", { style: "currency", currency: "IDR", maximumFractionDigits: 0 }).format(n || 0);

const statusBadge = (status) => {
  const map = {
    active:    ["bg-green-100 text-green-700", "Aktif"],
    expired:   ["bg-red-100 text-red-700",     "Expired"],
    trial:     ["bg-yellow-100 text-yellow-700","Trial"],
    cancelled: ["bg-gray-100 text-gray-600",   "Cancelled"],
  };
  const [cls, lbl] = map[status] || ["bg-gray-100 text-gray-600", status];
  return <span className={`text-xs px-2 py-1 rounded-full font-medium ${cls}`}>{lbl}</span>;
};

const PACKAGES = [
  { id: "starter",    name: "Starter",    price: 99000,  features: ["Max 50 pengguna", "Max 100 rumah", "IPL & Keuangan", "WhatsApp Basic"], color: "border-gray-200" },
  { id: "standard",  name: "Standard",   price: 199000, features: ["Max 150 pengguna", "Max 300 rumah", "Semua fitur Starter", "CCTV Monitor", "Budget & Dana"], color: "border-cyan-400", recommended: true },
  { id: "premium",   name: "Premium",    price: 349000, features: ["Unlimited pengguna", "Unlimited rumah", "Semua fitur Standard", "Multi RW/Kelurahan", "API Access", "Priority Support"], color: "border-purple-400" },
];

export default function SubscriptionPage() {
  const { token } = useAuth();
  const [subscriptions, setSubscriptions] = useState([]);
  const [loading, setLoading]     = useState(false);
  const [showPackages, setShowPackages] = useState(false);
  const [selected, setSelected]   = useState(null);
  const [saving, setSaving]       = useState(false);
  const [error, setError]         = useState("");

  const fetchSubs = async () => {
    setLoading(true);
    try {
      const res = await fetch(`${API_BASE_URL}/api/vendor/subscriptions`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (res.ok) setSubscriptions(await res.json());
    } catch (_) {}
    setLoading(false);
  };

  useEffect(() => { fetchSubs(); }, []);

  const handleSubscribe = async () => {
    if (!selected) return;
    setSaving(true); setError("");
    try {
      const res = await fetch(`${API_BASE_URL}/api/vendor/subscriptions`, {
        method: "POST",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
        body: JSON.stringify({ package_id: selected }),
      });
      if (!res.ok) { const d = await res.json(); throw new Error(d.detail || "Gagal"); }
      setShowPackages(false); setSelected(null); fetchSubs();
    } catch (e) { setError(e.message); }
    setSaving(false);
  };

  return (
    <div className="p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-800 dark:text-white">Subscription</h1>
          <p className="text-sm text-gray-500">Kelola paket langganan per tenant</p>
        </div>
        <div className="flex gap-2">
          <button onClick={fetchSubs} className="flex items-center gap-2 px-3 py-2 border rounded-xl text-sm hover:bg-gray-50 dark:border-gray-600">
            <RefreshCw size={15} className={loading ? "animate-spin" : ""} />
          </button>
          <button onClick={() => setShowPackages(true)}
            className="flex items-center gap-2 px-4 py-2 bg-[var(--rw-primary)] text-white rounded-xl hover:bg-[var(--rw-primary-hover)]">
            <Plus size={15} /> Tambah Langganan
          </button>
        </div>
      </div>

      {/* Subscription list */}
      <div className="bg-[var(--rw-bg-card)] dark:bg-gray-800 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-700 overflow-hidden">
        <div className="p-4 border-b dark:border-gray-700 font-semibold text-gray-800 dark:text-white">
          Langganan Aktif
        </div>
        {subscriptions.length === 0 ? (
          <div className="p-12 text-center">
            <CreditCard size={40} className="mx-auto text-gray-300 mb-3" />
            <p className="text-gray-400 text-sm">Belum ada langganan. Pilih paket untuk mulai.</p>
            <button onClick={() => setShowPackages(true)}
              className="mt-4 px-4 py-2 bg-[var(--rw-primary)] text-white rounded-xl hover:bg-[var(--rw-primary-hover)]">
              Pilih Paket
            </button>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead className="bg-[var(--rw-bg-card-alt)] dark:bg-gray-700/50">
                <tr>
                  {["Tenant", "Paket", "Mulai", "Berakhir", "Status"].map(h => (
                    <th key={h} className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
                {subscriptions.map(s => (
                  <tr key={s.id} className="hover:bg-[var(--rw-bg-card-alt)] dark:hover:bg-gray-700/30">
                    <td className="px-4 py-3 font-medium text-gray-800 dark:text-white">{s.tenant_name || s.tenant_id}</td>
                    <td className="px-4 py-3 text-gray-500">{s.package_name || s.package_id}</td>
                    <td className="px-4 py-3 text-gray-500">{s.started_at ? new Date(s.started_at).toLocaleDateString("id-ID") : "-"}</td>
                    <td className="px-4 py-3 text-gray-500">{s.expires_at ? new Date(s.expires_at).toLocaleDateString("id-ID") : "∞"}</td>
                    <td className="px-4 py-3">{statusBadge(s.status)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Pilih Paket Modal */}
      {showPackages && createPortal(
        <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[9999] flex items-center justify-center p-4">
          <div className="bg-[var(--rw-bg-card)] dark:bg-gray-800 rounded-2xl shadow-xl w-full max-w-3xl max-h-[90vh] overflow-y-auto">
            <div className="p-5 border-b dark:border-gray-700 flex items-center justify-between sticky top-0 bg-[var(--rw-bg-card)] dark:bg-gray-800">
              <h3 className="font-semibold text-gray-800 dark:text-white">Pilih Paket Langganan</h3>
              <button onClick={() => { setShowPackages(false); setError(""); }} className="text-gray-400 hover:text-gray-600">✕</button>
            </div>
            <div className="p-5">
              {error && <div className="mb-4 text-sm text-red-600 bg-red-50 p-3 rounded-lg flex gap-2"><AlertTriangle size={15}/>{error}</div>}
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                {PACKAGES.map(pkg => (
                  <div key={pkg.id}
                    onClick={() => setSelected(pkg.id)}
                    className={`relative border-2 rounded-2xl p-5 cursor-pointer transition-all ${
                      selected === pkg.id ? "border-cyan-500 bg-cyan-50 dark:bg-cyan-900/20" : `${pkg.color} hover:border-cyan-300`
                    }`}>
                    {pkg.recommended && (
                      <div className="absolute -top-3 left-1/2 -translate-x-1/2 bg-[var(--rw-primary)] text-white text-xs px-3 py-1 rounded-full font-medium">
                        Rekomendasi
                      </div>
                    )}
                    <h4 className="font-bold text-gray-800 dark:text-white text-lg">{pkg.name}</h4>
                    <p className="text-2xl font-bold text-cyan-500 mt-2">{fmt(pkg.price)}<span className="text-sm text-gray-400 font-normal">/bln</span></p>
                    <ul className="mt-4 space-y-2">
                      {pkg.features.map(f => (
                        <li key={f} className="flex items-center gap-2 text-sm text-gray-600 dark:text-gray-300">
                          <CheckCircle size={14} className="text-green-500 flex-shrink-0" />{f}
                        </li>
                      ))}
                    </ul>
                    {selected === pkg.id && (
                      <div className="mt-4 text-center text-xs text-cyan-600 font-medium">✓ Dipilih</div>
                    )}
                  </div>
                ))}
              </div>
              <div className="flex gap-3 mt-5">
                <button onClick={() => { setShowPackages(false); setError(""); }}
                  className="flex-1 border rounded-xl py-2 text-sm hover:bg-gray-50 dark:border-gray-600">Batal</button>
                <button onClick={handleSubscribe} disabled={!selected || saving}
                  className="flex-1 bg-[var(--rw-primary)] text-white rounded-xl hover:bg-[var(--rw-primary-hover)] disabled:opacity-50">
                  {saving ? "Memproses..." : "Langganan Sekarang"}
                </button>
              </div>
            </div>
          </div>
        </div>,
        document.body
      )}
    </div>
  );
}
