// ── Calendar ─────────────────────────────────────────────────

function MiniCalendar({ year, month, jadwalList, selectedDate, onSelectDate, onPrev, onNext }) {
  const today = new Date();
  const firstDay = new Date(year, month, 1).getDay();
  const daysInMonth = new Date(year, month + 1, 0).getDate();

  const dotsByDate = useMemo(() => {
    const map = {};
    jadwalList.forEach(j => {
      const d = j.tanggal?.split('-')[2];
      if (!d) return;
      const key = parseInt(d, 10);
      if (!map[key]) map[key] = new Set();
      map[key].add(j.jenis);
    });
    return map;
  }, [jadwalList]);

  const cells = [];
  for (let i = 0; i < firstDay; i++) cells.push(null);
  for (let d = 1; d <= daysInMonth; d++) cells.push(d);

  const isToday = (d) =>
    d && today.getFullYear() === year && today.getMonth() === month && today.getDate() === d;

  const isSelected = (d) => {
    if (!d || !selectedDate) return false;
    const selStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
    return selStr === selectedDate;
  };

  return (
    <div className="bg-[var(--rw-bg-card)] dark:bg-gray-800 rounded-lg shadow p-4">
      {/* Header */}
      <div className="flex items-center justify-between mb-3">
        <button onClick={onPrev} className="p-1.5 rounded hover:bg-[var(--rw-bg-card-alt)] dark:hover:bg-gray-700 transition-colors">
          <ChevronLeft className="h-4 w-4 text-gray-600 dark:text-gray-400" />
        </button>
        <span className="font-semibold text-gray-800 dark:text-gray-200 text-sm">
          {BULAN_NAMES[month]} {year}
        </span>
        <button onClick={onNext} className="p-1.5 rounded hover:bg-[var(--rw-bg-card-alt)] dark:hover:bg-gray-700 transition-colors">
          <ChevronRight className="h-4 w-4 text-gray-600 dark:text-gray-400" />
        </button>
      </div>

      {/* Day headers */}
      <div className="grid grid-cols-7 mb-1">
        {HARI.map(h => (
          <div key={h} className="text-center text-xs font-semibold text-gray-400 dark:text-gray-500 py-1">{h}</div>
        ))}
      </div>

      {/* Days */}
      <div className="grid grid-cols-7 gap-y-1">
        {cells.map((d, i) => (
          <div key={i} className="flex flex-col items-center">
            {d ? (
              <button
                onClick={() => {
                  const str = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
                  onSelectDate(isSelected(d) ? null : str);
                }}
                className={`w-8 h-8 rounded-full text-sm font-medium transition-colors
                  ${isToday(d) ? 'bg-gray-900 dark:bg-white text-white dark:text-gray-900' :
                    isSelected(d) ? 'bg-orange-500 text-white' :
                    'hover:bg-[var(--rw-bg-card-alt)] dark:hover:bg-gray-700 text-gray-700 dark:text-gray-300'}`}
              >
                {d}
              </button>
            ) : <div className="w-8 h-8" />}
            {/* Dots */}
            {d && dotsByDate[d] ? (
              <div className="flex gap-0.5 mt-0.5">
                {[...dotsByDate[d]].slice(0, 3).map(j => (
                  <div key={j} className={`w-1.5 h-1.5 rounded-full ${JENIS_CONFIG[j]?.dot || 'bg-gray-400'}`} />
                ))}
              </div>
            ) : <div className="h-2" />}
          </div>
        ))}
      </div>

      {/* Legend */}
      <div className="mt-3 pt-3 border-t border-[var(--rw-border)] dark:border-gray-700 flex flex-wrap gap-3">
        {Object.entries(JENIS_CONFIG).map(([k, v]) => (
          <div key={k} className="flex items-center gap-1">
            <div className={`w-2.5 h-2.5 rounded-full ${v.dot}`} />
            <span className="text-xs text-gray-500 dark:text-gray-400">{v.label}</span>
          </div>
        ))}
      </div>
    </div>
  );
}

// ── Modal ────────────────────────────────────────────────────

function Modal({ open, title, onClose, children }) {
  if (!open) return null;
  return createPortal(
    <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[9999] flex items-center justify-center p-4">
      <div className="bg-[var(--rw-bg-card)] dark:bg-gray-900 rounded-2xl shadow-2xl w-full max-w-md max-h-[90vh] flex flex-col">
        <div className="p-5 border-b border-[var(--rw-border)] dark:border-gray-700 flex items-center justify-between flex-shrink-0">
          <h3 className="font-bold text-gray-800 dark:text-gray-100 text-base">{title}</h3>
          <button onClick={onClose} className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-200">
            <X size={18} />
          </button>
        </div>
        <div className="flex-1 overflow-y-auto p-5">{children}</div>
      </div>
    </div>,
    document.body
  );
}

function FormRow({ label, children }) {
  return (
    <div className="space-y-1">
      <label className="block text-xs font-medium text-gray-600 dark:text-gray-400">{label}</label>
      {children}
    </div>
  );
}

