  const [activeTemplateJenis, setActiveTemplateJenis] = useState('ronda');
  const [reminderSettingLoading, setReminderSettingLoading] = useState(false);
  const [reminderSettingFetching, setReminderSettingFetching] = useState(false);
  const [reminderLogs, setReminderLogs] = useState([]);
