        ...prev,
        ...r.data,
        template_ronda:         r.data.template_ronda         || prev.template_ronda,
        template_rapat:         r.data.template_rapat         || prev.template_rapat,
        template_gotong_royong: r.data.template_gotong_royong || prev.template_gotong_royong,
