import React, { useEffect, useState } from 'react';
import { useSearchParams } from 'react-router-dom';
import { Bell, FileText } from 'lucide-react';
import { useAuth } from '../contexts/AuthContext';
import { API_BASE_URL } from '../config/api';

/**
 * Menu "Pengumuman" komprehensif: Pengumuman + Surat Edaran dalam satu menu
 * (tab). Dipakai di RT/Warga, RW, dan Kelurahan — tiap level mengirim halaman
 * Pengumuman & Surat Edaran miliknya sendiri. Tab aktif disimpan di URL
 * (?tab=surat) supaya link lama/notifikasi surat edaran bisa langsung
 * membuka tab Surat Edaran.
 *
 * Tab Surat Edaran hanya tampil kalau role punya izin baca menu surat-nya
 * (suratMenuId); backend tetap yang menegakkan akses sebenarnya.
 */
export default function PengumumanSuratTabs({ pengumuman, surat, suratMenuId }) {
  const { token, user } = useAuth();
  const [params, setParams] = useSearchParams();
  const [suratAllowed, setSuratAllowed] = useState(true);

  useEffect(() => {
    if (!token || !user?.role || !suratMenuId) return undefined;
    let cancelled = false;
    fetch(`${API_BASE_URL}/api/role-permissions/${user.role}`, { headers: { Authorization: `Bearer ${token}` } })
      .then(r => (r.ok ? r.json() : null))
      .then(d => {
        if (cancelled || !d) return;
        const perm = (d.permissions || {})[suratMenuId];
        // Sama dengan aturan sidebar: tidak ada aturan eksplisit = boleh
        setSuratAllowed(perm ? perm.read !== false : true);
      })
      .catch(() => {});
    return () => { cancelled = true; };
  }, [token, user?.role, suratMenuId]);

  const showSurat = !!surat && suratAllowed;
  const active = showSurat && params.get('tab') === 'surat' ? 'surat' : 'pengumuman';

  const select = (tab) => {
    const next = new URLSearchParams(params);
    if (tab === 'surat') next.set('tab', 'surat'); else next.delete('tab');
    setParams(next, { replace: true });
  };

  const tabs = [
    { id: 'pengumuman', label: 'Pengumuman', icon: Bell },
    ...(showSurat ? [{ id: 'surat', label: 'Surat Edaran', icon: FileText }] : []),
  ];

  return (
    <div className="min-h-full bg-[var(--rw-bg-page)] dark:bg-gray-900">
      {tabs.length > 1 && (
        <div className="px-6 pt-5">
          <div className="inline-flex gap-1 bg-[var(--rw-bg-card)] dark:bg-gray-800 rounded-xl p-1 shadow-sm border border-[var(--rw-border)] dark:border-gray-700">
            {tabs.map(({ id, label, icon: Icon }) => (
              <button
                key={id}
                type="button"
                onClick={() => select(id)}
                className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-semibold transition-colors ${
                  active === id
                    ? 'bg-purple-600 text-white shadow'
                    : 'text-gray-600 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700'
                }`}
              >
                <Icon size={15} /> {label}
              </button>
            ))}
          </div>
        </div>
      )}
      {active === 'surat' ? surat : pengumuman}
    </div>
  );
}
