import React, { useCallback, useEffect, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import { useLocation } from 'react-router-dom';
import { ArrowLeft, ArrowRight, Check } from 'lucide-react';
import { useAuth } from '../contexts/AuthContext';
import { useSidebar } from '../contexts/SidebarContext';
import { findWargaTour, buildGenericTour } from '../lib/wargaTours';

// Nama halaman untuk panduan otomatis: judul (h1) halaman, atau menu aktif di sidebar
function currentPageName() {
  const h1 = document.querySelector('main h1');
  if (h1 && h1.textContent.trim()) return h1.textContent.trim();
  const active = document.querySelector('aside a[class*="text-[var(--rw-primary)]"]');
  return active ? active.textContent.trim() : '';
}

function tourFor(pathname) {
  return findWargaTour(pathname) || buildGenericTour(pathname, currentPageName());
}

/**
 * Panduan visual per menu untuk warga (lansia-friendly).
 *  - Muncul otomatis saat sebuah menu PERTAMA kali dibuka (sekali per akun per
 *    perangkat), menyorot elemen penting dengan kartu petunjuk besar.
 *  - Bisa dibuka lagi kapan saja lewat tombol "Panduan" di Header
 *    (event 'page-tour:start').
 * Status "sudah dilihat" disimpan di localStorage per akun.
 */

const SEEN_KEY = (uid) => `page_tour_seen_v1_${uid}`;
const readSeen = (uid) => { try { return JSON.parse(localStorage.getItem(SEEN_KEY(uid)) || '[]'); } catch { return []; } };
const writeSeen = (uid, list) => { try { localStorage.setItem(SEEN_KEY(uid), JSON.stringify(list)); } catch { /* abaikan */ } };

function resolveTarget(spec) {
  if (!spec) return null;
  try {
    const nodes = document.querySelectorAll(typeof spec === 'string' ? spec : (spec.sel || '*'));
    for (const el of nodes) {
      if (typeof spec !== 'string' && spec.text && !spec.text.test((el.textContent || '').trim())) continue;
      if (el.getClientRects().length) return el;
    }
  } catch { /* selector tidak valid */ }
  return null;
}

export default function PageTour() {
  const { user } = useAuth();
  const { pathname } = useLocation();
  const { isMobile: sidebarMobile, openSidebar, closeSidebar } = useSidebar();
  const sidebarByTour = useRef(false);   // sidebar dibuka oleh panduan → tutup lagi setelahnya
  const uid = user?.id || user?.username || 'anon';
  const isWarga = user?.role === 'warga';

  const [tour, setTour] = useState(null);
  const [idx, setIdx] = useState(0);
  const [rect, setRect] = useState(null);
  const targetRef = useRef(null);
  const cardRef = useRef(null);
  const [cardH, setCardH] = useState(220);

  const finish = useCallback(() => {
    if (sidebarByTour.current) { sidebarByTour.current = false; closeSidebar(); }
    if (tour) {
      const seen = readSeen(uid);
      if (!seen.includes(tour.id)) writeSeen(uid, [...seen, tour.id]);
    }
    setTour(null);
    setIdx(0);
    setRect(null);
    targetRef.current = null;
  }, [tour, uid, closeSidebar]);

  // Mulai otomatis saat pindah ke menu yang belum pernah dipandu
  useEffect(() => {
    if (!isWarga) return undefined;
    const known = findWargaTour(pathname);
    const seenId = known ? known.id : `auto:${(pathname || '/').replace(/\/+$/, '') || '/'}`;
    if (readSeen(uid).includes(seenId)) { setTour(null); return undefined; }
    // Tunggu halaman selesai dimuat agar judul/elemen target sudah ada
    const timer = setTimeout(() => { setTour(known || tourFor(pathname)); setIdx(0); }, 1200);
    return () => clearTimeout(timer);
  }, [pathname, isWarga, uid]);

  // Mulai manual dari tombol "Panduan"
  useEffect(() => {
    if (!isWarga) return undefined;
    const start = () => {
      setTour(tourFor(pathname));
      setIdx(0);
    };
    // "Ulangi Semua Panduan": hapus tanda sudah-dilihat supaya panduan tiap menu
    // muncul lagi saat menu dibuka, lalu langsung putar panduan halaman ini.
    const resetAll = () => { writeSeen(uid, []); start(); };
    window.addEventListener('page-tour:start', start);
    window.addEventListener('page-tour:reset-all', resetAll);
    return () => {
      window.removeEventListener('page-tour:start', start);
      window.removeEventListener('page-tour:reset-all', resetAll);
    };
  }, [isWarga, pathname, uid]);

  const step = tour?.steps?.[idx];

  // Di layar kecil sidebar tersembunyi: buka otomatis saat langkah yang menyorot sidebar,
  // dan tutup lagi begitu pindah ke langkah lain.
  useEffect(() => {
    if (!sidebarMobile) return;
    if (step?.sidebar) {
      if (!sidebarByTour.current) { sidebarByTour.current = true; openSidebar(); }
    } else if (sidebarByTour.current) {
      sidebarByTour.current = false;
      closeSidebar();
    }
  }, [step, sidebarMobile, openSidebar, closeSidebar]);

  // Cari & pantau posisi elemen target (menunggu muncul sampai ~3 detik)
  useEffect(() => {
    if (!step) return undefined;
    let scrolled = false;
    const measure = () => {
      let el = targetRef.current;
      if (!el || !document.contains(el)) el = targetRef.current = resolveTarget(step.target);
      if (!el) { setRect(null); return; }
      if (!scrolled) {
        scrolled = true;
        el.scrollIntoView({ block: 'center', inline: 'nearest', behavior: 'smooth' });
      }
      const r = el.getBoundingClientRect();
      setRect({ top: r.top, left: r.left, width: r.width, height: r.height });
    };
    targetRef.current = null;
    measure();
    const iv = setInterval(measure, 250);
    return () => clearInterval(iv);
  }, [step]);

  useEffect(() => {
    if (cardRef.current) setCardH(cardRef.current.offsetHeight);
  }, [idx, tour, rect]);

  // Keyboard: Esc = lewati, Enter/→ = lanjut, ← = kembali
  useEffect(() => {
    if (!tour) return undefined;
    const last = tour.steps.length - 1;
    const onKey = (e) => {
      if (e.key === 'Escape') finish();
      else if (e.key === 'Enter' || e.key === 'ArrowRight') { if (idx >= last) finish(); else setIdx(idx + 1); }
      else if (e.key === 'ArrowLeft' && idx > 0) setIdx(idx - 1);
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [tour, idx, finish]);

  if (!isWarga || !tour || !step) return null;

  const total = tour.steps.length;
  const isLast = idx === total - 1;
  const vw = window.innerWidth;
  const vh = window.innerHeight;
  const mobile = vw < 640;
  const cardW = Math.min(vw - 24, 440);
  const pad = 8;

  // Posisi kartu: di bawah target kalau muat, kalau tidak di atas; tanpa target → tengah.
  let cardStyle;
  if (mobile) {
    cardStyle = { left: 12, right: 12, bottom: 12 };
    // Kalau target tertutup kartu di bawah, pindahkan kartu ke atas layar —
    // kecuali langkah sidebar: sidebar setinggi layar, kartu tetap di bawah supaya
    // menu bagian atas (yang paling penting) tetap kelihatan.
    if (!step.sidebar && rect && rect.top + rect.height > vh - cardH - 24) cardStyle = { left: 12, right: 12, top: 12 };
  } else if (rect) {
    const below = rect.top + rect.height + pad + 16;
    const fitsBelow = below + cardH < vh - 12;
    const top = fitsBelow ? below : Math.max(12, rect.top - pad - 16 - cardH);
    const left = Math.min(Math.max(12, rect.left + rect.width / 2 - cardW / 2), vw - cardW - 12);
    cardStyle = { top, left, width: cardW };
  } else {
    cardStyle = { top: Math.max(12, (vh - cardH) / 2), left: (vw - cardW) / 2, width: cardW };
  }

  return createPortal(
    <div className="fixed inset-0" style={{ zIndex: 10000 }} role="dialog" aria-modal="true" aria-label="Panduan penggunaan">
      {/* Penghalang klik — supaya tidak salah tekan saat panduan tampil */}
      <div className="absolute inset-0" style={{ background: rect ? 'transparent' : 'rgba(0,0,0,0.65)' }} onClick={(e) => e.stopPropagation()} />

      {/* Sorotan elemen */}
      {rect && (
        <div
          style={{
            position: 'fixed',
            top: rect.top - pad,
            left: rect.left - pad,
            width: rect.width + pad * 2,
            height: rect.height + pad * 2,
            borderRadius: 14,
            border: '4px solid #f59e0b',
            boxShadow: '0 0 0 9999px rgba(0,0,0,0.65)',
            pointerEvents: 'none',
            transition: 'all .25s ease',
            animation: 'tour-pulse 1.6s ease-in-out infinite',
          }}
        />
      )}

      {/* Kartu petunjuk */}
      <div
        ref={cardRef}
        className="fixed bg-white dark:bg-gray-900 rounded-2xl shadow-2xl border-2 border-amber-400 p-5"
        style={cardStyle}
      >
        <div className="flex items-start justify-between gap-3">
          <h2 className="text-xl font-extrabold text-gray-900 dark:text-white leading-snug">{step.title}</h2>
          <span className="flex-shrink-0 text-sm font-semibold text-amber-700 bg-amber-100 rounded-full px-3 py-1">{idx + 1} / {total}</span>
        </div>
        <p className="mt-3 text-[17px] leading-relaxed text-gray-700 dark:text-gray-200">{step.body}</p>

        <div className="mt-5 flex items-center gap-3">
          <button
            type="button"
            onClick={finish}
            className="text-base font-medium text-gray-500 hover:text-gray-800 dark:hover:text-gray-200 px-2 py-3 min-h-[48px]"
          >
            Lewati
          </button>
          <div className="flex-1" />
          {idx > 0 && (
            <button
              type="button"
              onClick={() => setIdx(idx - 1)}
              className="flex items-center gap-1.5 text-base font-semibold text-gray-700 dark:text-gray-200 border-2 border-gray-300 dark:border-gray-600 rounded-xl px-4 py-3 min-h-[48px]"
            >
              <ArrowLeft size={18} /> Kembali
            </button>
          )}
          <button
            type="button"
            onClick={() => { if (isLast) finish(); else setIdx(idx + 1); }}
            className="flex items-center gap-1.5 text-base font-bold text-white bg-amber-500 hover:bg-amber-600 rounded-xl px-5 py-3 min-h-[48px] shadow"
          >
            {isLast ? (<><Check size={18} /> Mengerti</>) : (<>Lanjut <ArrowRight size={18} /></>)}
          </button>
        </div>
      </div>

      <style>{'@keyframes tour-pulse{0%,100%{border-color:#f59e0b}50%{border-color:#fde68a}}'}</style>
    </div>,
    document.body
  );
}
