import React from 'react'
import { Ico } from './Icons.jsx'
import { useCMS } from './cmsContent.jsx'

// Visual illustrations are tied to the FIRST 5 cards by their layout slot —
// vendor can edit text/tags/icon, but the bespoke graphics stay where they are.
const ILLUSTRATIONS = [
  // 0 — Inti (people list)
  (
    <div className="mod-illus" style={{background: 'rgba(255,255,255,0.04)', borderColor: 'rgba(255,255,255,0.1)'}}>
      <div style={{display:'flex', flexDirection:'column', gap:8}}>
        {[
          {n:'Hendra Wijaya', r:'Kepala Keluarga · 12 anggota', s:'aktif'},
          {n:'Suryani Putri', r:'Kepala Keluarga · 4 anggota',  s:'aktif'},
          {n:'Ahmad Fauzi',   r:'Pindah masuk · Sep 2025',       s:'baru'},
        ].map((p,i) => (
          <div key={i} style={{display:'flex', alignItems:'center', gap:12, padding:'10px 12px', background:'rgba(0,0,0,0.25)', borderRadius:8, fontSize:12}}>
            <div style={{width:28, height:28, borderRadius:'50%', background:'var(--coral)', display:'grid', placeItems:'center', fontFamily:'Instrument Serif', fontStyle:'italic', color:'var(--paper)', fontSize:13}}>{p.n[0]}</div>
            <div style={{flex:1}}>
              <div style={{fontWeight:500, color:'var(--paper)'}}>{p.n}</div>
              <div style={{fontSize:10.5, opacity:0.55, fontFamily:'Geist Mono', letterSpacing:'0.04em', marginTop:2}}>{p.r}</div>
            </div>
            <span style={{fontSize:10, fontFamily:'Geist Mono', padding:'2px 8px', border:'1px solid rgba(255,255,255,0.15)', borderRadius:99, opacity:0.7, textTransform:'uppercase', letterSpacing:'0.08em'}}>{p.s}</span>
          </div>
        ))}
      </div>
    </div>
  ),
  // 1 — Keuangan (invoice)
  (
    <div className="mod-illus">
      <div className="illus-invoice">
        <div className="row"><span>IURAN MEI · RT 07/RW 03</span><span>RP 50.000</span></div>
        <div className="row"><span>Kebersihan</span><span>25.000</span></div>
        <div className="row"><span>Keamanan</span><span>20.000</span></div>
        <div className="row"><span>Sosial</span><span>5.000</span></div>
        <div className="row"><span>QRIS · LUNAS 19/05</span><span style={{color:'var(--accent)'}}>✓ 50.000</span></div>
      </div>
    </div>
  ),
  // 2 — Surat (no illus)
  null,
  // 3 — Komunikasi (chat)
  (
    <div className="mod-illus illus-chat">
      <div className="bubble">
        Info kerja bakti hari Minggu, 06.30 di Pos Ronda. Mohon hadir.
        <div className="meta">Sekretariat · 19/05 07:14</div>
      </div>
      <div className="bubble me">
        Sudah baca 86 dari 128 KK
        <div className="meta" style={{color:'rgba(255,255,255,0.6)'}}>auto-tracking</div>
      </div>
    </div>
  ),
  // 4 — Agenda (calendar)
  (
    <div className="mod-illus" style={{minHeight: 120, padding: 14}}>
      <div style={{display:'grid', gridTemplateColumns:'repeat(7,1fr)', gap:4, fontSize:11}}>
        {['S','S','R','K','J','S','M'].map((d,i)=>(
          <div key={i} style={{textAlign:'center', fontFamily:'Geist Mono', color:'var(--muted)', fontSize:9, letterSpacing:'0.1em'}}>{d}</div>
        ))}
        {Array.from({length:21}).map((_,i)=>{
          const active = [3,9,12,17].includes(i)
          const today = i===10
          return <div key={i} style={{
            aspectRatio:'1', display:'grid', placeItems:'center',
            background: today ? 'var(--ink)' : active ? 'var(--accent)' : 'transparent',
            color: today ? 'var(--paper)' : active ? 'var(--paper)' : 'var(--ink-2)',
            borderRadius: 6, fontFamily:'Geist Mono', fontSize:11,
            border: !today && !active ? '1px solid var(--line)' : 'none'
          }}>{i+1}</div>
        })}
      </div>
    </div>
  ),
]

// Grid span class per card index — preserves the existing layout
const SPAN_CLASSES = ['span-6 dark', 'span-6', 'span-4', 'span-4', 'span-4', 'span-6', 'span-6']

export default function Modules() {
  const c = useCMS('modules')
  const items = c.items || []
  return (
    <section className="section" id="modul">
      <div className="container">
        <div className="section-head">
          <span className="kicker">{c.kicker}</span>
          <h2 dangerouslySetInnerHTML={{ __html: c.title_html }} />
          <p>{c.description}</p>
        </div>

        <div className="modules">
          {items.map((m, i) => {
            const Icon = Ico[m.icon] || Ico.Users
            const span = SPAN_CLASSES[i] || 'span-4'
            const illus = ILLUSTRATIONS[i]
            return (
              <div key={i} className={'mod-card ' + span}>
                <span className="num">{m.number}</span>
                <div className="mod-icon"><Icon /></div>
                <h3 dangerouslySetInnerHTML={{ __html: m.title_html }} />
                {m.description && <p>{m.description}</p>}
                {illus}
                {(m.tags || []).length > 0 && (
                  <div className="tag-list">
                    {m.tags.map((t, j) => (
                      <span key={j} className="tag" dangerouslySetInnerHTML={{ __html: t }} />
                    ))}
                  </div>
                )}
              </div>
            )
          })}
        </div>
      </div>
    </section>
  )
}
