import React, { useState, useEffect, useCallback } from 'react';
import './ImageGallery.css';

/* ── Lightbox ──────────────────────────────────────────────── */
export function Lightbox({ images, startIndex, onClose }) {
  const [current, setCurrent] = useState(startIndex);

  const prev = useCallback(() => setCurrent(i => (i - 1 + images.length) % images.length), [images.length]);
  const next = useCallback(() => setCurrent(i => (i + 1) % images.length), [images.length]);

  useEffect(() => {
    const handler = (e) => {
      if (e.key === 'Escape') onClose();
      if (e.key === 'ArrowLeft') prev();
      if (e.key === 'ArrowRight') next();
    };
    document.addEventListener('keydown', handler);
    document.body.style.overflow = 'hidden';
    return () => {
      document.removeEventListener('keydown', handler);
      document.body.style.overflow = '';
    };
  }, [onClose, prev, next]);

  return (
    <div className="lb-overlay" onClick={onClose}>
      {/* Close */}
      <button className="lb-close" onClick={onClose}>✕</button>

      {/* Counter */}
      <div className="lb-counter">{current + 1} / {images.length}</div>

      {/* Prev */}
      {images.length > 1 && (
        <button className="lb-arrow lb-prev" onClick={e => { e.stopPropagation(); prev(); }}>‹</button>
      )}

      {/* Image */}
      <div className="lb-img-wrap" onClick={e => e.stopPropagation()}>
        <img
          className="lb-img"
          src={images[current]}
          alt={`Foto ${current + 1}`}
          draggable={false}
        />
      </div>

      {/* Next */}
      {images.length > 1 && (
        <button className="lb-arrow lb-next" onClick={e => { e.stopPropagation(); next(); }}>›</button>
      )}

      {/* Thumbnails strip */}
      {images.length > 1 && (
        <div className="lb-thumbs" onClick={e => e.stopPropagation()}>
          {images.map((img, i) => (
            <div
              key={i}
              className={`lb-thumb ${i === current ? 'active' : ''}`}
              onClick={() => setCurrent(i)}
            >
              <img src={img} alt={`thumb ${i + 1}`} />
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

/* ── Gallery Grid (inside DetailModal) ─────────────────────── */
export function ImageGalleryGrid({ images, listingId, onDelete, canDelete = false }) {
  const [lightboxIdx, setLightboxIdx] = useState(null);

  if (!images || images.length === 0) return null;

  return (
    <div className="ig-section">
      <h4 className="ig-section-title">📷 Foto ({images.length})</h4>
      <div className={`ig-grid ig-grid-${Math.min(images.length, 4)}`}>
        {images.slice(0, 4).map((img, i) => (
          <div
            key={i}
            className={`ig-cell ${i === 3 && images.length > 4 ? 'ig-more' : ''}`}
            onClick={() => setLightboxIdx(i)}
          >
            <img src={img} alt={`Foto ${i + 1}`} />
            {i === 3 && images.length > 4 && (
              <div className="ig-more-overlay">+{images.length - 4}</div>
            )}
            {canDelete && (
              <button
                className="ig-del-btn"
                onClick={e => { e.stopPropagation(); onDelete && onDelete(i); }}
                title="Hapus foto"
              >
                ✕
              </button>
            )}
          </div>
        ))}
      </div>

      {lightboxIdx !== null && (
        <Lightbox
          images={images}
          startIndex={lightboxIdx}
          onClose={() => setLightboxIdx(null)}
        />
      )}
    </div>
  );
}

/* ── Inline mini-gallery for Card (1–3 thumbnails + count) ── */
export function CardImageStrip({ images, onClick }) {
  if (!images || images.length === 0) return null;

  const shown = images.slice(0, 3);
  const extra = images.length - 3;

  return (
    <div
      className="cis-wrap"
      onClick={e => { e.stopPropagation(); onClick && onClick(); }}
      title={`${images.length} foto tersedia`}
    >
      <span className="cis-icon">🖼️</span>
      <div className="cis-thumbs">
        {shown.map((img, i) => (
          <div key={i} className="cis-thumb">
            <img src={img} alt="" />
          </div>
        ))}
        {extra > 0 && (
          <div className="cis-extra">+{extra}</div>
        )}
      </div>
      <span className="cis-label">{images.length} foto</span>
    </div>
  );
}

/* ── Upload zone (inside ListingForm) ───────────────────────── */
export function ImageUploadZone({ existingImages = [], listingId, onChange }) {
  const [previews, setPreviews]   = useState(existingImages);
  const [dragging, setDragging]   = useState(false);
  const [lightboxIdx, setLightboxIdx] = useState(null);

  // Sync if existingImages changes (edit mode)
  React.useEffect(() => { setPreviews(existingImages); }, [existingImages.length]);

  const addFiles = (files) => {
    const valid = Array.from(files).filter(f => f.type.startsWith('image/'));
    if (!valid.length) return;

    const remaining = 8 - previews.length;
    if (remaining <= 0) return;

    const toAdd = valid.slice(0, remaining);
    const newPreviews = toAdd.map(f => ({
      file: f,
      url:  URL.createObjectURL(f),
      name: f.name,
    }));

    const updated = [...previews, ...newPreviews];
    setPreviews(updated);
    onChange && onChange(updated);
  };

  const removePreview = (i) => {
    const updated = previews.filter((_, idx) => idx !== i);
    setPreviews(updated);
    onChange && onChange(updated);
  };

  const handleDrop = (e) => {
    e.preventDefault();
    setDragging(false);
    addFiles(e.dataTransfer.files);
  };

  return (
    <div className="iuz-wrap">
      <div className="iuz-header">
        <span className="iuz-title">📷 Foto Galeri</span>
        <span className="iuz-count">{previews.length} / 8 foto</span>
      </div>

      {/* Preview grid */}
      {previews.length > 0 && (
        <div className="iuz-preview-grid">
          {previews.map((p, i) => (
            <div key={i} className="iuz-preview-cell" onClick={() => setLightboxIdx(i)}>
              <img src={p.url || p} alt={p.name || `foto ${i + 1}`} />
              <button
                className="iuz-remove-btn"
                onClick={e => { e.stopPropagation(); removePreview(i); }}
                title="Hapus foto"
              >
                ✕
              </button>
              {i === 0 && <span className="iuz-main-badge">Utama</span>}
            </div>
          ))}

          {/* Add more slot */}
          {previews.length < 8 && (
            <label className="iuz-add-slot">
              <input
                type="file"
                accept="image/*"
                multiple
                style={{ display: 'none' }}
                onChange={e => addFiles(e.target.files)}
              />
              <span className="iuz-add-icon">+</span>
            </label>
          )}
        </div>
      )}

      {/* Drop zone — shown when no photos or as add area */}
      {previews.length === 0 && (
        <label
          className={`iuz-dropzone ${dragging ? 'dragging' : ''}`}
          onDragOver={e => { e.preventDefault(); setDragging(true); }}
          onDragLeave={() => setDragging(false)}
          onDrop={handleDrop}
        >
          <input
            type="file"
            accept="image/*"
            multiple
            style={{ display: 'none' }}
            onChange={e => addFiles(e.target.files)}
          />
          <div className="iuz-drop-icon">🖼️</div>
          <div className="iuz-drop-text">
            <strong>Klik atau seret gambar ke sini</strong>
            <span>JPG, PNG, WEBP · Maks 5MB · Maks 8 foto</span>
          </div>
        </label>
      )}

      {/* Lightbox */}
      {lightboxIdx !== null && (
        <Lightbox
          images={previews.map(p => p.url || p)}
          startIndex={lightboxIdx}
          onClose={() => setLightboxIdx(null)}
        />
      )}
    </div>
  );
}
