import { useState, useEffect, useCallback } from 'react';
import { API_BASE_URL } from '../config/api';

// Sama seperti formatAsalRtRw() di TamuLaporPage.jsx — dipakai supaya notifikasi
// dari RW/Kelurahan menunjukkan asal RT/RW warga dengan format yang konsisten.
const stripPrefix = (name, prefix) => (name ? name.replace(new RegExp(`^${prefix}\\s*`, 'i'), '').trim() : null);
function formatAsalRtRw(namaRt, namaRw) {
  const rt = stripPrefix(namaRt, 'RT');
  const rw = stripPrefix(namaRw, 'RW');
  if (!rt && !rw) return null;
  if (rt && rw) return `RT ${rt}/RW ${rw}`;
  if (rt) return `RT ${rt}`;
  return `RW ${rw}`;
}

// Label & warna badge per sumber notifikasi — dipakai bareng oleh dropdown
// notifikasi di Header dan halaman "Semua Notifikasi" biar konsisten.
export const NOTIF_SOURCE_META = {
  kelurahan:   { label: 'Kelurahan',   badgeClass: 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/40 dark:text-emerald-400' },
  rw:          { label: 'RW',          badgeClass: 'bg-blue-100 text-blue-700 dark:bg-blue-900/40 dark:text-blue-400' },
  tamu_lapor:  { label: 'Lapor Tamu',  badgeClass: 'bg-orange-100 text-orange-700 dark:bg-orange-900/40 dark:text-orange-400' },
  surat:       { label: 'Surat Resmi', badgeClass: 'bg-purple-100 text-purple-700 dark:bg-purple-900/40 dark:text-purple-400' },
  surat_warga: { label: 'Surat Resmi', badgeClass: 'bg-purple-100 text-purple-700 dark:bg-purple-900/40 dark:text-purple-400' },
  pengaduan:   { label: 'Pengaduan',   badgeClass: 'bg-red-100 text-red-700 dark:bg-red-900/40 dark:text-red-400' },
  pengaduan_warga: { label: 'Pengaduan', badgeClass: 'bg-red-100 text-red-700 dark:bg-red-900/40 dark:text-red-400' },
  informasi:   { label: 'Informasi',   badgeClass: 'bg-sky-100 text-sky-700 dark:bg-sky-900/40 dark:text-sky-400' },
  surat_edaran: { label: 'Surat Edaran', badgeClass: 'bg-indigo-100 text-indigo-700 dark:bg-indigo-900/40 dark:text-indigo-400' },
  default:     { label: 'Pengumuman',  badgeClass: 'bg-gray-100 text-gray-700 dark:bg-gray-800 dark:text-gray-300' },
};

export function getNotifSourceMeta(n) {
  return NOTIF_SOURCE_META[n?._from] || NOTIF_SOURCE_META.default;
}

// Tentukan menu tujuan ketika sebuah notifikasi diklik, tergantung sumber & role.
export function getNotifDestination(n, { isPengurusRW, isPengurusKelurahan, isRTAdmin } = {}) {
  if (n._from === 'tamu_lapor') return { path: '/tamu-lapor' };
  if (n._from === 'surat_warga') return { path: '/ajukan-surat' };
  if (n._from === 'surat') return { path: '/surat-resmi' };
  if (n._from === 'surat_edaran') {
    return { path: isPengurusKelurahan ? '/kelurahan/broadcast?tab=surat' : isPengurusRW ? '/rw/announcements?tab=surat' : '/pengumuman?tab=surat' };
  }
  if (n._from === 'informasi') return { path: `/informasi-warga/${n._informasiId}` };
  if (n._from === 'pengaduan') {
    return { path: isPengurusKelurahan ? '/kelurahan/complaints' : isPengurusRW ? '/rw/complaints' : '/pengaduan' };
  }
  if (n._from === 'pengaduan_warga') return { path: '/pengaduan' };
  if (isPengurusRW) return { path: '/rw/announcements' };
  if (isRTAdmin) {
    const tab = n._from === 'kelurahan' ? 'kel' : 'rw';
    return { path: '/pengumuman', state: { viewItem: n, tab } };
  }
  return { path: '/pengumuman', state: { viewItem: n } };
}

// Fetch gabungan semua notifikasi sesuai role (RT/RW/Kelurahan/Warga).
// Dipakai oleh dropdown notifikasi di Header dan halaman "Semua Notifikasi"
// supaya keduanya selalu menampilkan data yang sama persis.
export function useNotifications(token, user) {
  const [notifList, setNotifList] = useState([]);
  const [loading, setLoading] = useState(false);

  const isWarga = user?.role === 'warga';
  const isRTAdmin = user?.role === 'admin';
  const isPengurusRW = user?.role === 'pengurus_rw';
  const isPengurusKelurahan = user?.role === 'pengurus_kelurahan';
  const showNotifBell = isWarga || isRTAdmin || isPengurusRW || isPengurusKelurahan;

  const fetchInbox = useCallback(async () => {
    if (!showNotifBell || !token) { setNotifList([]); return; }
    setLoading(true);

    const fetchTamuNotifs = async () => {
      try {
        const res = await fetch(`${API_BASE_URL}/api/tamu-lapor?status=Baru`, { headers: { Authorization: `Bearer ${token}` } });
        const json = res.ok ? await res.json() : [];
        return (Array.isArray(json) ? json : []).map(t => ({
          id: `tamu-${t.id}`,
          judul: `Lapor Tamu: ${t.kategori}${t.nama_tamu ? ` — ${t.nama_tamu}` : ''}`,
          isi: [
            t.pelapor_nama,
            t.blok_rumah ? `Blok ${t.blok_rumah}` : null,
            t.alasan,
            formatAsalRtRw(t.tenant_nama_rt, t.tenant_nama_rw),
          ].filter(Boolean).join(' · '),
          published_at: t.created_at,
          _from: 'tamu_lapor',
        }));
      } catch { return []; }
    };
    // RT: surat berstatus 'pending' (baru masuk, butuh aksi RT)
    // RW: pakai inbox=true (surat berstatus rt_approved, butuh aksi RW)
    // Warga: surat milik sendiri yang statusnya sudah final (approved/rejected)
    const fetchSuratNotifs = async (queryParam) => {
      try {
        const res = await fetch(`${API_BASE_URL}/api/surat-resmi/permohonan${queryParam}`, { headers: { Authorization: `Bearer ${token}` } });
        const json = res.ok ? await res.json() : [];
        let items = Array.isArray(json) ? json : [];
        if (isWarga) items = items.filter(p => ['approved', 'rejected'].includes(p.status));
        return items.map(p => ({
          id: `surat-${p.id}`,
          judul: isWarga
            ? (p.status === 'approved' ? `Surat Terbit: ${p.jenis_surat}` : `Surat Ditolak: ${p.jenis_surat}`)
            : `Ajukan Surat: ${p.jenis_surat}`,
          isi: isWarga
            ? (p.status === 'approved' ? `No. ${p.nomor_surat || '-'}` : (p.catatan || 'Permohonan ditolak'))
            : [p.pemohon_nama, formatAsalRtRw(p.tenant_name, p.rw_name)].filter(Boolean).join(' · '),
          published_at: p.issued_at || p.updated_at || p.created_at,
          _from: isWarga ? 'surat_warga' : 'surat',
        }));
      } catch { return []; }
    };
    // Pengaduan: RT lihat yang eskalasi='RT' & masih open, RW/Kelurahan pakai endpoint monitoring masing-masing
    const fetchPengaduanNotifs = async (url, filterEskalasi) => {
      try {
        const res = await fetch(url, { headers: { Authorization: `Bearer ${token}` } });
        const json = res.ok ? await res.json() : [];
        let items = Array.isArray(json) ? json : (json.data || []);
        if (filterEskalasi) items = items.filter(p => p.eskalasi === filterEskalasi);
        return items.map(p => ({
          id: `pengaduan-${p.id}`,
          judul: `Pengaduan: ${p.judul}`,
          isi: [p.nama_pelapor, p.blok_rumah, p.kategori, formatAsalRtRw(p.rt_name, p.rw_name)].filter(Boolean).join(' · '),
          published_at: p.updated_at || p.created_at,
          _from: 'pengaduan',
        }));
      } catch { return []; }
    };
    // Informasi: warga lihat informasi terbaru yang aktif di RT-nya (top 5 per kategori dari endpoint dashboard)
    const fetchInformasiNotifs = async () => {
      try {
        const res = await fetch(`${API_BASE_URL}/api/informasi/warga/dashboard`, { headers: { Authorization: `Bearer ${token}` } });
        if (!res.ok) return [];
        const json = await res.json();
        const items = (json.kategori || []).flatMap(k => k.data || []);
        return items.map(i => ({
          id: `informasi-${i.id}`,
          judul: `Informasi: ${i.judul}`,
          isi: i.kategori,
          published_at: i.created_at || i.tanggal,
          _from: 'informasi',
          _informasiId: i.id,
        }));
      } catch { return []; }
    };
    // Pengaduan (warga): status pengaduan milik sendiri yang sudah diubah RT/RW/Kelurahan (bukan 'open' lagi)
    const fetchPengaduanStatusNotifsForWarga = async () => {
      try {
        const res = await fetch(`${API_BASE_URL}/api/pengaduan`, { headers: { Authorization: `Bearer ${token}` } });
        const json = res.ok ? await res.json() : [];
        const items = (Array.isArray(json) ? json : (json.data || [])).filter(p => p.status !== 'open');
        const statusLabel = { in_progress: 'Sedang Ditangani', resolved: 'Selesai Ditangani', closed: 'Ditutup' };
        return items.map(p => ({
          id: `pengaduan-status-${p.id}`,
          judul: `Pengaduan: ${p.judul}`,
          isi: `Status: ${statusLabel[p.status] || p.status}${p.eskalasi ? ` (${p.eskalasi})` : ''}`,
          published_at: p.updated_at || p.created_at,
          _from: 'pengaduan_warga',
        }));
      } catch { return []; }
    };

    // Surat Edaran (BEDA dengan Surat Resmi/permohonan di atas): surat edaran
    // yang sudah dipublikasikan RT ke audiens terkait (Warga/RW/Kelurahan).
    // Sebelum dipublikasikan, surat tidak akan muncul di endpoint ini sama sekali.
    const fetchSuratEdaranNotifs = async (url, publishedAtKey) => {
      try {
        const res = await fetch(url, { headers: { Authorization: `Bearer ${token}` } });
        if (!res.ok) return [];
        const json = await res.json();
        const items = Array.isArray(json) ? json : (json.data || []);
        return items.slice(0, 10).map(s => ({
          id: `surat-edaran-${s.id}`,
          judul: `Surat Edaran: ${s.judul_surat}`,
          isi: s.creator_name ? `Dari ${s.creator_name}` : '',
          published_at: s[publishedAtKey] || s.updated_at || s.created_at,
          _from: 'surat_edaran',
        }));
      } catch { return []; }
    };

    try {
      if (isRTAdmin) {
        const [rwRes, kelRes, tamuNotifs, suratNotifs, pengaduanNotifs] = await Promise.all([
          fetch(`${API_BASE_URL}/api/pengumuman/inbox-rt`, { headers: { Authorization: `Bearer ${token}` } }),
          fetch(`${API_BASE_URL}/api/pengumuman/inbox-rt-kelurahan`, { headers: { Authorization: `Bearer ${token}` } }),
          fetchTamuNotifs(),
          fetchSuratNotifs('?status=pending'),
          fetchPengaduanNotifs(`${API_BASE_URL}/api/pengaduan?eskalasi=RT&status=open`, null),
        ]);
        const rwJson = rwRes.ok ? await rwRes.json() : { data: [] };
        const kelJson = kelRes.ok ? await kelRes.json() : { data: [] };
        const combined = [
          ...(rwJson.data || []).map(n => ({ ...n, _from: 'rw' })),
          ...(kelJson.data || []).map(n => ({ ...n, _from: 'kelurahan' })),
          ...tamuNotifs,
          ...suratNotifs,
          ...pengaduanNotifs,
        ].sort((a, b) => new Date(b.published_at || b.created_at) - new Date(a.published_at || a.created_at));
        setNotifList(combined);
      } else if (isPengurusRW) {
        const [res, tamuNotifs, suratNotifs, pengaduanNotifs, suratEdaranNotifs] = await Promise.all([
          fetch(`${API_BASE_URL}/api/pengumuman/inbox-rw`, { headers: { Authorization: `Bearer ${token}` } }),
          fetchTamuNotifs(),
          fetchSuratNotifs('?inbox=true'),
          fetchPengaduanNotifs(`${API_BASE_URL}/api/rw/complaints?eskalasi=RW&status=open`, null),
          fetchSuratEdaranNotifs(`${API_BASE_URL}/api/rw/letters`, 'published_rw_at'),
        ]);
        const json = res.ok ? await res.json() : { data: [] };
        const combined = [
          ...(json.data || []),
          ...tamuNotifs,
          ...suratNotifs,
          ...pengaduanNotifs,
          ...suratEdaranNotifs,
        ].sort((a, b) => new Date(b.published_at || b.created_at) - new Date(a.published_at || a.created_at));
        setNotifList(combined);
      } else if (isPengurusKelurahan) {
        const [suratNotifs, pengaduanNotifs, suratEdaranNotifs] = await Promise.all([
          fetchSuratNotifs('?inbox=true'),
          fetchPengaduanNotifs(`${API_BASE_URL}/api/kelurahan/complaints?status=open`, 'Kelurahan'),
          fetchSuratEdaranNotifs(`${API_BASE_URL}/api/kelurahan/letters`, 'published_kelurahan_at'),
        ]);
        const combined = [...suratNotifs, ...pengaduanNotifs, ...suratEdaranNotifs]
          .sort((a, b) => new Date(b.published_at || b.created_at) - new Date(a.published_at || a.created_at));
        setNotifList(combined);
      } else {
        const [res, suratNotifs, informasiNotifs, pengaduanStatusNotifs, suratEdaranNotifs] = await Promise.all([
          fetch(`${API_BASE_URL}/api/pengumuman/inbox`, { headers: { Authorization: `Bearer ${token}` } }),
          isWarga ? fetchSuratNotifs('') : Promise.resolve([]),
          isWarga ? fetchInformasiNotifs() : Promise.resolve([]),
          isWarga ? fetchPengaduanStatusNotifsForWarga() : Promise.resolve([]),
          isWarga ? fetchSuratEdaranNotifs(`${API_BASE_URL}/api/surat`, 'published_warga_at') : Promise.resolve([]),
        ]);
        let combined = [...suratNotifs, ...informasiNotifs, ...pengaduanStatusNotifs, ...suratEdaranNotifs];
        if (res.ok) {
          const json = await res.json();
          combined = [...(json.data || []), ...combined]
            .sort((a, b) => new Date(b.published_at || b.created_at) - new Date(a.published_at || a.created_at));
        }
        setNotifList(combined);
      }
    } catch (_) { /* silent */ }
    setLoading(false);
  }, [token, showNotifBell, isRTAdmin, isPengurusRW, isPengurusKelurahan, isWarga]);

  // Polling berkala supaya badge notifikasi update realtime tanpa perlu refresh manual
  // (mis. saat ada pesan/laporan/pengaduan baru masuk dari user lain).
  useEffect(() => {
    fetchInbox();
    const id = setInterval(fetchInbox, 10000); // setiap 10 detik
    return () => clearInterval(id);
  }, [fetchInbox]);

  return {
    notifList,
    loading,
    refetch: fetchInbox,
    isWarga, isRTAdmin, isPengurusRW, isPengurusKelurahan, showNotifBell,
  };
}
