import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { useParams, useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { API_BASE_URL } from '../config/api';
import { ArrowLeft, Pencil, Video } from 'lucide-react';
import { Lightbox } from '../components/ImageGallery';

const formatDate = (val) => {
  if (!val) return '-';
  return new Date(val).toLocaleDateString('id-ID', { day: '2-digit', month: 'long', year: 'numeric' });
};

// Ubah link YouTube (watch / youtu.be / shorts) jadi embed URL. Selain YouTube, tampilkan sebagai link biasa.
const getYoutubeEmbed = (url) => {
  if (!url) return null;
  try {
    const u = new URL(url);
    let videoId = null;
    if (u.hostname.includes('youtu.be')) {
      videoId = u.pathname.slice(1);
    } else if (u.hostname.includes('youtube.com')) {
      if (u.pathname.startsWith('/shorts/')) videoId = u.pathname.split('/')[2];
      else videoId = u.searchParams.get('v');
    }
    return videoId ? `https://www.youtube.com/embed/${videoId}` : null;
  } catch {
    return null;
  }
};

const ORIGIN_BADGE_CLS = {
  RT: 'bg-blue-100 text-blue-700 border-blue-300 dark:bg-blue-900/30 dark:text-blue-400 dark:border-blue-700',
  RW: 'bg-purple-100 text-purple-700 border-purple-300 dark:bg-purple-900/30 dark:text-purple-400 dark:border-purple-700',
  Kelurahan: 'bg-emerald-100 text-emerald-700 border-emerald-300 dark:bg-emerald-900/30 dark:text-emerald-400 dark:border-emerald-700',
};

function OriginBadge({ type, name }) {
  if (!type) return null;
  return (
    <span className={`text-[10px] px-2 py-0.5 rounded-full font-semibold border ${ORIGIN_BADGE_CLS[type] || 'bg-gray-100 text-gray-600 border-gray-300'}`}>
      {type}{name ? ` · ${name}` : ''}
    </span>
  );
}

export default function InformasiDetailAdmin({ basePath = '/informasi' }) {
  const { id } = useParams();
  const { token } = useAuth();
  const navigate = useNavigate();
  const [item, setItem] = useState(null);
  const [loading, setLoading] = useState(true);
  const [notFound, setNotFound] = useState(false);
  const [lightboxIdx, setLightboxIdx] = useState(null);

  useEffect(() => {
    if (!id || !token) return;
    setLoading(true);
    setNotFound(false);
    axios.get(`${API_BASE_URL}/api/informasi/${id}`, {
      headers: { Authorization: `Bearer ${token}` }
    }).then(res => setItem(res.data))
      .catch(() => setNotFound(true))
      .finally(() => setLoading(false));
  }, [token, id]);

  const embedUrl = item ? getYoutubeEmbed(item.video_url) : null;

  return (
    <div className="p-4 sm:p-6 max-w-3xl mx-auto">
      <div className="flex items-center justify-between mb-4">
        <button
          onClick={() => navigate(basePath)}
          className="flex items-center gap-2 text-sm text-gray-600 dark:text-gray-300 hover:text-gray-900 dark:hover:text-white"
        >
          <ArrowLeft className="w-4 h-4" /> Kembali ke Informasi
        </button>
        {item && item.is_own && (
          <button
            onClick={() => navigate(basePath, { state: { editId: item.id } })}
            className="flex items-center gap-2 text-sm font-medium text-[var(--rw-primary)] hover:text-[#e15c47]"
          >
            <Pencil className="w-4 h-4" /> Edit
          </button>
        )}
      </div>

      {loading ? (
        <div className="py-16 text-center">
          <div className="w-8 h-8 border-4 border-blue-500 border-t-transparent rounded-full animate-spin mx-auto" />
        </div>
      ) : notFound || !item ? (
        <div className="bg-[var(--rw-bg-card)] dark:bg-gray-900 border border-[var(--rw-border)] dark:border-gray-700 rounded-xl py-16 text-center text-gray-400">
          Informasi tidak ditemukan.
        </div>
      ) : (
        <div className="bg-[var(--rw-bg-card)] dark:bg-gray-900 border border-[var(--rw-border)] dark:border-gray-700 rounded-xl p-5 sm:p-6 space-y-4">
          {item.gambar_header && (
            <img
              src={`${API_BASE_URL}/${item.gambar_header}`}
              alt=""
              className="w-full max-h-[70vh] object-contain rounded-xl bg-black/5 dark:bg-black/20"
            />
          )}

          <div>
            <div className="flex items-center gap-2 flex-wrap mb-1">
              <span className="text-[10px] px-2 py-0.5 rounded-full font-semibold bg-blue-100 text-blue-700 dark:bg-blue-900/40 dark:text-blue-300">
                {item.kategori}
              </span>
              <OriginBadge type={item.origin_tenant_type} name={item.origin_tenant_name} />
              {item.pin && (
                <span className="text-[10px] px-2 py-0.5 rounded-full font-semibold bg-[var(--rw-primary)]/15 text-[var(--rw-primary)]">
                  Pin
                </span>
              )}
              {!item.aktif && (
                <span className="text-[10px] px-2 py-0.5 rounded-full font-semibold bg-gray-200 text-gray-600 dark:bg-gray-700 dark:text-gray-300">
                  Nonaktif (belum publish)
                </span>
              )}
            </div>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white mt-1">{item.judul}</h1>
            <p className="text-sm text-gray-500 dark:text-gray-400 mt-1">
              {formatDate(item.tanggal)}{item.creator_name ? ` · Oleh ${item.creator_name}` : ''}
            </p>
          </div>

          {item.konten && (
            <p className="text-sm text-gray-700 dark:text-gray-300 whitespace-pre-line leading-relaxed">
              {item.konten}
            </p>
          )}

          {item.video_url && (
            embedUrl ? (
              <div className="aspect-video rounded-xl overflow-hidden">
                <iframe
                  src={embedUrl}
                  title="Video Informasi"
                  className="w-full h-full"
                  allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                  allowFullScreen
                />
              </div>
            ) : (
              <a href={item.video_url} target="_blank" rel="noreferrer" className="text-blue-600 dark:text-blue-400 text-sm underline flex items-center gap-1">
                <Video className="w-4 h-4" /> Lihat Video
              </a>
            )
          )}

          {item.galeri?.length > 0 && (
            <div>
              <p className="text-sm font-semibold text-gray-900 dark:text-gray-100 mb-2">Galeri</p>
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-2">
                {item.galeri.map((g, i) => (
                  <img
                    key={i}
                    src={`${API_BASE_URL}/${g}`}
                    alt=""
                    className="w-full h-32 object-cover rounded-lg cursor-pointer hover:opacity-90 transition-opacity"
                    onClick={() => setLightboxIdx(i)}
                  />
                ))}
              </div>
              {lightboxIdx !== null && (
                <Lightbox
                  images={item.galeri.map(g => `${API_BASE_URL}/${g}`)}
                  startIndex={lightboxIdx}
                  onClose={() => setLightboxIdx(null)}
                />
              )}
            </div>
          )}
        </div>
      )}
    </div>
  );
}
