import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';
import { useAuth } from '../../contexts/AuthContext';
import { useColorTheme } from '../../contexts/ColorThemeContext';
import { API_BASE_URL } from '../../config/api';
import { toast } from '@/components/ui/sonner';
import {
  Settings, Twitter, Facebook, Youtube, Instagram, Music2, MessageCircle, Save, RefreshCw,
  Image, Upload, Loader2, Palette, Check, Globe, Trash2, ImagePlus,
} from 'lucide-react';

const SOCIAL_FIELDS = [
  { key: 'twitter',   label: 'Twitter / X', Icon: Twitter,       placeholder: 'https://x.com/namaanda' },
  { key: 'facebook',  label: 'Facebook',    Icon: Facebook,      placeholder: 'https://facebook.com/namaanda' },
  { key: 'youtube',   label: 'YouTube',     Icon: Youtube,       placeholder: 'https://youtube.com/@namaanda' },
  { key: 'instagram', label: 'Instagram',   Icon: Instagram,     placeholder: 'https://instagram.com/namaanda' },
  { key: 'tiktok',    label: 'TikTok',      Icon: Music2,        placeholder: 'https://tiktok.com/@namaanda' },
  { key: 'discord',   label: 'Discord',     Icon: MessageCircle, placeholder: 'https://discord.gg/kodeundangan' },
];

const EMPTY = Object.fromEntries(
  SOCIAL_FIELDS.flatMap(({ key }) => [[`social_${key}`, ''], [`social_${key}_enabled`, true]])
);

const resolveUrl = (url) => {
  if (!url) return null;
  if (url.startsWith('http')) return url;
  return `${API_BASE_URL}${url}`;
};

function LoginLayoutPreview({ id }) {
  if (id === 'split-center') {
    return (
      <div className="w-full h-16 rounded-lg overflow-hidden flex border border-[var(--rw-border)] dark:border-gray-600">
        <div className="w-1/2 bg-emerald-500 flex items-center justify-center">
          <div className="w-4 h-4 rounded bg-white/80" />
        </div>
        <div className="w-1/2 bg-white flex flex-col items-center justify-center gap-1">
          <div className="w-8 h-1 rounded bg-gray-300" />
          <div className="w-8 h-1 rounded bg-gray-200" />
        </div>
      </div>
    );
  }
  if (id === 'elegant') {
    return (
      <div className="w-full h-16 rounded-lg overflow-hidden relative bg-gradient-to-br from-emerald-500 via-emerald-800 to-black flex items-center justify-center">
        <div className="w-12 h-11 rounded-lg bg-white/15 border border-white/30 flex flex-col items-center justify-center gap-1">
          <div className="w-3 h-3 rounded bg-white/70" />
          <div className="w-6 h-1 rounded bg-white/50 mt-1" />
        </div>
      </div>
    );
  }
  return (
    <div className="w-full h-16 rounded-lg overflow-hidden flex border border-[var(--rw-border)] dark:border-gray-600">
      <div className="w-[58%] bg-emerald-500 flex items-center justify-center">
        <div className="w-4 h-4 rounded bg-white/80" />
      </div>
      <div className="flex-1 bg-white flex flex-col items-center justify-center gap-1">
        <div className="w-8 h-1 rounded bg-gray-300" />
        <div className="w-8 h-1 rounded bg-gray-200" />
      </div>
    </div>
  );
}

function ThemeSwatch({ colors }) {
  return (
    <div className="flex items-center -space-x-1.5">
      {['bg_page', 'primary', 'primary_hover', 'text_accent'].map((k, i) => (
        <span
          key={k}
          className="w-4 h-4 rounded-full border-2 border-white shadow-sm"
          style={{ backgroundColor: colors[k], zIndex: 4 - i }}
        />
      ))}
    </div>
  );
}

export default function KonfigurasiSetting() {
  const { token } = useAuth();
  const authHeader = { Authorization: `Bearer ${token}` };
  const { reload: reloadColorTheme } = useColorTheme();

  const [form, setForm] = useState(EMPTY);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  // ── Identitas (logo aplikasi + logo kop surat) & Tema ──────────────────
  const [logoUrl, setLogoUrl]       = useState(null);
  const [kopLogoUrl, setKopLogoUrl] = useState(null);
  const [logoPreview, setLogoPreview]       = useState(null);
  const [kopLogoPreview, setKopLogoPreview] = useState(null);
  const [uploadingLogo, setUploadingLogo]       = useState(false);
  const [uploadingKopLogo, setUploadingKopLogo] = useState(false);
  const uploadRef    = useRef(null);
  const kopUploadRef = useRef(null);

  const [loginBgUrl, setLoginBgUrl]         = useState(null);
  const [loginBgPreview, setLoginBgPreview] = useState(null);
  const [uploadingLoginBg, setUploadingLoginBg] = useState(false);
  const [removingLoginBg, setRemovingLoginBg]   = useState(false);
  const loginBgUploadRef = useRef(null);

  const [availableThemes, setAvailableThemes] = useState([]);
  const [selectedThemeId, setSelectedThemeId] = useState('default');
  const [applyingTheme, setApplyingTheme] = useState(null);

  const [availableLoginLayouts, setAvailableLoginLayouts] = useState([]);
  const [selectedLoginLayoutId, setSelectedLoginLayoutId] = useState('default');
  const [applyingLoginLayout, setApplyingLoginLayout] = useState(null);

  const [loginCaption, setLoginCaption]     = useState('');
  const [savingCaption, setSavingCaption]   = useState(false);

  const loadSocial = async () => {
    try {
      const res = await axios.get(`${API_BASE_URL}/api/kelurahan/social-settings`, { headers: authHeader });
      setForm(f => ({ ...f, ...res.data }));
    } catch {
      toast.error('Gagal memuat pengaturan media sosial');
    }
  };

  const loadIdentity = async () => {
    try {
      const res = await axios.get(`${API_BASE_URL}/api/kelurahan/identity`, { headers: authHeader });
      const ts = Date.now();
      setLogoUrl(res.data.logo_url ? `${resolveUrl(res.data.logo_url)}?t=${ts}` : null);
      setKopLogoUrl(res.data.kop_logo_url ? `${resolveUrl(res.data.kop_logo_url)}?t=${ts}` : null);
      setAvailableThemes(res.data.available_themes || []);
      setSelectedThemeId(res.data.theme_id || 'default');
      setLoginCaption(res.data.login_caption || '');
      setLoginBgUrl(res.data.login_bg_url ? `${resolveUrl(res.data.login_bg_url)}?t=${ts}` : null);
      setAvailableLoginLayouts(res.data.available_login_layouts || []);
      setSelectedLoginLayoutId(res.data.login_layout_id || 'default');
    } catch {
      toast.error('Gagal memuat identitas & tema');
    }
  };

  const load = async () => {
    setLoading(true);
    await Promise.all([loadSocial(), loadIdentity()]);
    setLoading(false);
  };

  useEffect(() => { load(); }, [token]);

  const save = async () => {
    setSaving(true);
    try {
      const res = await axios.put(`${API_BASE_URL}/api/kelurahan/social-settings`, form, { headers: authHeader });
      setForm(f => ({ ...f, ...res.data }));
      toast.success('Pengaturan berhasil disimpan');
    } catch (err) {
      toast.error(err?.response?.data?.detail || 'Gagal menyimpan pengaturan');
    } finally {
      setSaving(false);
    }
  };

  const handleLogoSelect = (file) => {
    if (!file) return;
    if (!file.type.startsWith('image/')) { toast.error('File harus berformat gambar'); return; }
    if (file.size > 5 * 1024 * 1024)    { toast.error('Ukuran file maks 5 MB'); return; }
    setLogoPreview(URL.createObjectURL(file));
  };

  const handleLogoUpload = async () => {
    if (!uploadRef.current?.files?.[0]) return;
    setUploadingLogo(true);
    try {
      const fd = new FormData();
      fd.append('file', uploadRef.current.files[0]);
      const res = await axios.post(`${API_BASE_URL}/api/kelurahan/identity/logo`, fd, { headers: authHeader });
      setLogoUrl(`${resolveUrl(res.data.logo_url)}?t=${Date.now()}`);
      setLogoPreview(null);
      if (uploadRef.current) uploadRef.current.value = '';
      toast.success('Logo aplikasi berhasil diperbarui');
    } catch (err) {
      toast.error(err?.response?.data?.detail || 'Gagal upload logo');
    } finally {
      setUploadingLogo(false);
    }
  };

  const handleKopLogoSelect = (file) => {
    if (!file) return;
    if (!file.type.startsWith('image/')) { toast.error('File harus berformat gambar'); return; }
    if (file.size > 5 * 1024 * 1024)    { toast.error('Ukuran file maks 5 MB'); return; }
    setKopLogoPreview(URL.createObjectURL(file));
  };

  const handleKopLogoUpload = async () => {
    if (!kopUploadRef.current?.files?.[0]) return;
    setUploadingKopLogo(true);
    try {
      const fd = new FormData();
      fd.append('file', kopUploadRef.current.files[0]);
      const res = await axios.post(`${API_BASE_URL}/api/kelurahan/identity/kop-logo`, fd, { headers: authHeader });
      setKopLogoUrl(`${resolveUrl(res.data.kop_logo_url)}?t=${Date.now()}`);
      setKopLogoPreview(null);
      if (kopUploadRef.current) kopUploadRef.current.value = '';
      toast.success('Logo kop surat berhasil diperbarui');
    } catch (err) {
      toast.error(err?.response?.data?.detail || 'Gagal upload logo kop surat');
    } finally {
      setUploadingKopLogo(false);
    }
  };

  const handleLoginBgSelect = (file) => {
    if (!file) return;
    if (!file.type.startsWith('image/')) { toast.error('File harus berformat gambar'); return; }
    if (file.size > 5 * 1024 * 1024)    { toast.error('Ukuran file maks 5 MB'); return; }
    setLoginBgPreview(URL.createObjectURL(file));
  };

  const handleLoginBgUpload = async () => {
    if (!loginBgUploadRef.current?.files?.[0]) return;
    setUploadingLoginBg(true);
    try {
      const fd = new FormData();
      fd.append('file', loginBgUploadRef.current.files[0]);
      const res = await axios.post(`${API_BASE_URL}/api/kelurahan/identity/login-bg`, fd, { headers: authHeader });
      setLoginBgUrl(`${resolveUrl(res.data.login_bg_url)}?t=${Date.now()}`);
      setLoginBgPreview(null);
      if (loginBgUploadRef.current) loginBgUploadRef.current.value = '';
      toast.success('Gambar latar login berhasil diperbarui');
    } catch (err) {
      toast.error(err?.response?.data?.detail || 'Gagal upload gambar');
    } finally {
      setUploadingLoginBg(false);
    }
  };

  const removeLoginBg = async () => {
    setRemovingLoginBg(true);
    try {
      await axios.delete(`${API_BASE_URL}/api/kelurahan/identity/login-bg`, { headers: authHeader });
      setLoginBgUrl(null);
      toast.success('Gambar latar login dihapus, kembali ke gradien default');
    } catch (err) {
      toast.error(err?.response?.data?.detail || 'Gagal menghapus gambar');
    } finally {
      setRemovingLoginBg(false);
    }
  };

  const applyTheme = async (themeId) => {
    if (applyingTheme || themeId === selectedThemeId) return;
    setApplyingTheme(themeId);
    try {
      const res = await axios.put(`${API_BASE_URL}/api/kelurahan/identity/theme`, { theme_id: themeId }, { headers: authHeader });
      setSelectedThemeId(res.data.theme_id);
      await reloadColorTheme();
      toast.success('Tema warna berhasil diterapkan untuk Kelurahan ini');
    } catch (err) {
      toast.error(err?.response?.data?.detail || 'Gagal menerapkan tema');
    } finally {
      setApplyingTheme(null);
    }
  };

  const applyLoginLayout = async (layoutId) => {
    if (applyingLoginLayout || layoutId === selectedLoginLayoutId) return;
    setApplyingLoginLayout(layoutId);
    try {
      const res = await axios.put(`${API_BASE_URL}/api/kelurahan/identity/login-layout`, { layout_id: layoutId }, { headers: authHeader });
      setSelectedLoginLayoutId(res.data.login_layout_id);
      toast.success('Tema login berhasil diterapkan — cek halaman login Kelurahan ini');
    } catch (err) {
      toast.error(err?.response?.data?.detail || 'Gagal menerapkan tema login');
    } finally {
      setApplyingLoginLayout(null);
    }
  };

  const saveCaption = async () => {
    setSavingCaption(true);
    try {
      const res = await axios.put(`${API_BASE_URL}/api/kelurahan/identity/caption`, { login_caption: loginCaption }, { headers: authHeader });
      setLoginCaption(res.data.login_caption || '');
      toast.success('Keterangan halaman login berhasil disimpan');
    } catch (err) {
      toast.error(err?.response?.data?.detail || 'Gagal menyimpan keterangan');
    } finally {
      setSavingCaption(false);
    }
  };

  if (loading) {
    return (
      <div className="p-6 bg-[var(--rw-bg-page)] dark:bg-gray-900 min-h-full flex items-center justify-center">
        <div className="w-10 h-10 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin" />
      </div>
    );
  }

  return (
    <div className="p-6 space-y-6 bg-[var(--rw-bg-page)] dark:bg-gray-900 min-h-full">
      {/* Breadcrumb */}
      <div className="flex items-center gap-2 text-sm text-gray-500 dark:text-gray-400">
        <span>Kelurahan</span><span>/</span>
        <span>Konfigurasi</span><span>/</span>
        <span className="text-gray-700 dark:text-gray-300 font-medium">Setting</span>
      </div>

      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-gradient-to-br from-emerald-500 to-teal-600 rounded-xl flex items-center justify-center shadow">
            <Settings className="h-5 w-5 text-white" />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Setting</h1>
            <p className="text-sm text-gray-500 dark:text-gray-400">Identitas, tema, dan media sosial Kelurahan ini</p>
          </div>
        </div>
        <button onClick={load} className="flex items-center gap-2 px-3 py-2 text-sm bg-[var(--rw-bg-card)] dark:bg-gray-800 border border-[var(--rw-border)] dark:border-gray-700 rounded-lg hover:bg-[var(--rw-bg-card-alt)] dark:hover:bg-gray-700 transition-colors">
          <RefreshCw className="h-4 w-4" />
        </button>
      </div>

      {/* ── Identitas: Logo Aplikasi & Logo Kop Surat ── */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-5">
        <div className="bg-[var(--rw-bg-card)] dark:bg-gray-800 rounded-xl shadow p-5 flex flex-col gap-4">
          <div>
            <h3 className="text-sm font-semibold text-gray-800 dark:text-gray-100 flex items-center gap-2">
              <Image size={15} className="text-emerald-600" /> Logo Aplikasi
            </h3>
            <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">
              Tampil di halaman login ber-slug Kelurahan ini dan di sidebar aplikasi untuk RT/RW di bawahnya.
            </p>
          </div>

          <div className="flex flex-col items-center gap-3">
            <div className="w-28 h-28 rounded-2xl border-2 border-dashed border-[var(--rw-border)] dark:border-gray-600 flex items-center justify-center bg-[var(--rw-bg-page)] dark:bg-gray-900 overflow-hidden">
              {logoPreview || logoUrl ? (
                <img src={logoPreview || logoUrl} alt="Logo preview" className="w-full h-full object-contain p-2" />
              ) : (
                <div className="text-center">
                  <Image size={28} className="text-gray-300 mx-auto mb-1" />
                  <p className="text-xs text-gray-400">Belum ada logo</p>
                </div>
              )}
            </div>
            <p className="text-xs text-gray-400">PNG/JPG/WEBP/SVG · maks 5 MB</p>
          </div>

          <input ref={uploadRef} type="file" accept="image/*" className="hidden"
            onChange={e => handleLogoSelect(e.target.files?.[0])} />
          {logoPreview ? (
            <div className="flex gap-2">
              <button
                onClick={() => { setLogoPreview(null); if (uploadRef.current) uploadRef.current.value = ''; }}
                className="flex-1 py-2 rounded-lg border border-[var(--rw-border)] dark:border-gray-600 text-sm text-gray-600 dark:text-gray-300 hover:bg-[var(--rw-bg-card-alt)] dark:hover:bg-gray-700 transition-colors"
              >
                Batal
              </button>
              <button
                onClick={handleLogoUpload}
                disabled={uploadingLogo}
                className="flex-1 py-2 rounded-lg bg-emerald-500 hover:bg-emerald-600 text-white text-sm font-medium flex items-center justify-center gap-1.5 disabled:opacity-50 transition-colors"
              >
                {uploadingLogo ? <Loader2 size={13} className="animate-spin" /> : <Upload size={13} />}
                {uploadingLogo ? 'Mengupload...' : 'Simpan Logo'}
              </button>
            </div>
          ) : (
            <button
              onClick={() => uploadRef.current?.click()}
              className="w-full py-2 rounded-lg border border-[var(--rw-border)] dark:border-gray-600 text-sm text-gray-600 dark:text-gray-300 hover:bg-[var(--rw-bg-card-alt)] dark:hover:bg-gray-700 transition-colors flex items-center justify-center gap-2"
            >
              <Upload size={14} /> Pilih File Logo
            </button>
          )}
        </div>

        <div className="bg-[var(--rw-bg-card)] dark:bg-gray-800 rounded-xl shadow p-5 flex flex-col gap-4">
          <div>
            <h3 className="text-sm font-semibold text-gray-800 dark:text-gray-100 flex items-center gap-2">
              <Image size={15} className="text-indigo-500" /> Logo Kop Surat
            </h3>
            <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">
              Digunakan pada kwitansi IPL, laporan keuangan, dan surat resmi Kelurahan ini.
            </p>
          </div>

          <div className="flex flex-col items-center gap-3">
            <div className="w-28 h-28 rounded-2xl border-2 border-dashed border-[var(--rw-border)] dark:border-gray-600 flex items-center justify-center bg-[var(--rw-bg-page)] dark:bg-gray-900 overflow-hidden">
              {kopLogoPreview || kopLogoUrl ? (
                <img src={kopLogoPreview || kopLogoUrl} alt="Kop logo preview" className="w-full h-full object-contain p-2" />
              ) : (
                <div className="text-center">
                  <Image size={28} className="text-gray-300 mx-auto mb-1" />
                  <p className="text-xs text-gray-400">Belum ada logo</p>
                </div>
              )}
            </div>
            <p className="text-xs text-gray-400">PNG/JPG/WEBP/SVG · maks 5 MB</p>
          </div>

          <input ref={kopUploadRef} type="file" accept="image/*" className="hidden"
            onChange={e => handleKopLogoSelect(e.target.files?.[0])} />
          {kopLogoPreview ? (
            <div className="flex gap-2">
              <button
                onClick={() => { setKopLogoPreview(null); if (kopUploadRef.current) kopUploadRef.current.value = ''; }}
                className="flex-1 py-2 rounded-lg border border-[var(--rw-border)] dark:border-gray-600 text-sm text-gray-600 dark:text-gray-300 hover:bg-[var(--rw-bg-card-alt)] dark:hover:bg-gray-700 transition-colors"
              >
                Batal
              </button>
              <button
                onClick={handleKopLogoUpload}
                disabled={uploadingKopLogo}
                className="flex-1 py-2 rounded-lg bg-indigo-500 hover:bg-indigo-600 text-white text-sm font-medium flex items-center justify-center gap-1.5 disabled:opacity-50 transition-colors"
              >
                {uploadingKopLogo ? <Loader2 size={13} className="animate-spin" /> : <Upload size={13} />}
                {uploadingKopLogo ? 'Mengupload...' : 'Simpan Logo'}
              </button>
            </div>
          ) : (
            <button
              onClick={() => kopUploadRef.current?.click()}
              className="w-full py-2 rounded-lg border border-[var(--rw-border)] dark:border-gray-600 text-sm text-gray-600 dark:text-gray-300 hover:bg-[var(--rw-bg-card-alt)] dark:hover:bg-gray-700 transition-colors flex items-center justify-center gap-2"
            >
              <Upload size={14} /> Pilih File Logo Kop
            </button>
          )}
        </div>
      </div>

      {/* ── Gambar Latar Halaman Login ── */}
      <div className="bg-[var(--rw-bg-card)] dark:bg-gray-800 rounded-xl shadow p-5 space-y-4">
        <div>
          <h3 className="text-sm font-semibold text-gray-800 dark:text-gray-100 flex items-center gap-2">
            <ImagePlus size={15} className="text-emerald-600" /> Gambar Latar Halaman Login
          </h3>
          <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">
            Tampil sebagai latar panel kiri halaman login ber-slug Kelurahan ini (di atas gradien warna tema).
            Kosongkan untuk pakai gradien polos.
          </p>
        </div>

        <div className="w-full aspect-[16/7] rounded-xl border-2 border-dashed border-[var(--rw-border)] dark:border-gray-600 flex items-center justify-center bg-[var(--rw-bg-page)] dark:bg-gray-900 overflow-hidden">
          {loginBgPreview || loginBgUrl ? (
            <img src={loginBgPreview || loginBgUrl} alt="Preview gambar latar login" className="w-full h-full object-cover" />
          ) : (
            <div className="text-center">
              <ImagePlus size={28} className="text-gray-300 mx-auto mb-1" />
              <p className="text-xs text-gray-400">Belum ada gambar latar</p>
            </div>
          )}
        </div>
        <p className="text-xs text-gray-400 -mt-2">JPG/PNG/WEBP · maks 5 MB · disarankan orientasi potret/landscape gelap agar teks tetap terbaca</p>

        <input ref={loginBgUploadRef} type="file" accept="image/*" className="hidden"
          onChange={e => handleLoginBgSelect(e.target.files?.[0])} />
        {loginBgPreview ? (
          <div className="flex gap-2">
            <button
              onClick={() => { setLoginBgPreview(null); if (loginBgUploadRef.current) loginBgUploadRef.current.value = ''; }}
              className="flex-1 py-2 rounded-lg border border-[var(--rw-border)] dark:border-gray-600 text-sm text-gray-600 dark:text-gray-300 hover:bg-[var(--rw-bg-card-alt)] dark:hover:bg-gray-700 transition-colors"
            >
              Batal
            </button>
            <button
              onClick={handleLoginBgUpload}
              disabled={uploadingLoginBg}
              className="flex-1 py-2 rounded-lg bg-emerald-500 hover:bg-emerald-600 text-white text-sm font-medium flex items-center justify-center gap-1.5 disabled:opacity-50 transition-colors"
            >
              {uploadingLoginBg ? <Loader2 size={13} className="animate-spin" /> : <Upload size={13} />}
              {uploadingLoginBg ? 'Mengupload...' : 'Simpan Gambar'}
            </button>
          </div>
        ) : (
          <div className="flex gap-2">
            <button
              onClick={() => loginBgUploadRef.current?.click()}
              className="flex-1 py-2 rounded-lg border border-[var(--rw-border)] dark:border-gray-600 text-sm text-gray-600 dark:text-gray-300 hover:bg-[var(--rw-bg-card-alt)] dark:hover:bg-gray-700 transition-colors flex items-center justify-center gap-2"
            >
              <Upload size={14} /> Pilih Gambar
            </button>
            {loginBgUrl && (
              <button
                onClick={removeLoginBg}
                disabled={removingLoginBg}
                title="Hapus gambar latar"
                className="px-3 py-2 rounded-lg border border-red-200 dark:border-red-800 text-sm text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 transition-colors flex items-center gap-1.5 disabled:opacity-50"
              >
                {removingLoginBg ? <Loader2 size={14} className="animate-spin" /> : <Trash2 size={14} />}
              </button>
            )}
          </div>
        )}
      </div>

      {/* ── Keterangan Halaman Login ── */}
      <div className="bg-[var(--rw-bg-card)] dark:bg-gray-800 rounded-xl shadow p-5 space-y-3">
        <div>
          <h3 className="text-sm font-semibold text-gray-800 dark:text-gray-100 flex items-center gap-2">
            <Settings size={15} className="text-emerald-600" /> Keterangan Halaman Login
          </h3>
          <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">
            Baris singkat tambahan yang tampil di bawah "Manajemen Pengurus" pada halaman login ber-slug Kelurahan ini.
          </p>
        </div>
        <div className="flex gap-3">
          <input
            type="text"
            value={loginCaption}
            onChange={e => setLoginCaption(e.target.value)}
            placeholder="Contoh: Kelurahan Giriawas, Kecamatan Cikajang"
            maxLength={120}
            className="flex-1 px-3 py-2 text-sm border border-[var(--rw-border)] dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 dark:text-gray-100 focus:outline-none focus:ring-2 focus:ring-emerald-400/30"
          />
          <button
            onClick={saveCaption}
            disabled={savingCaption}
            className="px-4 py-2 rounded-lg bg-emerald-500 hover:bg-emerald-600 text-white text-sm font-medium flex items-center gap-1.5 disabled:opacity-50 transition-colors flex-shrink-0"
          >
            {savingCaption ? <Loader2 size={14} className="animate-spin" /> : <Save size={14} />}
            {savingCaption ? 'Menyimpan...' : 'Simpan'}
          </button>
        </div>
      </div>

      {/* ── Tema Warna ── */}
      <div className="bg-[var(--rw-bg-card)] dark:bg-gray-800 rounded-xl shadow p-5 space-y-4">
        <div>
          <h3 className="text-sm font-semibold text-gray-800 dark:text-gray-100 flex items-center gap-2">
            <Palette size={15} className="text-emerald-600" /> Tema Warna
          </h3>
          <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">
            Berlaku untuk halaman login ber-slug Kelurahan ini dan tampilan aplikasi setelah login.
            Pilihan tersedia di sini adalah tema yang sudah dipublish oleh vendor.
          </p>
        </div>

        <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-3">
          {availableThemes.map(theme => {
            const isSelected = selectedThemeId === theme.id;
            const isBusy = applyingTheme === theme.id;
            return (
              <div
                key={theme.id}
                className={`relative rounded-xl border-2 p-3 transition-colors ${
                  isSelected ? 'border-emerald-500' : 'border-[var(--rw-border)] dark:border-gray-600'
                }`}
                style={{ backgroundColor: theme.colors.bg_page }}
              >
                {isSelected && (
                  <span className="absolute top-2 right-2 w-5 h-5 rounded-full bg-emerald-500 text-white flex items-center justify-center">
                    <Check size={11} />
                  </span>
                )}
                <div className="rounded-lg p-2.5 mb-2" style={{ backgroundColor: theme.colors.bg_card, border: `1px solid ${theme.colors.border}` }}>
                  <ThemeSwatch colors={theme.colors} />
                </div>
                <p className="text-xs font-semibold text-gray-800 truncate">{theme.name}</p>
                <button
                  onClick={() => applyTheme(theme.id)}
                  disabled={isSelected || isBusy}
                  className={`w-full mt-2 py-1.5 rounded-lg text-[11px] font-semibold transition-colors ${
                    isSelected ? 'bg-gray-100 text-gray-400 cursor-default' : 'text-white hover:opacity-90'
                  }`}
                  style={!isSelected ? { backgroundColor: theme.colors.primary } : {}}
                >
                  {isBusy ? 'Memproses...' : isSelected ? 'Dipakai' : 'Pilih'}
                </button>
              </div>
            );
          })}
        </div>

        <p className="text-xs text-gray-400 border-t border-[var(--rw-border)] dark:border-gray-700 pt-3 flex items-center gap-1.5">
          <Globe size={12} /> Belum lihat tema lain di sini? Minta vendor untuk mempublish tema tambahan.
        </p>
      </div>

      {/* ── Tema Login (tata letak) ── */}
      <div className="bg-[var(--rw-bg-card)] dark:bg-gray-800 rounded-xl shadow p-5 space-y-4">
        <div>
          <h3 className="text-sm font-semibold text-gray-800 dark:text-gray-100 flex items-center gap-2">
            <ImagePlus size={15} className="text-emerald-600" /> Tema Login
          </h3>
          <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">
            Tata letak halaman login ber-slug Kelurahan ini (beda dari Tema Warna di atas). Pilihan tersedia di sini
            adalah tema yang sudah dipublish oleh vendor.
          </p>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
          {availableLoginLayouts.map(layout => {
            const isSelected = selectedLoginLayoutId === layout.id;
            const isBusy = applyingLoginLayout === layout.id;
            return (
              <div
                key={layout.id}
                className={`rounded-xl border-2 p-3 transition-colors ${
                  isSelected ? 'border-emerald-500' : 'border-[var(--rw-border)] dark:border-gray-600'
                }`}
              >
                <LoginLayoutPreview id={layout.id} />
                <p className="text-xs font-semibold text-gray-800 dark:text-gray-100 mt-2.5">{layout.name}</p>
                <p className="text-[11px] text-gray-500 dark:text-gray-400 mt-1 leading-snug">{layout.description}</p>
                <button
                  onClick={() => applyLoginLayout(layout.id)}
                  disabled={isSelected || isBusy}
                  className={`w-full mt-3 py-1.5 rounded-lg text-[11px] font-semibold transition-colors ${
                    isSelected
                      ? 'bg-gray-100 dark:bg-gray-700 text-gray-400 cursor-default'
                      : 'bg-emerald-500 hover:bg-emerald-600 text-white'
                  }`}
                >
                  {isBusy ? 'Memproses...' : isSelected ? 'Dipakai' : 'Pilih'}
                </button>
              </div>
            );
          })}
        </div>

        <p className="text-xs text-gray-400 border-t border-[var(--rw-border)] dark:border-gray-700 pt-3 flex items-center gap-1.5">
          <Globe size={12} /> Belum lihat tema login lain di sini? Minta vendor untuk mempublish tema tambahan.
        </p>
      </div>

      {/* ── Media Sosial ── */}
      <div className="bg-[var(--rw-bg-card)] dark:bg-gray-800 rounded-xl shadow p-5 space-y-5">
        <div>
          <h3 className="text-sm font-semibold text-gray-800 dark:text-gray-100 uppercase tracking-wide">Media Sosial</h3>
          <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">
            Tampil sebagai ikon di halaman login <strong>khusus tenant ini</strong> (link login ber-slug Kelurahan ini).
            Kosongkan kalau tidak ingin ditampilkan.
          </p>
        </div>

        {SOCIAL_FIELDS.map(({ key, label, Icon, placeholder }) => (
          <div key={key} className="space-y-1.5">
            <label className="flex items-center gap-1.5 text-xs font-semibold text-gray-600 dark:text-gray-300 uppercase tracking-wide">
              <Icon size={13} /> {label}
            </label>
            <div className="flex items-center gap-3">
              <input
                type="url"
                value={form[`social_${key}`] || ''}
                onChange={e => setForm(f => ({ ...f, [`social_${key}`]: e.target.value }))}
                placeholder={placeholder}
                className="flex-1 px-3 py-2 text-sm border border-[var(--rw-border)] dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 dark:text-gray-100 focus:outline-none focus:ring-2 focus:ring-emerald-400/30"
              />
              <label className="flex items-center gap-1.5 text-xs text-gray-500 dark:text-gray-400 whitespace-nowrap cursor-pointer">
                <input
                  type="checkbox"
                  checked={!!form[`social_${key}_enabled`]}
                  onChange={e => setForm(f => ({ ...f, [`social_${key}_enabled`]: e.target.checked }))}
                  className="w-4 h-4 rounded border-gray-300"
                />
                Aktif
              </label>
            </div>
          </div>
        ))}

        <p className="text-xs text-gray-400 border-t border-[var(--rw-border)] dark:border-gray-700 pt-3">
          Ikon hanya tampil di login kalau link diisi <strong>dan</strong> centang "Aktif" dinyalakan.
          Bisa juga sementara disembunyikan dengan mematikan "Aktif" tanpa perlu hapus link-nya.
        </p>

        <button
          onClick={save}
          disabled={saving}
          className="flex items-center gap-2 px-4 py-2.5 bg-emerald-500 hover:bg-emerald-600 text-white text-sm font-medium rounded-lg disabled:opacity-60 transition-colors"
        >
          <Save className="h-4 w-4" />{saving ? 'Menyimpan...' : 'Simpan Pengaturan'}
        </button>
      </div>
    </div>
  );
}
