import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { API_BASE_URL } from '@/config/api';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { toast } from '@/components/ui/sonner';
import { useAuth } from '@/contexts/AuthContext';
import { Checkbox } from '@/components/ui/checkbox';

export default function RumahFormModal({ open, onOpenChange, rumah, onSaved }) {
  const { token } = useAuth();

  // Dropdown Jenis Bangunan & Status Hunian diambil dari Tabel Referensi
  // vendor (bisa dikustomisasi tanpa ubah kode). Fallback ke daftar default
  // kalau API belum sempat merespons / gagal.
  const [jenisKepemilikanOptions, setJenisKepemilikanOptions] = useState([
    { nilai: 'Milik Sendiri', label: 'Milik Sendiri' },
    { nilai: 'Sewa / Kontrak', label: 'Sewa / Kontrak' },
    { nilai: 'Aset Publik', label: 'Aset Publik' },
    { nilai: 'Lainnya', label: 'Lainnya' },
  ]);
  const [statusHunianOptions, setStatusHunianOptions] = useState([
    { nilai: 'Ditempati Pemilik', label: 'Ditempati Pemilik' },
    { nilai: 'Ditempati Keluarga', label: 'Ditempati Keluarga' },
    { nilai: 'Disewakan / Kontrak', label: 'Disewakan / Kontrak' },
    { nilai: 'Tempat Usaha', label: 'Tempat Usaha' },
    { nilai: 'Kosong', label: 'Kosong' },
  ]);

  useEffect(() => {
    axios.get(`${API_BASE_URL}/api/referensi/jenis-kepemilikan-rumah`)
      .then(res => { if (res.data?.length) setJenisKepemilikanOptions(res.data); })
      .catch(() => {});
    axios.get(`${API_BASE_URL}/api/referensi/status-hunian-rumah`)
      .then(res => { if (res.data?.length) setStatusHunianOptions(res.data); })
      .catch(() => {});
  }, []);

  const [formData, setFormData] = useState({
    blok_no: '',
    nama_jalan: '',
    pemilik_sah: '',
    jenis_pemilik: 'Milik Sendiri',
    status_penghuni: 'Ditempati Pemilik',
    aktif: true,
    remark: '',
  });
  const [submitting, setSubmitting] = useState(false);

  // Load rumah data when editing
  useEffect(() => {
    if (rumah) {
      setFormData({
        blok_no: rumah.blok_no || '',
        nama_jalan: rumah.nama_jalan || '',
        pemilik_sah: rumah.pemilik_sah || '',
        jenis_pemilik: rumah.jenis_pemilik || 'Milik Sendiri',
        status_penghuni: rumah.status_penghuni || 'Ditempati Pemilik',
        aktif: rumah.aktif !== false,
        remark: rumah.remark || '',
      });
    } else {
      setFormData({
        blok_no: '',
        nama_jalan: '',
        pemilik_sah: '',
        jenis_pemilik: 'Milik Sendiri',
        status_penghuni: 'Ditempati Pemilik',
        aktif: true,
        remark: '',
      });
    }
  }, [rumah, open]);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleSelectChange = (name, value) => {
    const finalValue = value === 'none' ? '' : value;
    setFormData((prev) => ({
      ...prev,
      [name]: finalValue,
    }));
  };

  const handleCheckboxChange = (name) => {
    setFormData((prev) => ({
      ...prev,
      [name]: !prev[name],
    }));
  };

  const handleJenisPemilikChange = (value) => {
    setFormData((prev) => {
      const newFormData = { ...prev, jenis_pemilik: value };
      
      // Only auto-set status on create (when rumah is null)
      if (!rumah) {
        if (value === 'Sewa' || value === 'Kontrak' || value === 'Sewa / Kontrak') {
          newFormData.status_penghuni = 'Disewakan / Kontrak';
        } else if (value === 'Milik Sendiri') {
          newFormData.status_penghuni = 'Ditempati Pemilik';
        } else {
          newFormData.status_penghuni = 'Ditempati Pemilik';
        }
      }
      return newFormData;
    });
  };

  const handleStatusPenguniChange = (value) => {
    const newData = {
      ...formData,
      status_penghuni: value,
    };

    // "Sedang Kosong" tidak lagi diinput manual — backend otomatis
    // menyimpulkannya dari Status Hunian ini (kalau = "Kosong").
    if (value === 'Kosong') {
      newData.aktif = false; // Rumah kosong otomatis jadi tidak aktif (tidak kena tagihan IPL)
    }

    setFormData(newData);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!formData.blok_no.trim()) {
      toast.error('Blok / No Rumah harus diisi');
      return;
    }

    setSubmitting(true);

    try {
      const url = rumah
        ? `${API_BASE_URL}/api/rumah/${rumah.id}`
        : `${API_BASE_URL}/api/rumah`;

      const method = rumah ? 'PUT' : 'POST';

      const response = await fetch(url, {
        method: method,
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`,
        },
        body: JSON.stringify({
          blok_no: formData.blok_no,
          nama_jalan: formData.nama_jalan,
          pemilik_sah: formData.pemilik_sah,
          jenis_pemilik: formData.jenis_pemilik,
          status_penghuni: formData.status_penghuni,
          aktif: formData.aktif,
          remark: formData.remark,
        }),
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.detail || 'Gagal menyimpan data');
      }

      toast.success(rumah ? 'Data rumah berhasil diperbarui' : 'Data rumah berhasil ditambahkan');
      onOpenChange(false);
      onSaved();
    } catch (error) {
      console.error('Error:', error);
      toast.error(error.message || 'Gagal menyimpan data');
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto dark:bg-gray-900 dark:text-gray-100">
        <DialogHeader>
          <DialogTitle>
            {rumah ? 'Edit Rumah' : 'Tambah Rumah Baru'}
          </DialogTitle>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-6 py-4">
          {/* Row 1: Blok No & Nama Jalan */}
          <div className="grid grid-cols-2 gap-4">
            <div className="flex flex-col gap-2">
              <Label className="font-semibold text-gray-700 dark:text-gray-300">
                Blok / No Rumah <span className="text-red-500">*</span>
              </Label>
              <Input
                type="text"
                name="blok_no"
                value={formData.blok_no}
                onChange={handleInputChange}
                placeholder="e.g. A-1, B-5, GG-11"
                className="h-9 dark:bg-gray-800 dark:border-gray-700"
              />
            </div>

            <div className="flex flex-col gap-2">
              <Label className="font-semibold text-gray-700 dark:text-gray-300">
                Nama Jalan
              </Label>
              <Input
                type="text"
                name="nama_jalan"
                value={formData.nama_jalan}
                onChange={handleInputChange}
                placeholder="e.g. Jl. Merdeka"
                className="h-9 dark:bg-gray-800 dark:border-gray-700"
              />
            </div>
          </div>

          {/* Row 2: Pemilik Sah & Kategori */}
          <div className="grid grid-cols-2 gap-4">
            <div className="flex flex-col gap-2">
              <Label className="font-semibold text-gray-700 dark:text-gray-300">
                Pemilik Sah
              </Label>
              <Input
                type="text"
                name="pemilik_sah"
                value={formData.pemilik_sah}
                onChange={handleInputChange}
                placeholder="Nama pemilik sah"
                className="h-9 dark:bg-gray-800 dark:border-gray-700"
              />
            </div>
          </div>

          {/* Row 3: Jenis Bangunan & Status Hunian */}
          <div className="grid grid-cols-2 gap-4">
            <div className="flex flex-col gap-2">
              <Label className="font-semibold text-gray-700 dark:text-gray-300">
                Jenis Bangunan <span className="text-red-500">*</span>
              </Label>
              <Select value={formData.jenis_pemilik} onValueChange={handleJenisPemilikChange}>
                <SelectTrigger className="h-9 dark:bg-gray-800 dark:border-gray-700">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {jenisKepemilikanOptions.map((opt) => (
                    <SelectItem key={opt.nilai} value={opt.nilai}>{opt.label}</SelectItem>
                  ))}
                  {/* Nilai lama (data lawas sebelum ada Tabel Referensi) — tetap ditampilkan agar tidak kosong saat edit */}
                  {formData.jenis_pemilik && !jenisKepemilikanOptions.some(o => o.nilai === formData.jenis_pemilik) && (
                    <SelectItem value={formData.jenis_pemilik}>{formData.jenis_pemilik} (lama)</SelectItem>
                  )}
                </SelectContent>
              </Select>
            </div>

            <div className="flex flex-col gap-2">
              <Label className="font-semibold text-gray-700 dark:text-gray-300">
                Status Hunian <span className="text-red-500">*</span>
              </Label>
              <Select value={formData.status_penghuni} onValueChange={handleStatusPenguniChange}>
                <SelectTrigger className="h-9 dark:bg-gray-800 dark:border-gray-700">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {statusHunianOptions.map((opt) => (
                    <SelectItem key={opt.nilai} value={opt.nilai}>{opt.label}</SelectItem>
                  ))}
                  {formData.status_penghuni && !statusHunianOptions.some(o => o.nilai === formData.status_penghuni) && (
                    <SelectItem value={formData.status_penghuni}>{formData.status_penghuni} (lama)</SelectItem>
                  )}
                </SelectContent>
              </Select>
            </div>
          </div>

          {/* Row 5: Checkbox Aktif — "Sedang Kosong" dihapus karena sudah
              diwakili oleh Status Hunian = "Kosong" (backend otomatis
              menyimpulkan, tidak perlu diinput manual lagi) */}
          <div className="flex gap-4">
            <div className="flex items-center gap-2">
              <Checkbox
                id="aktif"
                checked={formData.aktif}
                onCheckedChange={() => handleCheckboxChange('aktif')}
              />
              <Label htmlFor="aktif" className="font-normal cursor-pointer">
                Aktif
              </Label>
            </div>
          </div>

          {/* Remark */}
          <div className="flex flex-col gap-2">
            <Label htmlFor="remark" className="font-semibold text-gray-700 dark:text-gray-300">
              Catatan (Remark)
            </Label>
            <textarea
              id="remark"
              name="remark"
              placeholder="Catatan: Opsional"
              value={formData.remark}
              onChange={handleInputChange}
              className="h-20 p-3 border border-gray-300 dark:border-gray-600 rounded-md bg-[var(--rw-bg-card)] dark:bg-gray-800 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-cyan-500"
            />
          </div>

          {/* Buttons */}
          <div className="flex gap-3 justify-end pt-4 border-t dark:border-gray-700">
            <Button
              type="button"
              variant="outline"
              onClick={() => onOpenChange(false)}
              className="dark:bg-gray-800 dark:text-gray-100 dark:border-gray-700"
            >
              Batal
            </Button>
            <Button
              type="submit"
              disabled={submitting}
              className="bg-[var(--rw-primary)] hover:bg-[var(--rw-primary-hover)] text-white"
            >
              {submitting ? 'Menyimpan...' : rumah ? 'Update' : 'Simpan'}
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}
