import React, { useEffect, useState, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import { API_BASE_URL } from '../config/api';
import { HeartHandshake, ExternalLink, AlertTriangle, Loader2 } from 'lucide-react';

/**
 * Halaman "Cek Bansos" — TIDAK lagi embed lewat iframe (situs pemerintah
 * seperti Kemensos punya CAPTCHA yang terikat sesi server, jadi walau
 * lewat proxy tetap gagal render gambar CAPTCHA-nya — keterbatasan
 * fundamental, bukan bug). Sekarang begitu link berhasil diambil dari
 * backend, otomatis buka di TAB BARU browser (sesi asli user, jadi
 * CAPTCHA dkk berfungsi normal seperti buka situs itu langsung).
 *
 * URL & judulnya TETAP diambil dinamis dari backend (kategori
 * "link_eksternal" di Tabel Referensi vendor) — vendor tetap bisa ganti
 * link ini kapan saja tanpa perlu ubah kode.
 *
 * Dipakai bersama di 3 route: /cek-bansos (RT & Warga), /rw/cek-bansos,
 * dan /kelurahan/cek-bansos.
 */
export default function CekBansos() {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [links, setLinks] = useState([]);
  const [opened, setOpened] = useState(false);
  const hasAutoOpened = useRef(false);

  useEffect(() => {
    let mounted = true;
    axios.get(`${API_BASE_URL}/api/referensi/link-eksternal`)
      .then(res => {
        if (!mounted) return;
        const data = res.data || [];
        setLinks(data);
      })
      .catch(() => setLinks([]))
      .finally(() => mounted && setLoading(false));
    return () => { mounted = false; };
  }, []);

  const primaryLink = links.find(l => (l.label || '').toLowerCase().includes('bansos')) || links[0];

  const openLink = (url) => {
    window.open(url, '_blank', 'noopener,noreferrer');
    setOpened(true);
  };

  // Begitu link-nya sudah didapat, langsung buka tab baru otomatis
  // (cuma sekali, supaya tidak buka berkali-kali kalau komponen re-render)
  useEffect(() => {
    if (!loading && primaryLink?.url && !hasAutoOpened.current) {
      hasAutoOpened.current = true;
      openLink(primaryLink.url);
    }
  }, [loading, primaryLink]);

  return (
    <div className="p-4 sm:p-6 max-w-2xl mx-auto">
      <div className="flex items-center gap-3 mb-6">
        <div className="w-10 h-10 rounded-xl bg-rose-100 dark:bg-rose-900/30 flex items-center justify-center flex-shrink-0">
          <HeartHandshake className="w-5 h-5 text-rose-600 dark:text-rose-400" />
        </div>
        <div>
          <h1 className="text-xl font-bold text-gray-900 dark:text-gray-100">Cek Bansos</h1>
          <p className="text-sm text-gray-500 dark:text-gray-400">
            Cek status penerima bantuan sosial langsung dari situs resmi Kementerian Sosial.
          </p>
        </div>
      </div>

      <div className="border border-gray-200 dark:border-gray-700 rounded-xl bg-white dark:bg-gray-800 p-8 text-center">
        {loading ? (
          <>
            <Loader2 className="w-8 h-8 text-gray-400 animate-spin mx-auto mb-3" />
            <p className="text-sm text-gray-500 dark:text-gray-400">Memuat link...</p>
          </>
        ) : !primaryLink ? (
          <>
            <AlertTriangle className="w-8 h-8 text-amber-500 mx-auto mb-3" />
            <p className="text-sm text-gray-600 dark:text-gray-400">
              Link Cek Bansos belum diatur. Hubungi admin/vendor untuk mengatur link ini
              di menu Tabel Referensi (kategori "Link Eksternal").
            </p>
          </>
        ) : (
          <>
            <HeartHandshake className="w-8 h-8 text-rose-500 mx-auto mb-3" />
            <p className="text-sm text-gray-600 dark:text-gray-400 mb-1">
              {opened
                ? `${primaryLink.label} sudah dibuka di tab baru.`
                : `Membuka ${primaryLink.label} di tab baru...`}
            </p>
            <p className="text-xs text-gray-400 dark:text-gray-500 mb-5">
              Kalau tab baru tidak terbuka otomatis (diblokir browser), klik tombol di bawah ini.
            </p>
            <button
              onClick={() => openLink(primaryLink.url)}
              className="inline-flex items-center gap-2 px-5 py-2.5 rounded-lg bg-rose-600 hover:bg-rose-700 text-white text-sm font-medium transition-colors"
            >
              <ExternalLink className="w-4 h-4" /> Buka {primaryLink.label}
            </button>

            {/* Kalau vendor mengaktifkan lebih dari satu link eksternal, tampilkan pilihan lainnya */}
            {links.length > 1 && (
              <div className="mt-6 pt-5 border-t border-gray-100 dark:border-gray-700">
                <p className="text-xs text-gray-400 dark:text-gray-500 mb-2">Link lainnya:</p>
                <div className="flex flex-wrap justify-center gap-2">
                  {links.filter(l => l.url !== primaryLink.url).map(l => (
                    <button
                      key={l.id}
                      onClick={() => openLink(l.url)}
                      className="text-sm px-3 py-1.5 rounded-lg border border-gray-300 dark:border-gray-600 text-gray-600 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors"
                    >
                      {l.label}
                    </button>
                  ))}
                </div>
              </div>
            )}

            <div className="mt-5">
              <button
                onClick={() => navigate(-1)}
                className="text-xs text-gray-400 hover:text-gray-600 dark:hover:text-gray-300 underline"
              >
                Kembali ke halaman sebelumnya
              </button>
            </div>
          </>
        )}
      </div>
    </div>
  );
}
