import React from 'react';
import { Card, CardContent, CardHeader, CardTitle } from './ui/card';

const DonutChart = ({ title, data, totalLabel = '(7 total)', frameless = false, className = '', valueFormatter = null }) => {
  // Calculate total for percentages
  const total = data.reduce((sum, item) => sum + item.value, 0);

  // Format angka di legend — default tampil apa adanya (utk chart hitungan warga dll),
  // tapi bisa dikasih formatter (mis. Rupiah) lewat prop valueFormatter.
  const formatValue = valueFormatter || ((v) => v);
  
  // Prepare data with percentages
  const chartData = data.map((item) => ({
    ...item,
    percentage: total > 0 ? Math.round((item.value / total) * 100) : 0
  }));

  // Ring donat pakai SVG asli (bukan CSS conic-gradient) — conic-gradient tidak
  // didukung html2canvas (dipakai fitur Print PDF dashboard), hasilnya jadi
  // lingkaran putih kosong. SVG di-capture dengan benar karena chart lain
  // (Pie3DChart) yang berbasis SVG juga terbukti ter-capture normal.
  const RADIUS = 80;
  const STROKE_WIDTH = 32;
  const CIRCUMFERENCE = 2 * Math.PI * RADIUS;

  const content = (
    // Breakpoint dinaikkan dari md (768px) ke xl (1280px): chart ini sering
    // ditaruh di grid 3 kolom (mis. dashboard RW/Kelurahan). Kalau layout
    // sejajar (donut + legend) aktif dari 768px, di lebar iPad/tablet
    // (768–1180px) grid-nya sudah 3 kolom TAPI tiap chart juga sudah coba
    // sejajar horizontal — hasilnya legend/angka kepotong/overflow keluar
    // card (lihat laporan bug: teks "(303" ke-cut). Di bawah 1280px sekarang
    // selalu stack vertikal (donut di atas, legend di bawah) yang aman di
    // lebar kolom berapa pun.
    <div className="flex flex-col xl:flex-row items-center justify-center gap-8">
      <div className="flex items-center justify-center">
        <div className="relative w-48 h-48">
          <svg viewBox="0 0 192 192" className="w-full h-full" style={{ transform: 'rotate(-90deg)' }}>
            {chartData.map((item, index) => {
              if (item.percentage <= 0) return null;
              const offsetPercent = chartData.slice(0, index).reduce((s, d) => s + d.percentage, 0);
              const dash = (item.percentage / 100) * CIRCUMFERENCE;
              return (
                <circle
                  key={index}
                  cx="96"
                  cy="96"
                  r={RADIUS}
                  fill="none"
                  stroke={item.color}
                  strokeWidth={STROKE_WIDTH}
                  strokeDasharray={`${dash} ${CIRCUMFERENCE - dash}`}
                  strokeDashoffset={-(offsetPercent / 100) * CIRCUMFERENCE}
                />
              );
            })}
          </svg>
        </div>
      </div>

      <div className="flex-1 space-y-3">
        {chartData.map((item, index) => (
          <div key={index} className="flex items-center justify-between text-sm">
            <div className="flex items-center gap-2">
              <div
                className="w-3 h-3 rounded-full flex-shrink-0"
                style={{ backgroundColor: item.color }}
              />
              <span className="text-gray-700 dark:text-gray-300">{item.label}</span>
            </div>
            <span className="text-gray-500 dark:text-gray-400 font-medium whitespace-nowrap ml-2">
              ({formatValue(item.value)} - {item.percentage}%)
            </span>
          </div>
        ))}
      </div>
    </div>
  );

  if (frameless) {
    return (
      <div className={`space-y-4 ${className}`}>
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <span className="text-sm font-bold text-gray-900 dark:text-white">{title}</span>
            <span className="text-green-500 text-lg">✓</span>
          </div>
          <span className="text-xs text-gray-500 dark:text-gray-400">{totalLabel}</span>
        </div>
        {content}
      </div>
    );
  }

  return (
    <Card className={`hover:shadow-lg transition-shadow duration-200 ${className}`}>
      <CardHeader>
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <CardTitle className="text-sm font-bold text-gray-900 dark:text-white">
              {title}
            </CardTitle>
            <span className="text-green-500 text-lg">✓</span>
          </div>
          <span className="text-xs text-gray-500 dark:text-gray-400">{totalLabel}</span>
        </div>
      </CardHeader>
      <CardContent>
        {content}
      </CardContent>
    </Card>
  );
};

export default DonutChart;