import { useEffect, useState } from "react";
import { API_BASE_URL } from '../../config/api';
import {
  MENU_ITEMS, PERMISSIONS_MATRIX, CRUD_ACTIONS
} from '../../lib/permissionsMatrix';
import {
  Shield, Check, X, RefreshCw, Save, AlertCircle,
  ChevronDown, ChevronUp, Globe, Building2, Home, Layout
} from 'lucide-react';

// Kelompokkan MENU_ITEMS berdasarkan group
const MENU_GROUPS = [
  {
    key: 'RT',
    label: 'RT — Operasional',
    icon: Home,
    color: 'bg-[#ed6f5c]',
    textColor: 'text-blue-600',
    bgLight: 'bg-blue-50',
    border: 'border-blue-200 ',
  },
  {
    key: 'RW',
    label: 'RW — Supervisory',
    icon: Building2,
    color: 'bg-[#ed6f5c]',
    textColor: 'text-[#ed6f5c]',
    bgLight: 'bg-[#fdf1ef]',
    border: 'border-[#e8c5be]',
  },
  {
    key: 'Kelurahan',
    label: 'Kelurahan — Monitoring',
    icon: Globe,
    color: 'bg-orange-500',
    textColor: 'text-orange-600',
    bgLight: 'bg-orange-50',
    border: 'border-orange-200 ',
  },
  {
    key: 'Vendor',
    label: 'Vendor — Platform',
    icon: Layout,
    color: 'bg-[#ed6f5c]',
    textColor: 'text-[#ed6f5c]',
    bgLight: 'bg-[#fdf1ef]',
    border: 'border-[#e8c5be]',
  },
];

const getMenuGroup = (menuId) => {
  if (menuId.startsWith('rw-'))     return 'RW';
  if (menuId.startsWith('kel-'))    return 'Kelurahan';
  if (menuId.startsWith('vendor-')) return 'Vendor';
  return 'RT';
};

// Token & headers pakai vendor_token
const vToken = () => localStorage.getItem('vendor_token');
const vHdrs  = () => ({
  'Content-Type': 'application/json',
  Authorization: `Bearer ${vToken()}`,
});

export default function VendorPermissions() {
  const [permissions, setPermissions] = useState({});
  const [roles, setRoles]             = useState(['admin']);
  const [loading, setLoading]         = useState(false);
  const [saving, setSaving]           = useState(false);
  const [toast, setToast]             = useState(null);
  const [collapsedGroups, setCollapsedGroups] = useState({});

  // Per-wilayah: '' = matriks Global (perilaku lama). Pilih satu Kelurahan
  // supaya toggle di bawah menyimpan sebagai OVERRIDE khusus wilayah itu
  // (cascade ke semua role RT/RW di bawahnya), bukan matriks global.
  const [tenants, setTenants]                 = useState([]);
  const [selectedTenantId, setSelectedTenantId] = useState('');

  // Freeze menu — daftar id menu yang "dibekukan": tetap tampil di sidebar
  // semua level & semua slug, tapi tidak bisa diklik. Terikat ke
  // selectedTenantId sama seperti matriks role di atas: kosong = edit status
  // Global, pilih satu Kelurahan = edit override khusus wilayah itu (nilai
  // yang ditampilkan sudah efektif — override kalau ada, else ikut Global).
  const [frozenIds, setFrozenIds] = useState(new Set());

  useEffect(() => {
    fetch(`${API_BASE_URL}/api/vendor/tenants`, { headers: vHdrs() })
      .then(res => res.ok ? res.json() : [])
      .then(data => setTenants((Array.isArray(data) ? data : []).filter(t => t.tenant_type === 'Kelurahan')))
      .catch(() => {});
  }, []);

  // Freeze — refetch setiap kali wilayah yang sedang diedit berganti, sama
  // seperti matriks role di bawah, supaya checkbox freeze menampilkan status
  // EFEKTIF wilayah tsb (override-nya kalau ada, else ikut Global).
  useEffect(() => {
    const q = selectedTenantId ? `?tenant_id=${selectedTenantId}` : '';
    fetch(`${API_BASE_URL}/api/vendor/frozen-menus${q}`, { headers: vHdrs() })
      .then(res => res.ok ? res.json() : { frozen_ids: [] })
      .then(data => setFrozenIds(new Set(data.frozen_ids || [])))
      .catch(() => {});
  }, [selectedTenantId]);

  const handleToggleFreeze = async (menuId, newVal) => {
    const prev = frozenIds;
    const next = new Set(prev);
    if (newVal) next.add(menuId); else next.delete(menuId);
    setFrozenIds(next);

    try {
      setSaving(true);
      const res = await fetch(`${API_BASE_URL}/api/vendor/frozen-menus/toggle`, {
        method: 'PUT', headers: vHdrs(),
        body: JSON.stringify({ menu_id: menuId, frozen: newVal, tenant_id: selectedTenantId || null }),
      });
      if (!res.ok) throw new Error(`Status ${res.status}`);
      showToast(`✓ ${menuId} ${newVal ? 'dibekukan' : 'diaktifkan kembali'}${selectedTenantId ? ' (khusus wilayah ini)' : ''}`);
    } catch (e) {
      showToast('Gagal menyimpan freeze: ' + e.message, 'error');
      setFrozenIds(prev);
    } finally {
      setSaving(false);
    }
  };

  const tenantQuery = selectedTenantId ? `?tenant_id=${selectedTenantId}` : '';

  const showToast = (msg, type = 'success') => {
    setToast({ msg, type });
    setTimeout(() => setToast(null), 3000);
  };

  const loadRolesAndPermissions = async () => {
    setLoading(true);
    try {
      // Load roles
      const rolesRes = await fetch(`${API_BASE_URL}/api/roles`, { headers: vHdrs() });
      let roleNames = ['admin'];
      if (rolesRes.ok) {
        const data = await rolesRes.json();
        roleNames = data.map(r => r.name).sort((a, b) => {
          if (a === 'admin') return -1;
          if (b === 'admin') return 1;
          return a.localeCompare(b);
        });
        setRoles(roleNames);
      }

      // Load permissions per role
      const initialPerms = {};
      for (const role of roleNames) {
        try {
          const res = await fetch(`${API_BASE_URL}/api/role-permissions/${role}${tenantQuery}`, { headers: vHdrs() });
          if (res.ok) {
            const data = await res.json();
            initialPerms[role] = data.permissions
              ? (typeof data.permissions === 'string' ? JSON.parse(data.permissions) : data.permissions)
              : getDefaultPermissionsForRole(role);
          } else {
            initialPerms[role] = getDefaultPermissionsForRole(role);
          }
        } catch {
          initialPerms[role] = getDefaultPermissionsForRole(role);
        }
      }
      setPermissions(initialPerms);
    } catch (e) {
      showToast('Gagal memuat data: ' + e.message, 'error');
    }
    setLoading(false);
  };

  const getDefaultPermissionsForRole = (role) => {
    const perms = {};
    MENU_ITEMS.forEach(menu => {
      perms[menu.id] = role === 'admin'
        ? { read: true, create: true, update: true, delete: true }
        : { read: false, create: false, update: false, delete: false };
    });
    return perms;
  };

  useEffect(() => { loadRolesAndPermissions(); }, [selectedTenantId]);

  const handleToggle = async (role, menuId, action) => {
    if (!permissions[role]) return;
    const prev = permissions[role][menuId] || { read: false, create: false, update: false, delete: false };
    const updated = {
      ...permissions,
      [role]: {
        ...permissions[role],
        [menuId]: { ...prev, [action]: !prev[action] },
      },
    };
    setPermissions(updated);

    try {
      setSaving(true);
      const res = await fetch(`${API_BASE_URL}/api/role-permissions/${role}${tenantQuery}`, {
        method: 'POST', headers: vHdrs(),
        body: JSON.stringify({ role, permissions: updated[role] }),
      });
      if (!res.ok) throw new Error(`Status ${res.status}`);
      showToast(`✓ ${role} › ${menuId} › ${action} disimpan`);
    } catch (e) {
      showToast('Gagal menyimpan: ' + e.message, 'error');
      loadRolesAndPermissions(); // revert
    } finally {
      setSaving(false);
    }
  };

  const handleToggleAllAction = async (role, action, newVal) => {
    const updatedRole = { ...permissions[role] };
    MENU_ITEMS.forEach(m => {
      if (!updatedRole[m.id]) updatedRole[m.id] = { read: false, create: false, update: false, delete: false };
      updatedRole[m.id][action] = newVal;
    });
    const updated = { ...permissions, [role]: updatedRole };
    setPermissions(updated);

    try {
      setSaving(true);
      const res = await fetch(`${API_BASE_URL}/api/role-permissions/${role}${tenantQuery}`, {
        method: 'POST', headers: vHdrs(),
        body: JSON.stringify({ role, permissions: updatedRole }),
      });
      if (!res.ok) throw new Error(`Status ${res.status}`);
      showToast(`✓ Semua ${action} untuk ${role} diperbarui`);
    } catch (e) {
      showToast('Gagal menyimpan', 'error');
      loadRolesAndPermissions();
    } finally {
      setSaving(false);
    }
  };

  const handleToggleGroup = async (role, groupKey, newVal) => {
    const groupMenus = MENU_ITEMS.filter(m => getMenuGroup(m.id) === groupKey);
    const updatedRole = { ...permissions[role] };
    groupMenus.forEach(m => {
      updatedRole[m.id] = { read: newVal, create: newVal, update: newVal, delete: newVal };
    });
    const updated = { ...permissions, [role]: updatedRole };
    setPermissions(updated);

    try {
      setSaving(true);
      const res = await fetch(`${API_BASE_URL}/api/role-permissions/${role}${tenantQuery}`, {
        method: 'POST', headers: vHdrs(),
        body: JSON.stringify({ role, permissions: updatedRole }),
      });
      if (!res.ok) throw new Error(`Status ${res.status}`);
      showToast(`✓ Grup ${groupKey} untuk ${role} diperbarui`);
    } catch (e) {
      showToast('Gagal menyimpan', 'error');
      loadRolesAndPermissions();
    } finally {
      setSaving(false);
    }
  };

  const isGroupAllChecked = (role, groupKey) => {
    const groupMenus = MENU_ITEMS.filter(m => getMenuGroup(m.id) === groupKey);
    return groupMenus.every(m =>
      CRUD_ACTIONS.every(a => permissions[role]?.[m.id]?.[a])
    );
  };

  const toggleGroupCollapse = (groupKey) => {
    setCollapsedGroups(p => ({ ...p, [groupKey]: !p[groupKey] }));
  };

  const ROLE_COLORS = [
    'text-[#ed6f5c]',
    'text-blue-700 ',
    'text-emerald-700 ',
    'text-orange-700 ',
    'text-red-700 ',
  ];

  return (
    <div className="space-y-5">
      {/* Header */}
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div>
          <h1 className="text-2xl font-bold text-gray-800 ">Matriks Hak Akses</h1>
          <p className="text-sm text-gray-500">
            Kelola akses menu per role untuk semua level (RT / RW / Kelurahan).
            Perubahan tersimpan otomatis.
          </p>
        </div>
        <div className="flex items-center gap-2 flex-wrap">
          <select
            value={selectedTenantId}
            onChange={e => setSelectedTenantId(e.target.value)}
            className="px-3 py-2 border border-gray-200 rounded-xl text-sm bg-white focus:outline-none focus:ring-2 focus:ring-[#ed6f5c]/30"
          >
            <option value="">Global (Semua Wilayah)</option>
            {tenants.map(t => (
              <option key={t.id} value={t.id}>{t.name}</option>
            ))}
          </select>
          <button onClick={loadRolesAndPermissions}
            className="flex items-center gap-2 px-3 py-2 border border-gray-200  rounded-xl text-sm hover:bg-gray-50">
            <RefreshCw size={14} className={loading ? 'animate-spin text-[#ed6f5c]' : ''} />
            Refresh
          </button>
        </div>
      </div>

      {/* Info banner */}
      <div className="flex items-start gap-3 bg-blue-50 border border-blue-200  rounded-xl p-4 text-sm text-blue-700 ">
        <AlertCircle size={16} className="flex-shrink-0 mt-0.5" />
        <div>
          <span className="font-semibold">Keterangan: </span>
          B = Baca (Read) | T = Tambah (Create) | E = Edit (Update) | H = Hapus (Delete)
          <br />
          Klik checkbox untuk mengubah permission. Perubahan tersimpan otomatis ke database.
        </div>
      </div>

      {/* Banner wilayah aktif */}
      {selectedTenantId && (
        <div className="flex items-start gap-3 bg-amber-50 border border-amber-200 rounded-xl p-4 text-sm text-amber-800">
          <Globe size={16} className="flex-shrink-0 mt-0.5" />
          <div>
            <span className="font-semibold">
              Menyunting matriks khusus {tenants.find(t => t.id === selectedTenantId)?.name || 'wilayah ini'}
            </span> — perubahan di bawah hanya berlaku untuk wilayah ini (cascade ke semua RT/RW di bawahnya).
            Wilayah lain tetap memakai matriks Global. Menu yang tidak diubah di sini otomatis ikut matriks Global.
          </div>
        </div>
      )}

      {loading ? (
        <div className="flex justify-center py-16">
          <div className="w-10 h-10 border-4 border-[#ed6f5c] border-t-transparent rounded-full animate-spin" />
        </div>
      ) : (
        <div className="bg-white  rounded-2xl border border-gray-100  overflow-hidden">
          {/* Saving indicator */}
          {saving && (
            <div className="bg-[#fdf1ef] px-5 py-2 text-xs text-[#ed6f5c] flex items-center gap-2 border-b border-gray-200 ">
              <Save size={12} className="animate-pulse" /> Menyimpan...
            </div>
          )}

          <div className="overflow-x-auto">
            <table className="w-full text-sm min-w-[700px]">
              <thead className="bg-gray-50 sticky top-0 z-10">
                <tr>
                  <th className="px-5 py-3 text-left text-xs font-semibold text-gray-500 uppercase w-44">MENU</th>
                  <th rowSpan={2}
                    className="px-2 py-3 text-center text-xs font-bold uppercase border-l border-gray-200 text-amber-600 w-16">
                    Freeze
                  </th>
                  {roles.map((role, i) => (
                    <th key={role} colSpan={4}
                      className={`px-2 py-3 text-center text-xs font-bold uppercase border-l border-gray-200  ${ROLE_COLORS[i % ROLE_COLORS.length]}`}>
                      {role}
                    </th>
                  ))}
                </tr>
                {/* Action headers per role */}
                <tr className="border-t border-gray-200 ">
                  <th className="px-5 py-2 text-left text-xs text-gray-400">
                    <span className="font-medium">Menu / Aksi</span>
                  </th>
                  {roles.map(role => (
                    CRUD_ACTIONS.map(action => {
                      const label = { read:'B', create:'T', update:'E', delete:'H' }[action];
                      const allChecked = MENU_ITEMS.every(m => permissions[role]?.[m.id]?.[action]);
                      return (
                        <th key={`${role}-${action}`}
                          className="w-10 py-2 text-center text-xs text-gray-400 border-l border-gray-200 first:border-l first:border-gray-200 ">
                          <div className="flex flex-col items-center gap-1">
                            <span className="font-bold text-gray-600 ">{label}</span>
                            <input type="checkbox" checked={allChecked}
                              onChange={e => handleToggleAllAction(role, action, e.target.checked)}
                              title={`Toggle all ${action} for ${role}`}
                              className="w-3.5 h-3.5 accent-[#ed6f5c] cursor-pointer" />
                          </div>
                        </th>
                      );
                    })
                  ))}
                </tr>
              </thead>

              <tbody className="divide-y divide-gray-50">
                {MENU_GROUPS.map(group => {
                  const groupMenus = MENU_ITEMS.filter(m => getMenuGroup(m.id) === group.key);
                  if (groupMenus.length === 0) return null;
                  const isCollapsed = collapsedGroups[group.key];
                  const GroupIcon  = group.icon;

                  return [
                    /* Group header row */
                    <tr key={`group-${group.key}`}
                      className={`${group.bgLight} border-t-2 ${group.border}`}>
                      <td className="px-4 py-2.5">
                        <div className="flex items-center gap-2">
                          <div className={`w-6 h-6 rounded-lg flex items-center justify-center ${group.color}`}>
                            <GroupIcon size={12} className="text-white" />
                          </div>
                          <span className={`text-xs font-bold uppercase tracking-wide ${group.textColor}`}>
                            {group.label}
                          </span>
                          <span className="text-xs text-gray-400">({groupMenus.length} menu)</span>
                          <button onClick={() => toggleGroupCollapse(group.key)}
                            className={`ml-1 ${group.textColor} opacity-60 hover:opacity-100`}>
                            {isCollapsed ? <ChevronDown size={13}/> : <ChevronUp size={13}/>}
                          </button>
                        </div>
                      </td>
                      <td className="border-l border-gray-200 "></td>
                      {/* Group toggle buttons per role */}
                      {roles.map(role => {
                        const allOn = isGroupAllChecked(role, group.key);
                        return CRUD_ACTIONS.map((action, ai) => (
                          <td key={`${role}-${group.key}-${action}`}
                            className="text-center py-2 border-l border-gray-200 ">
                            {ai === 0 && (
                              <button onClick={() => handleToggleGroup(role, group.key, !allOn)}
                                title={`Toggle semua ${group.key} untuk ${role}`}
                                className={`text-[10px] px-1.5 py-0.5 rounded font-semibold ${
                                  allOn
                                    ? `${group.color} text-white`
                                    : 'bg-gray-200  text-gray-500'
                                }`}>
                                {allOn ? 'ALL' : 'OFF'}
                              </button>
                            )}
                          </td>
                        ));
                      })}
                    </tr>,

                    /* Menu rows */
                    ...(!isCollapsed ? groupMenus.map(menu => {
                      const isFrozen = frozenIds.has(menu.id);
                      return (
                      <tr key={menu.id} className={`hover:bg-gray-50 ${isFrozen ? 'bg-amber-50/50' : ''}`}>
                        <td className="px-5 py-2.5 text-gray-700  text-sm">
                          {menu.label}
                          {isFrozen && (
                            <span className="ml-2 text-[10px] font-semibold text-amber-600 bg-amber-100 px-1.5 py-0.5 rounded">
                              Nonaktif
                            </span>
                          )}
                        </td>
                        <td className="text-center py-2.5 border-l border-gray-200 ">
                          <input type="checkbox" checked={isFrozen}
                            onChange={e => handleToggleFreeze(menu.id, e.target.checked)}
                            title={isFrozen ? 'Aktifkan kembali menu ini' : 'Bekukan menu ini (tampil tapi tidak bisa diklik)'}
                            className="w-4 h-4 accent-amber-500 cursor-pointer" />
                        </td>
                        {roles.map(role => (
                          CRUD_ACTIONS.map(action => {
                            const checked = !!permissions[role]?.[menu.id]?.[action];
                            return (
                              <td key={`${role}-${menu.id}-${action}`}
                                className="text-center py-2.5 border-l border-gray-200 ">
                                <div className="flex items-center justify-center">
                                  {checked
                                    ? <button onClick={() => handleToggle(role, menu.id, action)}
                                        className="w-7 h-7 rounded-lg bg-green-100 flex items-center justify-center hover:bg-green-200 transition-colors">
                                        <Check size={13} className="text-green-600" />
                                      </button>
                                    : <button onClick={() => handleToggle(role, menu.id, action)}
                                        className="w-7 h-7 rounded-lg bg-red-50 flex items-center justify-center hover:bg-red-100 transition-colors">
                                        <X size={13} className="text-red-400" />
                                      </button>
                                  }
                                </div>
                              </td>
                            );
                          })
                        ))}
                      </tr>
                      );
                    }) : [])
                  ];
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Toast notification */}
      {toast && (
        <div className={`fixed bottom-5 right-5 z-50 px-4 py-3 rounded-xl shadow-lg text-sm font-medium flex items-center gap-2 ${
          toast.type === 'error'
            ? 'bg-red-500 text-white'
            : 'bg-emerald-500 text-white'
        }`}>
          {toast.type === 'error' ? <X size={14}/> : <Check size={14}/>}
          {toast.msg}
        </div>
      )}
    </div>
  );
}




