import { useEffect, useState } from "react";

import { API_BASE_URL, API_ENDPOINTS } from "@/config/api";
import { useLocation } from "react-router-dom";
import ImportExcelModal from "@/components/ImportExcelModal";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import WargaTable from "./WargaTable";
import WargaForm from "./WargaForm";
import {
  AlertDialog,
  AlertDialogContent,
  AlertDialogHeader,
  AlertDialogFooter,
  AlertDialogTitle,
  AlertDialogCancel,
  AlertDialogAction
} from "@/components/ui/alert-dialog";
import { useAuth } from "@/contexts/AuthContext";
import { toast } from "@/components/ui/sonner";
import { useRolePermissions } from "@/hooks/useRolePermissions";

export default function WargaPage() {
  const location = useLocation();
  const [data, setData] = useState([]);
  const [search, setSearch] = useState("");
  const { token, logout, user } = useAuth();
  const { canCreate, canDelete } = useRolePermissions(user?.role, token);

  // FORM
  const [openForm, setOpenForm] = useState(false);
  const [selectedWarga, setSelectedWarga] = useState(null);

  // MULTI SELECT
  const [selectedRows, setSelectedRows] = useState([]);

  // FILTER
  const [showFilter, setShowFilter] = useState(false);
  const [filterStatus, setFilterStatus] = useState("all");
  const [filterGender, setFilterGender] = useState("all");
  const [filterPosisi, setFilterPosisi] = useState("all");
  const [filterBlok, setFilterBlok] = useState("all");
  const [filterStrata, setFilterStrata] = useState("all");
  const [filterBantuan, setFilterBantuan] = useState("all");
  const [filterPunyaUser, setFilterPunyaUser] = useState("all");
  const [filterAgama, setFilterAgama] = useState("all");
  const [filterPekerjaan, setFilterPekerjaan] = useState("all");
  const [filterUmur, setFilterUmur] = useState("all");
  const [filterKewarganegaraan, setFilterKewarganegaraan] = useState("all");

  // Kelompok umur — sama persis dengan kategori di chart Dashboard ("Jumlah Warga Berdasarkan Umur")
  const UMUR_BUCKETS = ["0-5", "6-12", "13-19", "20-40", "41-60", "60+"];
  const getUmurBucket = (tanggalLahir) => {
    if (!tanggalLahir) return null;
    const birth = new Date(tanggalLahir);
    if (isNaN(birth.getTime())) return null;
    const now = new Date();
    let age = now.getFullYear() - birth.getFullYear();
    const m = now.getMonth() - birth.getMonth();
    if (m < 0 || (m === 0 && now.getDate() < birth.getDate())) age--;
    if (age <= 5) return "0-5";
    if (age <= 12) return "6-12";
    if (age <= 19) return "13-19";
    if (age <= 40) return "20-40";
    if (age <= 60) return "41-60";
    return "60+";
  };

  // PAGINATION
  const [page, setPage] = useState(1);
  const [perPage, setPerPage] = useState(5);

  // BULK DELETE DIALOG
  const [openBulkDelete, setOpenBulkDelete] = useState(false);

  // IMPORT EXCEL
  const [showImportModal, setShowImportModal] = useState(false);

  const loadWarga = async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/warga`, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (res.status === 401) {
        logout();
        return;
      }

      const json = await res.json();
      setData(json);
    } catch (err) {
      console.error("Gagal load warga", err);
      toast.error("Gagal memuat data warga");
    }
  };

  useEffect(() => {
    loadWarga();
  }, []);

  // Auto-search dari state (misal dari IPL page)
  useEffect(() => {
    if (location.state?.searchName) {
      setSearch(location.state.searchName);
    }
  }, [location.state?.searchName]);

  // Nilai unik dari data yang sedang dimuat — dipakai buat isi pilihan dropdown filter
  // supaya selalu sesuai dengan data riil (bukan daftar statis yang bisa ketinggalan zaman).
  // Pakai natural sort (numeric: true) supaya "Desil 2" < "Desil 10", bukan urut abjad ("Desil 10" < "Desil 2").
  const naturalSort = (a, b) => a.localeCompare(b, undefined, { numeric: true, sensitivity: "base" });
  const uniqueValues = (key) =>
    Array.from(new Set(data.map((w) => w[key]).filter(Boolean))).sort(naturalSort);
  const posisiOptions = uniqueValues("posisi_keluarga");
  const blokOptions = uniqueValues("blok_rumah");
  const strataOptions = uniqueValues("strata_ekonomi");
  const agamaOptions = uniqueValues("agama");
  const pekerjaanOptions = uniqueValues("pekerjaan");
  const statusOptions = Array.from(
    new Set(data.map((w) => w.status_detail || (w.status === "active" ? "Aktif" : "Tidak Aktif")))
  ).sort(naturalSort);
  const bantuanOptions = Array.from(
    new Set(data.flatMap((w) => w.bantuan_diterima || []))
  ).sort();

  // FILTER LOGIC — pencarian mencakup nama, no WhatsApp, dan blok/no rumah biar lebih akurat
  const filtered = data
    .filter((w) => {
      if (!search) return true;
      const s = search.toLowerCase();
      return (
        (w.nama_lengkap || "").toLowerCase().includes(s) ||
        (w.whatsapp || "").toLowerCase().includes(s) ||
        (w.blok_rumah || "").toLowerCase().includes(s)
      );
    })
    .filter((w) => {
      if (filterStatus === "all") return true;
      const s = w.status_detail || (w.status === "active" ? "Aktif" : "Tidak Aktif");
      return s === filterStatus;
    })
    .filter((w) => {
      if (filterGender === "L") return w.jenis_kelamin === "Laki-laki";
      if (filterGender === "P") return w.jenis_kelamin === "Perempuan";
      return true;
    })
    .filter((w) => filterPosisi === "all" || w.posisi_keluarga === filterPosisi)
    .filter((w) => filterBlok === "all" || w.blok_rumah === filterBlok)
    .filter((w) => filterStrata === "all" || w.strata_ekonomi === filterStrata)
    .filter((w) => filterBantuan === "all" || (w.bantuan_diterima || []).includes(filterBantuan))
    .filter((w) => filterAgama === "all" || w.agama === filterAgama)
    .filter((w) => filterPekerjaan === "all" || w.pekerjaan === filterPekerjaan)
    .filter((w) => filterUmur === "all" || getUmurBucket(w.tanggal_lahir) === filterUmur)
    .filter((w) => {
      if (filterKewarganegaraan === "all") return true;
      const kode = (w.kewarganegaraan || "").trim().toUpperCase();
      const isWNI = kode === "" || kode === "ID";
      return filterKewarganegaraan === "wni" ? isWNI : !isWNI;
    })
    .filter((w) => {
      if (filterPunyaUser === "all") return true;
      return filterPunyaUser === "ya" ? !!w.has_user : !w.has_user;
    });

  // PAGINATION
  const totalPages = Math.ceil(filtered.length / perPage);
  const paginatedData = filtered.slice((page - 1) * perPage, page * perPage);

  // Bangun query string dari filter yang sedang aktif — dipakai bareng oleh export Excel & PDF
  // supaya hasil export selalu sesuai dengan data yang sedang difilter di layar.
  const buildFilterParams = () => {
    const params = new URLSearchParams();
    if (search) params.set('search', search);
    if (filterStatus !== 'all') params.set('status', filterStatus);
    if (filterGender !== 'all') params.set('gender', filterGender === 'L' ? 'Laki-laki' : 'Perempuan');
    if (filterPosisi !== 'all') params.set('posisi', filterPosisi);
    if (filterBlok !== 'all') params.set('blok', filterBlok);
    if (filterStrata !== 'all') params.set('strata', filterStrata);
    if (filterBantuan !== 'all') params.set('bantuan', filterBantuan);
    if (filterPunyaUser !== 'all') params.set('punya_user', filterPunyaUser);
    if (filterAgama !== 'all') params.set('agama', filterAgama);
    if (filterPekerjaan !== 'all') params.set('pekerjaan', filterPekerjaan);
    if (filterUmur !== 'all') params.set('umur', filterUmur);
    if (filterKewarganegaraan !== 'all') params.set('kewarganegaraan', filterKewarganegaraan);
    return params.toString();
  };

  // EXPORT EXCEL
  const [exporting, setExporting] = useState(false);
  const exportExcel = async () => {
    setExporting(true);
    try {
      const qs = buildFilterParams();
      const res = await fetch(`${API_ENDPOINTS.EXPORT_EXCEL_WARGA}${qs ? `?${qs}` : ''}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (res.status === 401) { logout(); return; }
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const blob = await res.blob();
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `daftar-warga-${new Date().toISOString().slice(0, 10)}.xlsx`;
      a.click();
      URL.revokeObjectURL(url);
    } catch (err) {
      console.error('Gagal export warga', err);
      toast.error('Gagal mengekspor data warga');
    } finally {
      setExporting(false);
    }
  };

  // PRINT / EXPORT PDF (kolom & filter sama dengan Export Excel)
  const [printingPdf, setPrintingPdf] = useState(false);
  const exportPdf = async () => {
    setPrintingPdf(true);
    try {
      const qs = buildFilterParams();
      const res = await fetch(`${API_ENDPOINTS.EXPORT_EXCEL_WARGA}/pdf${qs ? `?${qs}` : ''}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (res.status === 401) { logout(); return; }
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const blob = await res.blob();
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `daftar-warga-${new Date().toISOString().slice(0, 10)}.pdf`;
      a.click();
      URL.revokeObjectURL(url);
    } catch (err) {
      console.error('Gagal export PDF warga', err);
      toast.error('Gagal membuat PDF data warga');
    } finally {
      setPrintingPdf(false);
    }
  };

  // BULK DELETE
  const doBulkDelete = async () => {
    for (const id of selectedRows) {
      await fetch(`${API_BASE_URL}/api/warga/${id}`, {
        method: "DELETE",
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });
    }
    toast.success(`${selectedRows.length} warga berhasil dihapus`);
    loadWarga();
    setSelectedRows([]);
    setOpenBulkDelete(false);
  };

  return (
    <div className="p-6 space-y-4">
      {/* HEADER */}
      <div className="flex flex-col sm:flex-row sm:justify-between sm:items-center gap-3">
        <div>
          <h1 className="text-3xl font-bold dark:text-gray-100">
            {user?.role === "warga" ? "Data Keluarga Saya" : "Daftar Warga"}
          </h1>
          <p className="text-sm text-gray-600 dark:text-gray-400">
            {user?.role === "warga" ? "Anggota keluarga di rumah Anda" : "Kelola data warga"}
          </p>
        </div>
        <div className="flex flex-wrap gap-2 sm:justify-end">
          {user?.role !== "warga" && (
          <Button
            variant="outline"
            onClick={exportExcel}
            disabled={exporting}
            className="flex-1 basis-[calc(50%-4px)] sm:basis-auto sm:flex-none border-blue-600 text-blue-700 hover:bg-blue-50 dark:border-blue-500 dark:text-blue-400 px-2 sm:px-4 text-xs sm:text-sm"
          >
            <span className="sm:hidden">⬇ Excel</span>
            <span className="hidden sm:inline">{exporting ? "Mengekspor..." : "⬇ Export Excel"}</span>
          </Button>
          )}
          {user?.role !== "warga" && (
          <Button
            variant="outline"
            onClick={exportPdf}
            disabled={printingPdf}
            className="flex-1 basis-[calc(50%-4px)] sm:basis-auto sm:flex-none border-orange-600 text-orange-700 hover:bg-orange-50 dark:border-orange-500 dark:text-orange-400 px-2 sm:px-4 text-xs sm:text-sm"
          >
            <span className="sm:hidden">🖨 PDF</span>
            <span className="hidden sm:inline">{printingPdf ? "Membuat PDF..." : "🖨 Print PDF"}</span>
          </Button>
          )}
          {canCreate('warga') && (
            <>
              <Button
                variant="outline"
                onClick={() => setShowImportModal(true)}
                className="flex-1 basis-[calc(50%-4px)] sm:basis-auto sm:flex-none border-green-600 text-green-700 hover:bg-green-50 dark:border-green-500 dark:text-green-400 px-2 sm:px-4 text-xs sm:text-sm"
              >
                <span className="sm:hidden">⬆ Import</span>
                <span className="hidden sm:inline">⬆ Import Excel</span>
              </Button>
              <Button
                onClick={() => {
                  setSelectedWarga(null);
                  setOpenForm(true);
                }}
                className="flex-1 basis-[calc(50%-4px)] sm:basis-auto sm:flex-none bg-[var(--rw-primary)] hover:bg-[var(--rw-primary-hover)] text-white px-2 sm:px-4 text-xs sm:text-sm"
              >
                <span className="sm:hidden">+ Tambah</span>
                <span className="hidden sm:inline">+ Tambah Warga</span>
              </Button>
            </>
          )}
        </div>
      </div>

      {/* SEARCH & FILTER */}
      <div className="flex gap-3">
        <Input
          placeholder="Cari nama, no WhatsApp, atau blok/no rumah..."
          value={search}
          onChange={(e) => {
            setSearch(e.target.value);
            setPage(1);
          }}
          className="flex-1 dark:bg-gray-800 dark:text-gray-100 dark:border-gray-700"
        />
        <Button
          variant="outline"
          onClick={() => setShowFilter(!showFilter)}
          className="dark:border-gray-700 dark:text-gray-200"
        >
          Filter
        </Button>
      </div>

      {/* FILTER PANEL */}
      {showFilter && (
        <div className="bg-[var(--rw-bg-card)] dark:bg-gray-900 p-6 rounded-lg border dark:border-gray-700 space-y-4">
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            {/* STATUS */}
            <div>
              <label className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase">Status</label>
              <select
                value={filterStatus}
                onChange={(e) => { setFilterStatus(e.target.value); setPage(1); }}
                className="w-full p-2 mt-2 border rounded-md dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100 bg-[var(--rw-bg-card-alt)]"
              >
                <option value="all">Semua</option>
                {statusOptions.map((s) => <option key={s} value={s}>{s}</option>)}
              </select>
            </div>

            {/* JENIS KELAMIN */}
            <div>
              <label className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase">Jenis Kelamin</label>
              <select
                value={filterGender}
                onChange={(e) => { setFilterGender(e.target.value); setPage(1); }}
                className="w-full p-2 mt-2 border rounded-md dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100 bg-[var(--rw-bg-card-alt)]"
              >
                <option value="all">Semua</option>
                <option value="L">Laki-laki</option>
                <option value="P">Perempuan</option>
              </select>
            </div>

            {/* POSISI KELUARGA */}
            <div>
              <label className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase">Posisi Keluarga</label>
              <select
                value={filterPosisi}
                onChange={(e) => { setFilterPosisi(e.target.value); setPage(1); }}
                className="w-full p-2 mt-2 border rounded-md dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100 bg-[var(--rw-bg-card-alt)]"
              >
                <option value="all">Semua</option>
                {posisiOptions.map((p) => <option key={p} value={p}>{p}</option>)}
              </select>
            </div>

            {/* BLOK / NO RUMAH */}
            <div>
              <label className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase">Blok / No Rumah</label>
              <select
                value={filterBlok}
                onChange={(e) => { setFilterBlok(e.target.value); setPage(1); }}
                className="w-full p-2 mt-2 border rounded-md dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100 bg-[var(--rw-bg-card-alt)]"
              >
                <option value="all">Semua</option>
                {blokOptions.map((b) => <option key={b} value={b}>{b}</option>)}
              </select>
            </div>

            {/* STRATA EKONOMI */}
            <div>
              <label className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase">Strata Ekonomi</label>
              <select
                value={filterStrata}
                onChange={(e) => { setFilterStrata(e.target.value); setPage(1); }}
                className="w-full p-2 mt-2 border rounded-md dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100 bg-[var(--rw-bg-card-alt)]"
              >
                <option value="all">Semua</option>
                {strataOptions.map((s) => <option key={s} value={s}>{s}</option>)}
              </select>
            </div>

            {/* BANTUAN */}
            <div>
              <label className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase">Bantuan Diterima</label>
              <select
                value={filterBantuan}
                onChange={(e) => { setFilterBantuan(e.target.value); setPage(1); }}
                className="w-full p-2 mt-2 border rounded-md dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100 bg-[var(--rw-bg-card-alt)]"
              >
                <option value="all">Semua</option>
                {bantuanOptions.map((b) => <option key={b} value={b}>{b}</option>)}
              </select>
            </div>

            {/* AGAMA */}
            <div>
              <label className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase">Agama</label>
              <select
                value={filterAgama}
                onChange={(e) => { setFilterAgama(e.target.value); setPage(1); }}
                className="w-full p-2 mt-2 border rounded-md dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100 bg-[var(--rw-bg-card-alt)]"
              >
                <option value="all">Semua</option>
                {agamaOptions.map((a) => <option key={a} value={a}>{a}</option>)}
              </select>
            </div>

            {/* PEKERJAAN */}
            <div>
              <label className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase">Pekerjaan</label>
              <select
                value={filterPekerjaan}
                onChange={(e) => { setFilterPekerjaan(e.target.value); setPage(1); }}
                className="w-full p-2 mt-2 border rounded-md dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100 bg-[var(--rw-bg-card-alt)]"
              >
                <option value="all">Semua</option>
                {pekerjaanOptions.map((p) => <option key={p} value={p}>{p}</option>)}
              </select>
            </div>

            {/* UMUR — kategori sama seperti chart di Dashboard */}
            <div>
              <label className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase">Umur</label>
              <select
                value={filterUmur}
                onChange={(e) => { setFilterUmur(e.target.value); setPage(1); }}
                className="w-full p-2 mt-2 border rounded-md dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100 bg-[var(--rw-bg-card-alt)]"
              >
                <option value="all">Semua</option>
                {UMUR_BUCKETS.map((u) => <option key={u} value={u}>{u} Tahun</option>)}
              </select>
            </div>

            {/* KEWARGANEGARAAN — dipetakan dari kode negara: ID = WNI, selain itu = WNA */}
            <div>
              <label className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase">Kewarganegaraan</label>
              <select
                value={filterKewarganegaraan}
                onChange={(e) => { setFilterKewarganegaraan(e.target.value); setPage(1); }}
                className="w-full p-2 mt-2 border rounded-md dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100 bg-[var(--rw-bg-card-alt)]"
              >
                <option value="all">Semua</option>
                <option value="wni">WNI</option>
                <option value="wna">WNA</option>
              </select>
            </div>

            {/* PUNYA USER */}
            {user?.role !== "warga" && (
              <div>
                <label className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase">Punya User</label>
                <select
                  value={filterPunyaUser}
                  onChange={(e) => { setFilterPunyaUser(e.target.value); setPage(1); }}
                  className="w-full p-2 mt-2 border rounded-md dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100 bg-[var(--rw-bg-card-alt)]"
                >
                  <option value="all">Semua</option>
                  <option value="ya">Sudah Punya User</option>
                  <option value="tidak">Belum Punya User</option>
                </select>
              </div>
            )}

            {/* PER HALAMAN */}
            <div>
              <label className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase">Per Halaman</label>
              <select
                value={perPage}
                onChange={(e) => { setPerPage(Number(e.target.value)); setPage(1); }}
                className="w-full p-2 mt-2 border rounded-md dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100 bg-[var(--rw-bg-card-alt)]"
              >
                <option value="5">5</option>
                <option value="10">10</option>
                <option value="25">25</option>
              </select>
            </div>
          </div>

          {(filterStatus !== 'all' || filterGender !== 'all' || filterPosisi !== 'all' || filterBlok !== 'all' ||
            filterStrata !== 'all' || filterBantuan !== 'all' || filterPunyaUser !== 'all' ||
            filterAgama !== 'all' || filterPekerjaan !== 'all' || filterUmur !== 'all' ||
            filterKewarganegaraan !== 'all' || search) && (
            <button
              onClick={() => {
                setSearch(''); setFilterStatus('all'); setFilterGender('all'); setFilterPosisi('all');
                setFilterBlok('all'); setFilterStrata('all'); setFilterBantuan('all'); setFilterPunyaUser('all');
                setFilterAgama('all'); setFilterPekerjaan('all'); setFilterUmur('all');
                setFilterKewarganegaraan('all');
                setPage(1);
              }}
              className="text-xs text-blue-600 dark:text-blue-400 hover:underline"
            >
              Reset semua filter
            </button>
          )}
        </div>
      )}

      {/* ACTIONS */}
      {selectedRows.length > 0 && canDelete('warga') && (
        <div className="flex gap-3 bg-blue-50 dark:bg-blue-900/20 p-4 rounded-lg border border-blue-200 dark:border-blue-800">
          <span className="text-sm dark:text-gray-300">
            {selectedRows.length} item dipilih
          </span>
          <Button
            size="sm"
            variant="destructive"
            onClick={() => setOpenBulkDelete(true)}
          >
            Hapus
          </Button>
          {user?.role !== "warga" && (
          <Button
            size="sm"
            onClick={exportExcel}
            className="bg-green-500 hover:bg-green-600 text-white"
          >
            Export Excel
          </Button>
          )}
        </div>
      )}

      {/* TABLE */}
      <div className="bg-[var(--rw-bg-card)] dark:bg-gray-900 rounded-lg border dark:border-gray-700">
        <WargaTable
          data={paginatedData}
          onEdit={(w) => {
            setSelectedWarga(w);
            setOpenForm(true);
          }}
          onDelete={loadWarga}
          selectedRows={selectedRows}
          setSelectedRows={setSelectedRows}
        />
      </div>

      {/* PAGINATION INFO */}
      <div className="flex justify-between items-center text-sm text-gray-600 dark:text-gray-400 px-2">
        <span>
          {filtered.length === 0 ? "Tidak ada data" : `${(page - 1) * perPage + 1}-${Math.min(page * perPage, filtered.length)} dari ${filtered.length}`}
        </span>
        <div className="flex gap-2">
          <Button
            size="sm"
            variant="outline"
            onClick={() => setPage(Math.max(1, page - 1))}
            disabled={page === 1}
            className="dark:border-gray-700 dark:text-gray-200"
          >
            Sebelumnya
          </Button>
          <Button
            size="sm"
            variant="outline"
            onClick={() => setPage(Math.min(totalPages, page + 1))}
            disabled={page === totalPages}
            className="dark:border-gray-700 dark:text-gray-200"
          >
            Selanjutnya
          </Button>
        </div>
      </div>

      {/* FORM DIALOG */}
      <WargaForm
        open={openForm}
        onOpenChange={setOpenForm}
        warga={selectedWarga}
        onSaved={() => {
          loadWarga();
          setSelectedWarga(null);
        }}
      />

      {/* BULK DELETE DIALOG */}
      <AlertDialog open={openBulkDelete} onOpenChange={setOpenBulkDelete}>
        <AlertDialogContent className="bg-[var(--rw-bg-card)] dark:bg-gray-900 dark:text-gray-100">
          <AlertDialogHeader>
            <AlertDialogTitle>Hapus {selectedRows.length} Warga?</AlertDialogTitle>
          </AlertDialogHeader>
          <p className="text-sm text-gray-600 dark:text-gray-400">
            Tindakan ini tidak dapat dibatalkan.
          </p>
          <AlertDialogFooter>
            <AlertDialogCancel className="dark:bg-gray-800 dark:text-gray-200">
              Batal
            </AlertDialogCancel>
            <AlertDialogAction
              onClick={doBulkDelete}
              className="bg-red-600 hover:bg-red-700"
            >
              Hapus Semua
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* IMPORT EXCEL MODAL */}
      <ImportExcelModal
        show={showImportModal}
        onClose={() => setShowImportModal(false)}
        onImported={loadWarga}
        title="Import Data Warga dari Excel"
        templateUrl={API_ENDPOINTS.IMPORT_EXCEL_TEMPLATE_WARGA}
        importUrl={API_ENDPOINTS.IMPORT_EXCEL_WARGA}
        templateName="template_warga.xlsx"
        columns={[
          'Nama Lengkap *', 'No WhatsApp', 'Tanggal Lahir', 'Tempat Lahir',
          'Jenis Kelamin', 'Agama', 'Pekerjaan', 'Posisi Keluarga',
          'Blok/No Rumah', 'Status', 'Strata Ekonomi', 'Bantuan Diterima',
        ]}
        importModes={[
          {
            value: 'upsert',
            label: 'Insert / Update',
            description: 'Data baru otomatis ditambahkan. Kalau No WhatsApp sudah ada, datanya akan diperbarui (bukan dobel).',
          },
          {
            value: 'replace',
            label: 'Hapus Data',
            description: 'Seluruh data warga di RT ini dihapus dulu, baru diganti sepenuhnya dengan data dari file.',
          },
        ]}
      />
    </div>
  );
}
