import React, { useState, useEffect } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { useNavigate } from 'react-router-dom';
import { Bell, RefreshCw, ChevronRight } from 'lucide-react';
import { Button } from '../components/ui/button';
import {
  useNotifications, getNotifSourceMeta, getNotifDestination,
} from '../hooks/useNotifications';

const ROLE_SCOPE_LABELS = {
  admin: 'RT',
  pengurus_rw: 'RW',
  pengurus_kelurahan: 'Kelurahan',
  warga: 'Warga',
};

const Notifikasi = () => {
  const { user, token } = useAuth();
  const navigate = useNavigate();
  const {
    notifList, loading, refetch, isRTAdmin, isPengurusRW, isPengurusKelurahan,
  } = useNotifications(token, user);

  const notifStorageKey = `notif_read_${user?.username || 'u'}`;
  const [readIds, setReadIds] = useState([]);

  useEffect(() => {
    if (!user?.username) return;
    try { setReadIds(JSON.parse(localStorage.getItem(notifStorageKey) || '[]')); }
    catch { setReadIds([]); }
  }, [user?.username, notifStorageKey]);

  const markRead = (id) => {
    if (readIds.includes(id)) return;
    const next = [...readIds, id];
    setReadIds(next);
    localStorage.setItem(notifStorageKey, JSON.stringify(next));
  };

  const handleClick = (n) => {
    markRead(n.id);
    const { path, state } = getNotifDestination(n, { isPengurusRW, isPengurusKelurahan, isRTAdmin });
    navigate(path, state ? { state } : undefined);
  };

  const unreadCount = notifList.filter(n => !readIds.includes(n.id)).length;

  return (
    <div className="p-4 sm:p-6 max-w-3xl mx-auto">
      <div className="flex items-center justify-between mb-1">
        <div className="flex items-center gap-2">
          <Bell className="h-5 w-5 text-[var(--rw-primary)]" />
          <h1 className="text-xl font-bold text-gray-800 dark:text-white">Semua Notifikasi</h1>
        </div>
        <Button variant="ghost" size="icon" onClick={refetch} disabled={loading} title="Muat ulang">
          <RefreshCw className={`h-4 w-4 ${loading ? 'animate-spin' : ''}`} />
        </Button>
      </div>
      <p className="text-sm text-gray-500 dark:text-gray-400 mb-4">
        Semua notifikasi untuk akun {ROLE_SCOPE_LABELS[user?.role] || ''} kamu, digabung dari semua sumber.
        {unreadCount > 0 ? ` ${unreadCount} belum dibaca.` : ' Semua sudah terbaca.'}
      </p>

      <div className="bg-[var(--rw-bg-card)] dark:bg-gray-900 border border-[var(--rw-border)] dark:border-gray-700 rounded-xl overflow-hidden">
        {notifList.length === 0 ? (
          <div className="py-16 text-center text-sm text-gray-400">
            {loading ? 'Memuat notifikasi...' : 'Tidak ada notifikasi'}
          </div>
        ) : (
          notifList.map((n) => {
            const isRead = readIds.includes(n.id);
            const meta = getNotifSourceMeta(n);
            return (
              <button
                key={n.id}
                onClick={() => handleClick(n)}
                className={`w-full text-left px-4 sm:px-5 py-4 border-b border-[#e8e0cb] dark:border-gray-800 last:border-b-0 hover:bg-[var(--rw-bg-card-alt)] dark:hover:bg-gray-800 flex items-start gap-3 transition-colors ${isRead ? 'opacity-60' : ''}`}
              >
                <span className={`mt-2 w-2 h-2 rounded-full flex-shrink-0 ${isRead ? 'bg-transparent' : 'bg-[var(--rw-primary)]'}`} />
                <div className="min-w-0 flex-1">
                  <div className="flex items-center gap-2 flex-wrap mb-0.5">
                    <span className={`flex-shrink-0 text-[10px] px-2 py-0.5 rounded-full font-semibold ${meta.badgeClass}`}>
                      {meta.label}
                    </span>
                    <p className={`text-sm ${isRead ? 'font-normal text-gray-600 dark:text-gray-400' : 'font-semibold text-gray-800 dark:text-white'}`}>
                      {n.judul}
                    </p>
                  </div>
                  {n.isi && (
                    <p className="text-sm text-gray-500 dark:text-gray-400 mt-0.5">{n.isi}</p>
                  )}
                  <p className="text-[11px] text-gray-400 mt-1.5">
                    {n.published_at
                      ? new Date(n.published_at).toLocaleString('id-ID', { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' })
                      : ''}
                  </p>
                </div>
                <ChevronRight className="h-4 w-4 text-gray-300 dark:text-gray-600 flex-shrink-0 mt-1.5" />
              </button>
            );
          })
        )}
      </div>
    </div>
  );
};

export default Notifikasi;
