import React, { useState, useEffect } from 'react';
import ReactDOM from 'react-dom';
import axios from 'axios';
import { useNavigate, useLocation } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { API_BASE_URL } from '../config/api';
import { toast } from '@/components/ui/sonner';
import {
  AlertDialog,
  AlertDialogContent,
  AlertDialogHeader,
  AlertDialogFooter,
  AlertDialogTitle,
  AlertDialogCancel,
  AlertDialogAction
} from '@/components/ui/alert-dialog';
import {
  Newspaper, Plus, Pencil, Trash2, Pin, PinOff, CheckCircle, XCircle,
  Eye, X, Image as ImageIcon, Video, Search
} from 'lucide-react';

const emptyForm = {
  tanggal: new Date().toISOString().split('T')[0],
  kategori: '',
  judul: '',
  konten: '',
  video_url: '',
  pin: false,
  aktif: true,
};

const ORIGIN_BADGE_CLS = {
  RT: 'bg-blue-100 text-blue-700 border-blue-300 dark:bg-blue-900/30 dark:text-blue-400 dark:border-blue-700',
  RW: 'bg-purple-100 text-purple-700 border-purple-300 dark:bg-purple-900/30 dark:text-purple-400 dark:border-purple-700',
  Kelurahan: 'bg-emerald-100 text-emerald-700 border-emerald-300 dark:bg-emerald-900/30 dark:text-emerald-400 dark:border-emerald-700',
};

function OriginBadge({ type, name }) {
  if (!type) return null;
  return (
    <span className={`inline-flex items-center gap-1 text-xs px-2 py-0.5 rounded-full font-medium border ${ORIGIN_BADGE_CLS[type] || 'bg-gray-100 text-gray-600 border-gray-300'}`}>
      {type}{name ? ` · ${name}` : ''}
    </span>
  );
}

export default function Informasi({ basePath = '/informasi' }) {
  const { token } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [editItem, setEditItem] = useState(null);
  const [form, setForm] = useState(emptyForm);
  const [gambarHeaderFile, setGambarHeaderFile] = useState(null);
  const [gambarHeaderPreview, setGambarHeaderPreview] = useState(null);
  const [galeriFiles, setGaleriFiles] = useState([]);
  const [saving, setSaving] = useState(false);
  const [deleteId, setDeleteId] = useState(null);
  const [kategoriRefOptions, setKategoriRefOptions] = useState([]);
  const [lightboxImg, setLightboxImg] = useState(null);
  const [incoming, setIncoming] = useState([]);

  const headers = { Authorization: `Bearer ${token}` };

  const fetchData = async () => {
    setLoading(true);
    try {
      const res = await axios.get(`${API_BASE_URL}/api/informasi/`, { headers });
      setData(res.data.data || []);
    } catch (e) {
      toast.error('Gagal memuat data informasi');
    } finally {
      setLoading(false);
    }
  };

  const fetchIncoming = async () => {
    try {
      const res = await axios.get(`${API_BASE_URL}/api/informasi/incoming`, { headers });
      setIncoming(res.data.data || []);
    } catch (e) {
      setIncoming([]);
    }
  };

  const fetchKategoriRef = async () => {
    try {
      const res = await axios.get(`${API_BASE_URL}/api/referensi/kategori-informasi`);
      setKategoriRefOptions(res.data || []);
    } catch (e) {
      setKategoriRefOptions([]);
    }
  };

  useEffect(() => { fetchData(); fetchKategoriRef(); fetchIncoming(); /* eslint-disable-next-line */ }, [token]);

  // Kalau datang dari halaman detail (tombol Edit) dengan state editId, langsung buka form edit
  useEffect(() => {
    const editId = location.state?.editId;
    if (editId && data.length > 0) {
      const item = data.find(d => d.id === editId);
      if (item) openEdit(item);
      navigate(location.pathname, { replace: true, state: {} });
    }
    
  }, [location.state, data]);

  const openCreate = () => {
    setEditItem(null);
    setForm(emptyForm);
    setGambarHeaderFile(null);
    setGambarHeaderPreview(null);
    setGaleriFiles([]);
    setShowForm(true);
  };

  const openEdit = (item) => {
    setEditItem(item);
    setForm({
      tanggal: item.tanggal ? item.tanggal.split('T')[0] : '',
      kategori: item.kategori || '',
      judul: item.judul || '',
      konten: item.konten || '',
      video_url: item.video_url || '',
      pin: !!item.pin,
      aktif: !!item.aktif,
    });
    setGambarHeaderFile(null);
    setGambarHeaderPreview(item.gambar_header ? `${API_BASE_URL}/${item.gambar_header}` : null);
    setGaleriFiles([]);
    setShowForm(true);
  };

  const handleGambarHeaderChange = (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setGambarHeaderFile(file);
    setGambarHeaderPreview(URL.createObjectURL(file));
  };

  const handleSubmit = async () => {
    if (!form.tanggal || !form.kategori || !form.judul) {
      toast.error('Tanggal, Kategori, dan Judul wajib diisi');
      return;
    }
    setSaving(true);
    try {
      const fd = new FormData();
      fd.append('tanggal', form.tanggal);
      fd.append('kategori', form.kategori);
      fd.append('judul', form.judul);
      fd.append('konten', form.konten || '');
      fd.append('video_url', form.video_url || '');
      fd.append('pin', form.pin);
      fd.append('aktif', form.aktif);
      if (gambarHeaderFile) fd.append('gambar_header', gambarHeaderFile);
      galeriFiles.forEach(f => fd.append('galeri', f));

      const uploadHeaders = { ...headers, 'Content-Type': 'multipart/form-data' };

      if (editItem) {
        await axios.put(`${API_BASE_URL}/api/informasi/${editItem.id}`, fd, { headers: uploadHeaders });
        toast.success('Informasi berhasil diperbarui');
      } else {
        await axios.post(`${API_BASE_URL}/api/informasi/`, fd, { headers: uploadHeaders });
        toast.success('Informasi berhasil ditambahkan');
      }
      setShowForm(false);
      fetchData();
    } catch (e) {
      toast.error(e?.response?.data?.detail || 'Gagal menyimpan informasi');
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async () => {
    if (!deleteId) return;
    try {
      await axios.delete(`${API_BASE_URL}/api/informasi/${deleteId}`, { headers });
      toast.success('Informasi berhasil dihapus');
      setDeleteId(null);
      fetchData();
    } catch (e) {
      toast.error('Gagal menghapus informasi');
    }
  };

  const togglePin = async (item) => {
    try {
      await axios.post(`${API_BASE_URL}/api/informasi/${item.id}/toggle-pin`, {}, { headers });
      fetchData();
    } catch (e) {
      toast.error('Gagal mengubah Pin Informasi');
    }
  };

  const toggleAktif = async (item) => {
    try {
      await axios.post(`${API_BASE_URL}/api/informasi/${item.id}/toggle-aktif`, {}, { headers });
      fetchData();
    } catch (e) {
      toast.error('Gagal mengubah status');
    }
  };

  const filtered = data.filter(d =>
    !search || d.judul.toLowerCase().includes(search.toLowerCase()) || d.kategori.toLowerCase().includes(search.toLowerCase())
  );

  const formatDate = (val) => {
    if (!val) return '-';
    const d = new Date(val);
    return d.toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' });
  };

  return (
    <div className="p-4 md:p-6 space-y-4">
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-lg bg-blue-500 flex items-center justify-center">
            <Newspaper className="w-5 h-5 text-white" />
          </div>
          <div>
            <h1 className="text-xl font-bold text-gray-900 dark:text-white">Informasi</h1>
            <p className="text-sm text-gray-500 dark:text-gray-400">Kelola informasi/berita untuk warga</p>
          </div>
        </div>
        <button
          onClick={openCreate}
          className="flex items-center gap-2 bg-[var(--rw-primary)] hover:bg-[#e15c47] text-white px-4 py-2 rounded-lg text-sm font-medium"
        >
          <Plus className="w-4 h-4" /> Tambah Informasi
        </button>
      </div>

      {incoming.length > 0 && (
        <div className="bg-[var(--rw-bg-card)] dark:bg-gray-800 rounded-lg border border-[var(--rw-border)] dark:border-gray-700 overflow-x-auto">
          <div className="p-3 border-b border-[var(--rw-border)] dark:border-gray-700">
            <h2 className="text-sm font-semibold text-gray-900 dark:text-gray-100">Informasi Masuk (dari RW / Kelurahan)</h2>
          </div>
          <table className="w-full text-sm">
            <thead>
              <tr className="text-left text-xs font-semibold text-gray-500 uppercase border-b border-[var(--rw-border)] dark:border-gray-700">
                <th className="p-3">Tanggal</th>
                <th className="p-3">Asal</th>
                <th className="p-3">Kategori</th>
                <th className="p-3">Judul</th>
                <th className="p-3 text-right">Aksi</th>
              </tr>
            </thead>
            <tbody>
              {incoming.map(item => (
                <tr key={item.id} className="border-b border-gray-100 dark:border-gray-700 last:border-0">
                  <td className="p-3 whitespace-nowrap">{formatDate(item.tanggal)}</td>
                  <td className="p-3"><OriginBadge type={item.origin_tenant_type} name={item.origin_tenant_name} /></td>
                  <td className="p-3">{item.kategori}</td>
                  <td className="p-3 font-medium text-gray-900 dark:text-gray-100">{item.judul}</td>
                  <td className="p-3 text-right">
                    <button onClick={() => navigate(`${basePath}/${item.id}`)} className="p-1.5 rounded hover:bg-gray-200 dark:hover:bg-gray-700" title="Lihat">
                      <Eye className="w-4 h-4 text-gray-600 dark:text-gray-300 inline" />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      <div className="relative max-w-sm">
        <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
        <input
          className="w-full pl-9 pr-3 py-2 rounded-lg border border-[var(--rw-border)] dark:border-gray-700 bg-[var(--rw-bg-card)] dark:bg-gray-800 text-sm"
          placeholder="Cari judul atau kategori..."
          value={search}
          onChange={e => setSearch(e.target.value)}
        />
      </div>

      <div className="bg-[var(--rw-bg-card)] dark:bg-gray-800 rounded-lg border border-[var(--rw-border)] dark:border-gray-700 overflow-x-auto">
        {loading ? (
          <div className="p-10 text-center">
            <div className="w-8 h-8 border-4 border-blue-500 border-t-transparent rounded-full animate-spin mx-auto" />
          </div>
        ) : filtered.length === 0 ? (
          <div className="p-10 text-center text-gray-400">Belum ada informasi</div>
        ) : (
          <table className="w-full text-sm">
            <thead>
              <tr className="text-left text-xs font-semibold text-gray-500 uppercase border-b border-[var(--rw-border)] dark:border-gray-700">
                <th className="p-3">Tanggal</th>
                <th className="p-3">Kategori Informasi</th>
                <th className="p-3">Judul</th>
                <th className="p-3">Gambar Header</th>
                <th className="p-3 text-center">Pin Informasi</th>
                <th className="p-3 text-center">Aktif</th>
                <th className="p-3 text-right">Aksi</th>
              </tr>
            </thead>
            <tbody>
              {filtered.map(item => (
                <tr key={item.id} className="border-b border-gray-100 dark:border-gray-700 last:border-0">
                  <td className="p-3 whitespace-nowrap">{formatDate(item.tanggal)}</td>
                  <td className="p-3">{item.kategori}</td>
                  <td className="p-3 font-medium text-gray-900 dark:text-gray-100">{item.judul}</td>
                  <td className="p-3">
                    {item.gambar_header ? (
                      <button
                        type="button"
                        onClick={() => setLightboxImg(`${API_BASE_URL}/${item.gambar_header}`)}
                        className="block rounded overflow-hidden hover:opacity-80 hover:ring-2 hover:ring-blue-400 transition"
                        title="Lihat gambar penuh"
                      >
                        <img src={`${API_BASE_URL}/${item.gambar_header}`} alt="" className="w-14 h-10 object-cover" />
                      </button>
                    ) : (
                      <div className="w-14 h-10 bg-gray-200 dark:bg-gray-700 rounded flex items-center justify-center">
                        <ImageIcon className="w-4 h-4 text-gray-400" />
                      </div>
                    )}
                  </td>
                  <td className="p-3 text-center">
                    <button onClick={() => togglePin(item)} title="Toggle Pin">
                      {item.pin ? <Pin className="w-5 h-5 text-green-600 mx-auto" /> : <PinOff className="w-5 h-5 text-red-400 mx-auto" />}
                    </button>
                  </td>
                  <td className="p-3 text-center">
                    <button onClick={() => toggleAktif(item)} title="Toggle Status">
                      {item.aktif ? <CheckCircle className="w-5 h-5 text-green-600 mx-auto" /> : <XCircle className="w-5 h-5 text-red-400 mx-auto" />}
                    </button>
                  </td>
                  <td className="p-3">
                    <div className="flex items-center justify-end gap-2">
                      <button onClick={() => navigate(`${basePath}/${item.id}`)} className="p-1.5 rounded hover:bg-gray-200 dark:hover:bg-gray-700" title="Lihat">
                        <Eye className="w-4 h-4 text-gray-600 dark:text-gray-300" />
                      </button>
                      <button onClick={() => openEdit(item)} className="p-1.5 rounded hover:bg-gray-200 dark:hover:bg-gray-700" title="Edit">
                        <Pencil className="w-4 h-4 text-blue-600" />
                      </button>
                      <button onClick={() => setDeleteId(item.id)} className="p-1.5 rounded hover:bg-gray-200 dark:hover:bg-gray-700" title="Hapus">
                        <Trash2 className="w-4 h-4 text-red-500" />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>

      {/* Form Modal (Tambah/Edit) — pakai portal ke document.body supaya backdrop bener-bener full halaman,
          gak kepotong sama overflow-hidden di layout (Sidebar/Header) */}
      {showForm && ReactDOM.createPortal(
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-[var(--rw-bg-card)] dark:bg-gray-900 rounded-xl shadow-xl w-full max-w-lg max-h-[90vh] overflow-y-auto">
            <div className="flex items-center justify-between p-5 border-b border-[var(--rw-border)] dark:border-gray-700">
              <h2 className="text-lg font-bold text-gray-900 dark:text-white">
                {editItem ? 'Edit Informasi' : 'Tambah Informasi'}
              </h2>
              <button onClick={() => setShowForm(false)}><X className="w-5 h-5 text-gray-500" /></button>
            </div>
            <div className="p-5 space-y-4">
              <div>
                <label className="block text-sm font-medium mb-1">Tanggal</label>
                <input
                  type="date"
                  className="w-full px-3 py-2 rounded-lg border border-[var(--rw-border)] dark:border-gray-700 bg-white dark:bg-gray-800 text-sm"
                  value={form.tanggal}
                  onChange={e => setForm(f => ({ ...f, tanggal: e.target.value }))}
                />
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">Kategori Informasi</label>
                <select
                  className="w-full px-3 py-2 rounded-lg border border-[var(--rw-border)] dark:border-gray-700 bg-white dark:bg-gray-800 text-sm"
                  value={form.kategori}
                  onChange={e => setForm(f => ({ ...f, kategori: e.target.value }))}
                >
                  <option value="">-- Pilih Kategori --</option>
                  {kategoriRefOptions.map(k => (
                    <option key={k.id} value={k.nilai}>{k.label || k.nilai}</option>
                  ))}
                </select>
                {kategoriRefOptions.length === 0 && (
                  <p className="text-xs text-amber-600 mt-1">
                    Belum ada kategori. Minta vendor menambahkan di menu Tabel Referensi &gt; Kategori Informasi.
                  </p>
                )}
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">Judul</label>
                <input
                  className="w-full px-3 py-2 rounded-lg border border-[var(--rw-border)] dark:border-gray-700 bg-white dark:bg-gray-800 text-sm"
                  value={form.judul}
                  onChange={e => setForm(f => ({ ...f, judul: e.target.value }))}
                />
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">Isi / Deskripsi</label>
                <textarea
                  rows={4}
                  className="w-full px-3 py-2 rounded-lg border border-[var(--rw-border)] dark:border-gray-700 bg-white dark:bg-gray-800 text-sm"
                  value={form.konten}
                  onChange={e => setForm(f => ({ ...f, konten: e.target.value }))}
                />
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">Gambar Header</label>
                <input type="file" accept="image/*" onChange={handleGambarHeaderChange} className="text-sm" />
                {gambarHeaderPreview && (
                  <img src={gambarHeaderPreview} alt="" className="mt-2 w-32 h-20 object-cover rounded" />
                )}
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">Gambar Galeri (bisa lebih dari satu)</label>
                <input
                  type="file" accept="image/*" multiple
                  onChange={e => setGaleriFiles(Array.from(e.target.files || []))}
                  className="text-sm"
                />
                {editItem?.galeri?.length > 0 && (
                  <p className="text-xs text-gray-500 mt-1">
                    {editItem.galeri.length} gambar galeri tersimpan. Upload baru akan ditambahkan.
                  </p>
                )}
              </div>
              <div>
                <label className="block text-sm font-medium mb-1 flex items-center gap-1">
                  <Video className="w-4 h-4" /> Link Video (YouTube / lainnya)
                </label>
                <input
                  className="w-full px-3 py-2 rounded-lg border border-[var(--rw-border)] dark:border-gray-700 bg-white dark:bg-gray-800 text-sm"
                  placeholder="https://youtube.com/watch?v=..."
                  value={form.video_url}
                  onChange={e => setForm(f => ({ ...f, video_url: e.target.value }))}
                />
              </div>
              <div className="flex items-center gap-6">
                <label className="flex items-center gap-2 text-sm font-medium">
                  <input type="checkbox" checked={form.pin} onChange={e => setForm(f => ({ ...f, pin: e.target.checked }))} />
                  Pin Informasi
                </label>
                <label className="flex items-center gap-2 text-sm font-medium">
                  <input type="checkbox" checked={form.aktif} onChange={e => setForm(f => ({ ...f, aktif: e.target.checked }))} />
                  Aktif (publish)
                </label>
              </div>
            </div>
            <div className="flex justify-end gap-2 p-5 border-t border-[var(--rw-border)] dark:border-gray-700">
              <button onClick={() => setShowForm(false)} className="px-4 py-2 rounded-lg text-sm font-medium text-gray-600 dark:text-gray-300">
                Batal
              </button>
              <button
                onClick={handleSubmit}
                disabled={saving}
                className="px-4 py-2 rounded-lg text-sm font-medium bg-[var(--rw-primary)] hover:bg-[#e15c47] text-white disabled:opacity-60"
              >
                {saving ? 'Menyimpan...' : 'Simpan'}
              </button>
            </div>
          </div>
        </div>,
        document.body
      )}

      {/* Delete Confirm */}
      <AlertDialog open={!!deleteId} onOpenChange={(open) => !open && setDeleteId(null)}>
        <AlertDialogContent className="bg-[var(--rw-bg-card)] dark:bg-gray-900 dark:text-gray-100">
          <AlertDialogHeader>
            <AlertDialogTitle>Hapus Informasi ini?</AlertDialogTitle>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel className="dark:bg-gray-800 dark:text-gray-200">Batal</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete} className="bg-red-600 hover:bg-red-700">
              Hapus
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* Image Lightbox — klik thumbnail Gambar Header untuk lihat penuh */}
      {lightboxImg && ReactDOM.createPortal(
        <div
          className="fixed inset-0 bg-black/80 flex items-center justify-center z-[60] p-4"
          onClick={() => setLightboxImg(null)}
        >
          <button
            onClick={() => setLightboxImg(null)}
            className="absolute top-4 right-4 text-white/80 hover:text-white"
          >
            <X className="w-7 h-7" />
          </button>
          <img
            src={lightboxImg}
            alt=""
            onClick={(e) => e.stopPropagation()}
            className="max-w-full max-h-[90vh] rounded-lg object-contain"
          />
        </div>,
        document.body
      )}
    </div>
  );
}
