import { useEffect, useState } from "react";
import axios from "axios";

import { API_BASE_URL, API_ENDPOINTS } from "@/config/api";
import ImportExcelModal from "@/components/ImportExcelModal";
import { useLocation } from "react-router-dom";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import RumahTable from "./RumahTable";
import RumahFormModal from "./RumahFormModal";
import {
  AlertDialog,
  AlertDialogContent,
  AlertDialogHeader,
  AlertDialogFooter,
  AlertDialogTitle,
  AlertDialogCancel,
  AlertDialogAction
} from "@/components/ui/alert-dialog";
import { useAuth } from "@/contexts/AuthContext";
import { toast } from "@/components/ui/sonner";
import { useRolePermissions } from "@/hooks/useRolePermissions";

export default function RumahPage() {
  const location = useLocation();
  const [rumahList, setRumahList] = useState([]);
  const [search, setSearch] = useState("");
  const { token, logout, user } = useAuth();
  const { canCreate, canDelete } = useRolePermissions(user?.role, token);

  // FORM
  const [openForm, setOpenForm] = useState(false);
  const [selectedRumah, setSelectedRumah] = useState(null);

  // MULTI SELECT
  const [selectedRows, setSelectedRows] = useState([]);

  // FILTER
  const [showFilter, setShowFilter] = useState(false);
  const [filterJenisPemilik, setFilterJenisPemilik] = useState("all");
  const [filterStatusPenghuni, setFilterStatusPenghuni] = useState("all");
  const [filterAktif, setFilterAktif] = useState("all");

  // Opsi dropdown Jenis Bangunan & Status Hunian — dari Tabel Referensi
  // vendor, bisa dikustomisasi tanpa ubah kode. Fallback ke default kalau
  // API belum sempat merespons / gagal.
  const [jenisKepemilikanOptions, setJenisKepemilikanOptions] = useState([
    { nilai: 'Milik Sendiri', label: 'Milik Sendiri' },
    { nilai: 'Sewa / Kontrak', label: 'Sewa / Kontrak' },
    { nilai: 'Aset Publik', label: 'Aset Publik' },
    { nilai: 'Lainnya', label: 'Lainnya' },
  ]);
  const [statusHunianOptions, setStatusHunianOptions] = useState([
    { nilai: 'Ditempati Pemilik', label: 'Ditempati Pemilik' },
    { nilai: 'Ditempati Keluarga', label: 'Ditempati Keluarga' },
    { nilai: 'Disewakan / Kontrak', label: 'Disewakan / Kontrak' },
    { nilai: 'Tempat Usaha', label: 'Tempat Usaha' },
    { nilai: 'Kosong', label: 'Kosong' },
  ]);

  useEffect(() => {
    axios.get(`${API_BASE_URL}/api/referensi/jenis-kepemilikan-rumah`)
      .then(res => { if (res.data?.length) setJenisKepemilikanOptions(res.data); })
      .catch(() => {});
    axios.get(`${API_BASE_URL}/api/referensi/status-hunian-rumah`)
      .then(res => { if (res.data?.length) setStatusHunianOptions(res.data); })
      .catch(() => {});
  }, []);

  // PAGINATION
  const [page, setPage] = useState(1);
  const [perPage, setPerPage] = useState(5);

  // BULK DELETE DIALOG
  const [openBulkDelete, setOpenBulkDelete] = useState(false);

  // IMPORT EXCEL
  const [showImportModal, setShowImportModal] = useState(false);

  // Load rumah list
  const loadRumah = async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/rumah`, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (res.status === 401) {
        logout();
        return;
      }

      const data = await res.json();
      setRumahList(data);
    } catch (err) {
      console.error("Gagal load rumah", err);
      toast.error("Gagal memuat data rumah");
    }
  };

  useEffect(() => {
    loadRumah();
  }, []);

  // Auto-search dari state (misal dari IPL page)
  useEffect(() => {
    if (location.state?.searchBlok) {
      setSearch(location.state.searchBlok);
    }
  }, [location.state?.searchBlok]);

  // FILTER LOGIC
  const filtered = rumahList
    .filter((r) =>
      r.blok_no.toLowerCase().includes(search.toLowerCase()) ||
      (r.nama_jalan && r.nama_jalan.toLowerCase().includes(search.toLowerCase())) ||
      (r.pemilik_sah && r.pemilik_sah.toLowerCase().includes(search.toLowerCase()))
    )
    .filter((r) => {
      if (filterJenisPemilik === "all") return true;
      return r.jenis_pemilik === filterJenisPemilik;
    })
    .filter((r) => {
      if (filterStatusPenghuni === "all") return true;
      return r.status_penghuni === filterStatusPenghuni;
    })
    .filter((r) => {
      if (filterAktif === "all") return true;
      return filterAktif === "aktif" ? r.aktif : !r.aktif;
    });

  // PAGINATION
  const totalPages = Math.ceil(filtered.length / perPage);
  const paginatedData = filtered.slice((page - 1) * perPage, page * perPage);

  // Bangun query string dari filter yang sedang aktif — dipakai bareng oleh export Excel & PDF
  // supaya hasil export selalu sesuai dengan data yang sedang difilter di layar.
  const buildFilterParams = () => {
    const params = new URLSearchParams();
    if (search) params.set('search', search);
    if (filterJenisPemilik !== 'all') params.set('jenis_pemilik', filterJenisPemilik);
    if (filterStatusPenghuni !== 'all') params.set('status_penghuni', filterStatusPenghuni);
    if (filterAktif !== 'all') params.set('aktif', filterAktif);
    return params.toString();
  };

  // EXPORT EXCEL
  const [exporting, setExporting] = useState(false);
  const exportExcel = async () => {
    setExporting(true);
    try {
      const qs = buildFilterParams();
      const res = await fetch(`${API_ENDPOINTS.EXPORT_EXCEL_RUMAH}${qs ? `?${qs}` : ''}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (res.status === 401) { logout(); return; }
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const blob = await res.blob();
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `daftar-rumah-${new Date().toISOString().slice(0, 10)}.xlsx`;
      a.click();
      URL.revokeObjectURL(url);
    } catch (err) {
      console.error('Gagal export rumah', err);
      toast.error('Gagal mengekspor data rumah');
    } finally {
      setExporting(false);
    }
  };

  // PRINT / EXPORT PDF (kolom & filter sama dengan Export Excel)
  const [printingPdf, setPrintingPdf] = useState(false);
  const exportPdf = async () => {
    setPrintingPdf(true);
    try {
      const qs = buildFilterParams();
      const res = await fetch(`${API_ENDPOINTS.EXPORT_EXCEL_RUMAH}/pdf${qs ? `?${qs}` : ''}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (res.status === 401) { logout(); return; }
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const blob = await res.blob();
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `daftar-rumah-${new Date().toISOString().slice(0, 10)}.pdf`;
      a.click();
      URL.revokeObjectURL(url);
    } catch (err) {
      console.error('Gagal export PDF rumah', err);
      toast.error('Gagal membuat PDF data rumah');
    } finally {
      setPrintingPdf(false);
    }
  };

  // BULK DELETE
  const doBulkDelete = async () => {
    for (const id of selectedRows) {
      await fetch(`${API_BASE_URL}/api/rumah/${id}`, {
        method: "DELETE",
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });
    }
    toast.success(`${selectedRows.length} rumah berhasil dihapus`);
    loadRumah();
    setSelectedRows([]);
    setOpenBulkDelete(false);
  };

  return (
    <div className="p-6 space-y-4">
      {/* HEADER */}
      <div className="flex flex-col sm:flex-row sm:justify-between sm:items-center gap-3">
        <div>
          <h1 className="text-3xl font-bold dark:text-gray-100">
            {user?.role === "warga" ? "Rumah Saya" : "Daftar Rumah"}
          </h1>
          <p className="text-sm text-gray-600 dark:text-gray-400">
            {user?.role === "warga" ? "Data rumah Anda" : "Kelola data rumah/properti di kompleks"}
          </p>
        </div>
        <div className="flex flex-wrap gap-2 sm:justify-end">
          {user?.role !== "warga" && (
          <Button
            variant="outline"
            onClick={exportExcel}
            disabled={exporting}
            className="flex-1 basis-[calc(50%-4px)] sm:basis-auto sm:flex-none border-blue-600 text-blue-700 hover:bg-blue-50 dark:border-blue-500 dark:text-blue-400 px-2 sm:px-4 text-xs sm:text-sm"
          >
            <span className="sm:hidden">⬇ Excel</span>
            <span className="hidden sm:inline">{exporting ? "Mengekspor..." : "⬇ Export Excel"}</span>
          </Button>
          )}
          {user?.role !== "warga" && (
          <Button
            variant="outline"
            onClick={exportPdf}
            disabled={printingPdf}
            className="flex-1 basis-[calc(50%-4px)] sm:basis-auto sm:flex-none border-orange-600 text-orange-700 hover:bg-orange-50 dark:border-orange-500 dark:text-orange-400 px-2 sm:px-4 text-xs sm:text-sm"
          >
            <span className="sm:hidden">🖨 PDF</span>
            <span className="hidden sm:inline">{printingPdf ? "Membuat PDF..." : "🖨 Print PDF"}</span>
          </Button>
          )}
          {canCreate('rumah') && (
            <>
              <Button
                variant="outline"
                onClick={() => setShowImportModal(true)}
                className="flex-1 basis-[calc(50%-4px)] sm:basis-auto sm:flex-none border-green-600 text-green-700 hover:bg-green-50 dark:border-green-500 dark:text-green-400 px-2 sm:px-4 text-xs sm:text-sm"
              >
                <span className="sm:hidden">⬆ Import</span>
                <span className="hidden sm:inline">⬆ Import Excel</span>
              </Button>
              <Button
                onClick={() => {
                  setSelectedRumah(null);
                  setOpenForm(true);
                }}
                className="flex-1 basis-[calc(50%-4px)] sm:basis-auto sm:flex-none bg-[var(--rw-primary)] hover:bg-[var(--rw-primary-hover)] text-white px-2 sm:px-4 text-xs sm:text-sm"
              >
                <span className="sm:hidden">+ Tambah</span>
                <span className="hidden sm:inline">+ Tambah Rumah</span>
              </Button>
            </>
          )}
        </div>
      </div>

      {/* SEARCH & FILTER */}
      <div className="flex gap-3">
        <Input
          placeholder="Cari blok, jalan, atau pemilik..."
          value={search}
          onChange={(e) => {
            setSearch(e.target.value);
            setPage(1);
          }}
          className="flex-1 dark:bg-gray-800 dark:text-gray-100 dark:border-gray-700"
        />
        <Button
          variant="outline"
          onClick={() => setShowFilter(!showFilter)}
          className="dark:border-gray-700 dark:text-gray-200"
        >
          Filter
        </Button>
      </div>

      {/* FILTER PANEL */}
      {showFilter && (
        <div className="bg-[var(--rw-bg-card)] dark:bg-gray-900 p-6 rounded-lg border dark:border-gray-700 space-y-4">
          <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
            {/* JENIS KEPEMILIKAN */}
            <div>
              <label className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase">Jenis Bangunan</label>
              <select
                value={filterJenisPemilik}
                onChange={(e) => {
                  setFilterJenisPemilik(e.target.value);
                  setPage(1);
                }}
                className="w-full p-2 mt-2 border rounded-md dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100 bg-[var(--rw-bg-card-alt)]"
              >
                <option value="all">Semua</option>
                {jenisKepemilikanOptions.map((opt) => (
                  <option key={opt.nilai} value={opt.nilai}>{opt.label}</option>
                ))}
              </select>
            </div>

            {/* STATUS HUNIAN */}
            <div>
              <label className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase">Status Hunian</label>
              <select
                value={filterStatusPenghuni}
                onChange={(e) => {
                  setFilterStatusPenghuni(e.target.value);
                  setPage(1);
                }}
                className="w-full p-2 mt-2 border rounded-md dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100 bg-[var(--rw-bg-card-alt)]"
              >
                <option value="all">Semua</option>
                {statusHunianOptions.map((opt) => (
                  <option key={opt.nilai} value={opt.nilai}>{opt.label}</option>
                ))}
              </select>
            </div>

            {/* AKTIF */}
            <div>
              <label className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase">Aktif?</label>
              <select
                value={filterAktif}
                onChange={(e) => {
                  setFilterAktif(e.target.value);
                  setPage(1);
                }}
                className="w-full p-2 mt-2 border rounded-md dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100 bg-[var(--rw-bg-card-alt)]"
              >
                <option value="all">Semua</option>
                <option value="aktif">Aktif</option>
                <option value="nonaktif">Tidak Aktif</option>
              </select>
            </div>

            {/* PER HALAMAN */}
            <div>
              <label className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase">Per Halaman</label>
              <select
                value={perPage}
                onChange={(e) => {
                  setPerPage(Number(e.target.value));
                  setPage(1);
                }}
                className="w-full p-2 mt-2 border rounded-md dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100 bg-[var(--rw-bg-card-alt)]"
              >
                <option value="5">5</option>
                <option value="10">10</option>
                <option value="25">25</option>
              </select>
            </div>
          </div>
        </div>
      )}

      {/* ACTIONS */}
      {selectedRows.length > 0 && canDelete('rumah') && (
        <div className="flex gap-3 bg-blue-50 dark:bg-blue-900/20 p-4 rounded-lg border border-blue-200 dark:border-blue-800">
          <span className="text-sm dark:text-gray-300">
            {selectedRows.length} item dipilih
          </span>
          <Button
            size="sm"
            variant="destructive"
            onClick={() => setOpenBulkDelete(true)}
          >
            Hapus
          </Button>
          {user?.role !== "warga" && (
          <Button
            size="sm"
            onClick={exportExcel}
            disabled={exporting}
            className="bg-green-500 hover:bg-green-600 text-white"
          >
            {exporting ? "Mengekspor..." : "Export Excel"}
          </Button>
          )}
        </div>
      )}

      {/* TABLE */}
      <div className="bg-[var(--rw-bg-card)] dark:bg-gray-900 rounded-lg border dark:border-gray-700">
        <RumahTable
          data={paginatedData}
          onEdit={(r) => {
            setSelectedRumah(r);
            setOpenForm(true);
          }}
          onDelete={loadRumah}
          selectedRows={selectedRows}
          setSelectedRows={setSelectedRows}
        />
      </div>

      {/* PAGINATION INFO */}
      <div className="flex justify-between items-center text-sm text-gray-600 dark:text-gray-400 px-2">
        <span>
          {filtered.length === 0 ? "Tidak ada data" : `${(page - 1) * perPage + 1}-${Math.min(page * perPage, filtered.length)} dari ${filtered.length}`}
        </span>
        <div className="flex gap-2">
          <Button
            size="sm"
            variant="outline"
            onClick={() => setPage(Math.max(1, page - 1))}
            disabled={page === 1}
            className="dark:border-gray-700 dark:text-gray-200"
          >
            Sebelumnya
          </Button>
          <Button
            size="sm"
            variant="outline"
            onClick={() => setPage(Math.min(totalPages, page + 1))}
            disabled={page === totalPages}
            className="dark:border-gray-700 dark:text-gray-200"
          >
            Selanjutnya
          </Button>
        </div>
      </div>

      {/* FORM MODAL */}
      <RumahFormModal
        open={openForm}
        onOpenChange={setOpenForm}
        rumah={selectedRumah}
        onSaved={() => {
          loadRumah();
          setSelectedRumah(null);
        }}
      />

      {/* BULK DELETE DIALOG */}
      <AlertDialog open={openBulkDelete} onOpenChange={setOpenBulkDelete}>
        <AlertDialogContent className="bg-[var(--rw-bg-card)] dark:bg-gray-900 dark:text-gray-100">
          <AlertDialogHeader>
            <AlertDialogTitle>Hapus {selectedRows.length} Rumah?</AlertDialogTitle>
          </AlertDialogHeader>
          <p className="text-sm text-gray-600 dark:text-gray-400">
            Tindakan ini tidak dapat dibatalkan.
          </p>
          <AlertDialogFooter>
            <AlertDialogCancel className="dark:bg-gray-800 dark:text-gray-200">
              Batal
            </AlertDialogCancel>
            <AlertDialogAction
              onClick={doBulkDelete}
              className="bg-red-600 hover:bg-red-700"
            >
              Hapus Semua
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* IMPORT EXCEL MODAL */}
      <ImportExcelModal
        show={showImportModal}
        onClose={() => setShowImportModal(false)}
        onImported={loadRumah}
        title="Import Data Rumah dari Excel"
        templateUrl={API_ENDPOINTS.IMPORT_EXCEL_TEMPLATE_RUMAH}
        importUrl={API_ENDPOINTS.IMPORT_EXCEL_RUMAH}
        templateName="template_rumah.xlsx"
        columns={[
          'Blok/No Rumah *', 'Nama Jalan', 'Pemilik Sah', 'Jenis Bangunan',
          'Status Hunian', 'Aktif', 'Catatan',
        ]}
        importModes={[
          {
            value: 'upsert',
            label: 'Insert / Update',
            description: 'Data baru otomatis ditambahkan. Kalau Blok/No Rumah sudah ada, datanya akan diperbarui (bukan dobel).',
          },
          {
            value: 'replace',
            label: 'Sinkronkan (Hapus yang Tidak Ada di File)',
            description: 'Rumah yang blok-nya sudah ada di file akan diperbarui di tempat (ID & tautannya tetap sama — Kartu Keluarga, tagihan IPL, dsb tidak putus). Rumah yang blok-nya TIDAK ADA di file akan dihapus, kecuali masih punya riwayat tagihan/pembayaran/tarif IPL (akan dilewati & dilaporkan demi keamanan data).',
          },
        ]}
      />
    </div>
  );
}
