import { useState } from "react";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Button } from "@/components/ui/button";
import { API_BASE_URL } from "@/config/api";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { CheckCircle2, XCircle, Lock, Building2, ChevronRight } from "lucide-react";
import { toast } from "@/components/ui/sonner";
import { useAuth } from "@/contexts/AuthContext";
import { useRolePermissions } from "@/hooks/useRolePermissions";

export default function PengurusTable({
  data,
  profilKetua,
  selectedRows,
  setSelectedRows,
  onEdit,
  onDelete,
  onDetailKetua,
}) {
  const { token, user } = useAuth();
  const { canRead, canUpdate: canEdit, canDelete } = useRolePermissions(user?.role, token);
  const [sortField, setSortField] = useState("");
  const [sortDir, setSortDir] = useState("asc");
  const [showDeleteAlert, setShowDeleteAlert] = useState(false);
  const [selectedForDelete, setSelectedForDelete] = useState(null);

  const toggleSort = (field) => {
    const newDir =
      sortField === field && sortDir === "asc" ? "desc" : "asc";
    setSortField(field);
    setSortDir(newDir);
  };

  const sortedData = [...data].sort((a, b) => {
    if (!sortField) return 0;
    const aVal = a[sortField] ?? "";
    const bVal = b[sortField] ?? "";
    return sortDir === "asc"
      ? aVal.toString().localeCompare(bVal.toString())
      : bVal.toString().localeCompare(aVal.toString());
  });

  // Handle individual checkbox
  const handleSelectRow = (id) => {
    setSelectedRows((prev) =>
      prev.includes(id) ? prev.filter((row) => row !== id) : [...prev, id]
    );
  };

  // Handle select all
  const handleSelectAll = () => {
    if (selectedRows.length === data.length) {
      setSelectedRows([]);
    } else {
      setSelectedRows(data.map((p) => p.id));
    }
  };



  // Delete single pengurus
  const handleDelete = async () => {
    try {
      const res = await fetch(
        `${API_BASE_URL}/api/pengurus/${selectedForDelete}`,
        {
          method: "DELETE",
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      if (res.ok) {
        toast.success("Pengurus berhasil dihapus!");
        onDelete();
        setShowDeleteAlert(false);
      } else {
        toast.error("Gagal menghapus pengurus");
      }
    } catch (err) {
      toast.error("Tidak dapat terhubung ke server");
      console.error(err);
    }
  };

  const formatDate = (val) => {
    if (!val) return "-";
    return new Date(val).toLocaleDateString("id-ID");
  };

  const formatPeriode = (mulai, sampai) => {
    if (!mulai && !sampai) return "-";
    const fmt = (v) => {
      if (!v) return "?";
      const d = new Date(v);
      return d.toLocaleDateString("id-ID", { day: "2-digit", month: "2-digit", year: "numeric" });
    };
    if (mulai && sampai) return `Mulai ${fmt(mulai)} s/d ${fmt(sampai)}`;
    if (mulai) return `Mulai ${fmt(mulai)}`;
    return `s/d ${fmt(sampai)}`;
  };

  return (
    <>
      <div className="border rounded-lg overflow-hidden dark:border-gray-700">
        <Table className="dark:bg-gray-800">
          <TableHeader>
            <TableRow className="dark:border-gray-700">
              <TableHead className="w-10 dark:text-gray-400">
                <input
                  type="checkbox"
                  checked={
                    data.length > 0 && selectedRows.length === data.length
                  }
                  onChange={handleSelectAll}
                />
              </TableHead>
              <TableHead
                onClick={() => toggleSort("nama_lengkap")}
                className="cursor-pointer dark:text-gray-400 hover:text-cyan-500"
              >
                Nama{" "}
                {sortField === "nama_lengkap" &&
                  (sortDir === "asc" ? "▲" : "▼")}
              </TableHead>
              <TableHead className="dark:text-gray-400">
                Nama Jabatan
              </TableHead>
              <TableHead className="dark:text-gray-400">
                Periode
              </TableHead>
              <TableHead className="text-center dark:text-gray-400">
                Status Aktif
              </TableHead>
              {canRead('pengurus') && canEdit('pengurus') && (<TableHead className="text-right dark:text-gray-400">
                Aksi
              </TableHead>)}
            </TableRow>
          </TableHeader>
          <TableBody>
            {/* Row Ketua RT — otomatis dari Profil RT; klik untuk buka detail (Profil RT) */}
            {profilKetua && (
              <TableRow
                onClick={() => onDetailKetua?.()}
                title="Klik untuk melihat detail Profil RT"
                className="bg-amber-50 dark:bg-amber-900/10 border-b border-amber-200 dark:border-amber-800 cursor-pointer hover:bg-amber-100/70 dark:hover:bg-amber-900/20">
                <TableCell className="w-10">
                  <Lock className="h-4 w-4 text-amber-500 mx-auto" />
                </TableCell>
                <TableCell className="font-semibold text-gray-900 dark:text-gray-100">
                  {profilKetua.nama_lengkap}
                  <span className="ml-2 text-[10px] font-normal bg-amber-100 dark:bg-amber-900/40 text-amber-700 dark:text-amber-400 px-1.5 py-0.5 rounded">
                    dari Profil RT
                  </span>
                </TableCell>
                <TableCell className="text-gray-700 dark:text-gray-300">
                  {profilKetua.nama_jabatan}
                </TableCell>
                <TableCell className="text-gray-600 dark:text-gray-400 text-sm">
                  {formatPeriode(profilKetua.mulai_jabatan, profilKetua.sampai_jabatan)}
                </TableCell>
                <TableCell className="text-center">
                  <CheckCircle2 className="w-5 h-5 text-green-500 mx-auto" />
                </TableCell>
                <TableCell className="text-right">
                  <span className="text-xs font-semibold text-amber-700 dark:text-amber-400 flex items-center justify-end gap-1">
                    <Building2 className="h-3.5 w-3.5" /> Detail Profil RT <ChevronRight className="h-3.5 w-3.5" />
                  </span>
                </TableCell>
              </TableRow>
            )}

            {/* Rows lain — editable */}
            {sortedData.length === 0 && !profilKetua ? (
              <TableRow>
                <TableCell colSpan={7} className="text-center text-gray-500 py-8">
                  Tidak ada data
                </TableCell>
              </TableRow>
            ) : (
              sortedData.map((pengurus) => (
                <TableRow key={pengurus.id} className="dark:border-gray-700 dark:hover:bg-gray-700">
                  <TableCell className="w-10">
                    <input
                      type="checkbox"
                      checked={selectedRows.includes(pengurus.id)}
                      onChange={() => handleSelectRow(pengurus.id)}
                    />
                  </TableCell>
                  <TableCell className="font-medium dark:text-gray-100">
                    {pengurus.nama_lengkap}
                  </TableCell>
                  <TableCell className="dark:text-gray-300">
                    {pengurus.nama_jabatan}
                  </TableCell>
                  <TableCell className="dark:text-gray-300 text-sm">
                    {formatPeriode(pengurus.mulai_jabatan, pengurus.sampai_jabatan)}
                  </TableCell>
                  <TableCell className="text-center">
                    {pengurus.aktif ? (
                      <CheckCircle2 className="w-5 h-5 text-green-500 mx-auto" />
                    ) : (
                      <XCircle className="w-5 h-5 text-red-500 mx-auto" />
                    )}
                  </TableCell>
                  <TableCell className="text-right">
                    {canRead('pengurus') && canEdit('pengurus') && (
                      <Button
                        onClick={() => onEdit(pengurus)}
                        className="bg-[var(--rw-primary)] hover:bg-[var(--rw-primary-hover)] text-white"
                        size="sm"
                      >
                        Edit
                      </Button>
                    )}
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </div>

      {/* DELETE ALERT */}
      <AlertDialog open={showDeleteAlert} onOpenChange={setShowDeleteAlert}>
        <AlertDialogContent className="bg-[var(--rw-bg-card)] dark:bg-gray-900">
          <AlertDialogTitle className="dark:text-gray-100">
            Hapus Pengurus?
          </AlertDialogTitle>
          <AlertDialogDescription className="dark:text-gray-400">
            Data pengurus akan dihapus secara permanen. Aksi ini tidak dapat dibatalkan.
          </AlertDialogDescription>
          <div className="flex gap-3 justify-end">
            <AlertDialogCancel className="dark:border-gray-700 dark:hover:bg-gray-800">
              Batal
            </AlertDialogCancel>
            <AlertDialogAction
              onClick={handleDelete}
              className="bg-red-600 hover:bg-red-700"
            >
              Hapus
            </AlertDialogAction>
          </div>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}
