import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { API_BASE_URL } from "@/config/api";
import { countryCodeToFlag } from "@/utils/countryFlag";

// Warna badge per status_detail (Aktif/Kontrak/Kos/Pendatang Warga Sementara/Pindah/Meninggal/Tidak Aktif)
const STATUS_DETAIL_COLORS = {
  "Aktif": "bg-green-100 text-green-700 dark:bg-green-900 dark:text-green-200",
  "Kontrak": "bg-blue-100 text-blue-700 dark:bg-blue-900 dark:text-blue-200",
  "Kos": "bg-cyan-100 text-cyan-700 dark:bg-cyan-900 dark:text-cyan-200",
  "Pendatang Warga Sementara": "bg-yellow-100 text-yellow-700 dark:bg-yellow-900 dark:text-yellow-200",
  "Pindah": "bg-orange-100 text-orange-700 dark:bg-orange-900 dark:text-orange-200",
  "Meninggal": "bg-gray-200 text-gray-700 dark:bg-gray-700 dark:text-gray-300",
  "Tidak Aktif": "bg-red-100 text-red-700 dark:bg-red-900 dark:text-red-200",
};
const getStatusDetailColor = (statusDetail) =>
  STATUS_DETAIL_COLORS[statusDetail] || (statusDetail ? "bg-gray-100 text-gray-700" : "bg-red-100 text-red-700 dark:bg-red-900 dark:text-red-200");
const getStatusDetailLabel = (w) => w.status_detail || (w.status === "active" ? "Aktif" : "Tidak Aktif");
import { Button } from "@/components/ui/button";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow
} from "@/components/ui/table";
import {
  AlertDialog,
  AlertDialogHeader,
  AlertDialogFooter,
  AlertDialogTitle,
  AlertDialogContent,
  AlertDialogCancel,
  AlertDialogAction
} from "@/components/ui/alert-dialog";
import { CheckCircle2, XCircle, ChevronDown, ChevronRight } from "lucide-react";
import { toast } from "@/components/ui/sonner";
import { useAuth } from "@/contexts/AuthContext";
import { useRolePermissions } from "@/hooks/useRolePermissions";

const BANTUAN_COLORS = {
  KIS:      'bg-blue-100 text-blue-700 dark:bg-blue-900 dark:text-blue-300',
  PIP:      'bg-purple-100 text-purple-700 dark:bg-purple-900 dark:text-purple-300',
  BLT:      'bg-green-100 text-green-700 dark:bg-green-900 dark:text-green-300',
  BNPT:     'bg-orange-100 text-orange-700 dark:bg-orange-900 dark:text-orange-300',
  RUTILAHU: 'bg-red-100 text-red-700 dark:bg-red-900 dark:text-red-300',
};

export default function WargaTable({
  data,
  onEdit,
  onDelete,
  selectedRows,
  setSelectedRows
}) {
  const [sortField, setSortField] = useState("");
  const [sortDir, setSortDir] = useState("asc");
  const navigate = useNavigate();
  const { token, user } = useAuth(); // 🔐 JWT
  const { canRead, canUpdate: canEdit, canDelete } = useRolePermissions(user?.role, token);
  const isWarga = user?.role === "warga";
  const [deleteConfirm, setDeleteConfirm] = useState(null);
  const [expandedRows, setExpandedRows] = useState([]);

  const toggleSort = (field) => {
    const newDir =
      sortField === field && sortDir === "asc" ? "desc" : "asc";
    setSortField(field);
    setSortDir(newDir);
  };

  const sortedData = [...data].sort((a, b) => {
    if (!sortField) return 0;
    const aVal = a[sortField] ?? "";
    const bVal = b[sortField] ?? "";
    return sortDir === "asc"
      ? aVal.toString().localeCompare(bVal.toString())
      : bVal.toString().localeCompare(aVal.toString());
  });

  const toggleRow = (id) => {
    setSelectedRows(
      selectedRows.includes(id)
        ? selectedRows.filter((r) => r !== id)
        : [...selectedRows, id]
    );
  };

  const toggleAll = () => {
    if (selectedRows.length === data.length) setSelectedRows([]);
    else setSelectedRows(data.map((w) => w.id));
  };

  const remove = async (id) => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/warga/${id}`, {
        method: "DELETE",
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (!res.ok) throw new Error();

      toast.success("Warga dihapus");
      onDelete();
    } catch {
      toast.error("Gagal menghapus warga");
    }
    setDeleteConfirm(null);
  };

  const formatDate = (val) => {
    if (!val) return "-";
    return new Date(val).toLocaleDateString("id-ID");
  };

  const toggleExpanded = (id) => {
    setExpandedRows(
      expandedRows.includes(id)
        ? expandedRows.filter((r) => r !== id)
        : [...expandedRows, id]
    );
  };

  return (
    <>
      <Table className="border rounded-lg bg-[var(--rw-bg-card)] dark:bg-gray-900 shadow-sm">
        <TableHeader>
          <TableRow className="dark:border-gray-700">
            {/* EXPAND ICON */}
            <TableHead className="w-10"></TableHead>

            {/* CHECKBOX */}
            <TableHead className="w-10">
              <input
                type="checkbox"
                checked={
                  data.length > 0 && selectedRows.length === data.length
                }
                onChange={toggleAll}
              />
            </TableHead>

            <TableHead
              onClick={() => toggleSort("nama_lengkap")}
              className="cursor-pointer dark:text-gray-300"
            >
              Nama {sortField === "nama_lengkap" && (sortDir === "asc" ? "▲" : "▼")}
            </TableHead>

            <TableHead className="dark:text-gray-300">No WhatsApp</TableHead>
            <TableHead className="dark:text-gray-300">Jenis Kelamin</TableHead>
            <TableHead className="dark:text-gray-300">Posisi Keluarga</TableHead>
            <TableHead className="dark:text-gray-300">Blok / No Rumah</TableHead>
            {!isWarga && (<TableHead className="dark:text-gray-300">Status</TableHead>)}
            {!isWarga && (<TableHead className="dark:text-gray-300">Strata Ekonomi</TableHead>)}
            <TableHead className="dark:text-gray-300">Bantuan</TableHead>
            <TableHead className="text-center dark:text-gray-300">Punya User?</TableHead>
            {canRead('warga') && canEdit('warga') && (<TableHead className="text-right dark:text-gray-300">Edit</TableHead>)}
          </TableRow>
        </TableHeader>

        <TableBody>
          {sortedData.map((w) => (
            <>
              <TableRow key={w.id} className="dark:border-gray-700 dark:hover:bg-gray-800">
                {/* EXPAND ICON */}
                <TableCell 
                  className="w-10 cursor-pointer"
                  onClick={() => toggleExpanded(w.id)}
                >
                  {expandedRows.includes(w.id) ? (
                    <ChevronDown className="w-5 h-5 text-gray-600 dark:text-gray-400" />
                  ) : (
                    <ChevronRight className="w-5 h-5 text-gray-600 dark:text-gray-400" />
                  )}
                </TableCell>

                {/* CHECKBOX */}
                <TableCell className="w-10">
                  <input
                    type="checkbox"
                    checked={selectedRows.includes(w.id)}
                    onChange={() => toggleRow(w.id)}
                  />
                </TableCell>

                <TableCell className="dark:text-gray-200">{w.nama_lengkap}</TableCell>
                <TableCell className="dark:text-gray-200">{w.whatsapp || "-"}</TableCell>
                <TableCell className="dark:text-gray-200">{w.jenis_kelamin || "-"}</TableCell>
                <TableCell className="dark:text-gray-200">{w.posisi_keluarga || "-"}</TableCell>
                <TableCell className="dark:text-gray-200">
                  {w.block_house ? (
                    <button
                      onClick={() => navigate(`/warga/${w.id}`)}
                      className="font-medium text-[var(--rw-primary)] hover:text-[var(--rw-primary-hover)] hover:underline transition-colors"
                    >
                      {w.block_house}
                    </button>
                  ) : "-"}
                </TableCell>

                {!isWarga && (
                <TableCell className="dark:text-gray-200">
                  <span
                    className={`px-2 py-1 rounded-full text-xs font-semibold ${getStatusDetailColor(w.status_detail)}`}
                  >
                    {getStatusDetailLabel(w)}
                  </span>
                </TableCell>
                )}

                {/* Strata Ekonomi */}
                {!isWarga && (
                <TableCell className="dark:text-gray-200">
                  {w.strata_ekonomi ? (
                    <span className={`px-2 py-1 rounded-full text-xs font-semibold ${
                      w.strata_ekonomi === 'Mampu'
                        ? 'bg-green-100 text-green-700 dark:bg-green-900 dark:text-green-300'
                        : 'bg-orange-100 text-orange-700 dark:bg-orange-900 dark:text-orange-300'
                    }`}>
                      {w.strata_ekonomi}
                    </span>
                  ) : <span className="text-gray-400 text-xs">-</span>}
                </TableCell>
                )}

                {/* Bantuan */}
                <TableCell className="dark:text-gray-200">
                  <div className="flex flex-wrap gap-1">
                    {Array.isArray(w.bantuan_diterima) && w.bantuan_diterima.length > 0
                      ? w.bantuan_diterima.map(b => (
                          <span key={b} className={`px-1.5 py-0.5 rounded text-xs font-semibold ${BANTUAN_COLORS[b] || 'bg-gray-100 text-gray-700'}`}>
                            {b}
                          </span>
                        ))
                      : <span className="text-gray-400 text-xs">-</span>
                    }
                  </div>
                </TableCell>

                <TableCell className="text-center">
                  {w.has_user ? (
                    <span className="inline-flex items-center gap-2 px-3 py-1 rounded-full
                    bg-green-100 text-green-700 dark:bg-green-900 dark:text-green-200 text-xs font-semibold">
                      <CheckCircle2 className="w-4 h-4" />
                      SUDAH PUNYA USER
                    </span>
                  ) : (
                    <span className="inline-flex items-center gap-2 px-3 py-1 rounded-full
                    bg-red-100 text-red-700 dark:bg-red-900 dark:text-red-200 text-xs font-semibold">
                      <XCircle className="w-4 h-4" />
                      BELUM PUNYA USER
                    </span>
                  )}
                </TableCell>

                <TableCell className="text-right">
                  {canRead('warga') && canEdit('warga') && (
                    <Button
                      size="sm"
                      onClick={() => onEdit(w)}
                      className="bg-[var(--rw-primary)] hover:bg-[var(--rw-primary-hover)] text-white"
                    >
                      Edit
                    </Button>
                  )}
                </TableCell>
              </TableRow>

              {/* EXPANDED DETAIL ROW */}
              {expandedRows.includes(w.id) && (
                <TableRow className="dark:border-gray-700 bg-[var(--rw-bg-card-alt)] dark:bg-gray-800/50">
                  <TableCell colSpan="13" className="p-6">
                    <div className="grid grid-cols-2 md:grid-cols-3 gap-6">
                      <div>
                        <p className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">Nama Lengkap</p>
                        <p className="text-sm font-medium text-gray-900 dark:text-gray-100 mt-1">{w.nama_lengkap}</p>
                      </div>
                      <div>
                        <p className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">No WhatsApp</p>
                        <p className="text-sm font-medium text-gray-900 dark:text-gray-100 mt-1">
                          {w.country_code}{w.whatsapp || "-"}
                        </p>
                      </div>
                      <div>
                        <p className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">Tanggal Lahir</p>
                        <p className="text-sm font-medium text-gray-900 dark:text-gray-100 mt-1">{formatDate(w.tanggal_lahir)}</p>
                      </div>
                      <div>
                        <p className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">Tempat Lahir</p>
                        <p className="text-sm font-medium text-gray-900 dark:text-gray-100 mt-1">{w.tempat_lahir || "-"}</p>
                      </div>
                      <div>
                        <p className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">Jenis Kelamin</p>
                        <p className="text-sm font-medium text-gray-900 dark:text-gray-100 mt-1">{w.jenis_kelamin || "-"}</p>
                      </div>
                      <div>
                        <p className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">Agama</p>
                        <p className="text-sm font-medium text-gray-900 dark:text-gray-100 mt-1">{w.agama || "-"}</p>
                      </div>
                      <div>
                        <p className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">Kewarganegaraan</p>
                        <p className="text-sm font-medium text-gray-900 dark:text-gray-100 mt-1">
                          {w.kewarganegaraan ? `${countryCodeToFlag(w.kewarganegaraan)} ${w.kewarganegaraan}` : "-"}
                        </p>
                      </div>
                      <div>
                        <p className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">Pekerjaan</p>
                        <p className="text-sm font-medium text-gray-900 dark:text-gray-100 mt-1">{w.pekerjaan || "-"}</p>
                      </div>
                      <div>
                        <p className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">Posisi Keluarga</p>
                        <p className="text-sm font-medium text-gray-900 dark:text-gray-100 mt-1">{w.posisi_keluarga || "-"}</p>
                      </div>
                      <div>
                        <p className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">Blok / No Rumah</p>
                        <p className="text-sm font-medium text-gray-900 dark:text-gray-100 mt-1">{w.block_house || "-"}</p>
                      </div>
                      {!isWarga && (
                      <div>
                        <p className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">Status</p>
                        <p className="text-sm font-medium text-gray-900 dark:text-gray-100 mt-1">
                          {getStatusDetailLabel(w)}
                        </p>
                      </div>
                      )}
                      {!isWarga && ["Pindah", "Meninggal"].includes(w.status_detail) && (
                      <div>
                        <p className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">
                          Tanggal {w.status_detail === "Pindah" ? "Pindah" : "Meninggal"}
                        </p>
                        <p className="text-sm font-medium text-gray-900 dark:text-gray-100 mt-1">
                          {w.status_changed_at ? formatDate(w.status_changed_at) : "-"}
                        </p>
                      </div>
                      )}
                      <div>
                        <p className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">Punya User?</p>
                        <p className="text-sm font-medium text-gray-900 dark:text-gray-100 mt-1">
                          {w.has_user ? "✓ Ya" : "✗ Belum"}
                        </p>
                      </div>
                      {!isWarga && (
                      <div>
                        <p className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">Strata Ekonomi</p>
                        <p className="text-sm font-medium text-gray-900 dark:text-gray-100 mt-1">{w.strata_ekonomi || "-"}</p>
                      </div>
                      )}
                      <div>
                        <p className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">Bantuan Diterima</p>
                        <div className="flex flex-wrap gap-1 mt-1">
                          {Array.isArray(w.bantuan_diterima) && w.bantuan_diterima.length > 0
                            ? w.bantuan_diterima.map(b => (
                                <span key={b} className={`px-2 py-1 rounded text-xs font-semibold ${BANTUAN_COLORS[b] || 'bg-gray-100 text-gray-700'}`}>{b}</span>
                              ))
                            : <span className="text-gray-500 text-sm">-</span>}
                        </div>
                      </div>
                      <div>
                        <p className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">Tanggal Dibuat</p>
                        <p className="text-sm font-medium text-gray-900 dark:text-gray-100 mt-1">{formatDate(w.created_at)}</p>
                      </div>
                      <div className="col-span-2 md:col-span-3">
                        <p className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">Keterangan</p>
                        <p className="text-sm font-medium text-gray-900 dark:text-gray-100 mt-1 whitespace-pre-line">{w.keterangan || '-'}</p>
                      </div>
                      <div className="flex gap-2 items-end">
                        {canDelete(user?.role) && (
                          <Button
                            size="sm"
                            variant="destructive"
                            onClick={() => setDeleteConfirm(w.id)}
                          >
                            Hapus
                          </Button>
                        )}
                      </div>
                    </div>
                  </TableCell>
                </TableRow>
              )}
            </>
          ))}
        </TableBody>
      </Table>

      {/* DELETE CONFIRMATION */}
      <AlertDialog open={deleteConfirm !== null} onOpenChange={(open) => !open && setDeleteConfirm(null)}>
        <AlertDialogContent className="bg-[var(--rw-bg-card)] dark:bg-gray-900 dark:text-gray-100">
          <AlertDialogHeader>
            <AlertDialogTitle>Hapus Warga?</AlertDialogTitle>
          </AlertDialogHeader>
          <p className="text-sm text-gray-600 dark:text-gray-400">
            Tindakan ini tidak dapat dibatalkan.
          </p>
          <AlertDialogFooter>
            <AlertDialogCancel className="dark:bg-gray-800 dark:text-gray-200">
              Batal
            </AlertDialogCancel>
            <AlertDialogAction
              onClick={() => remove(deleteConfirm)}
              className="bg-red-600 hover:bg-red-700"
            >
              Hapus
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}
