import React, { useState } from 'react';

/* ── Stars display (readonly) ────────────────────────────────── */
export function Stars({ rating, count, size = 'sm' }) {
  const fontSize = size === 'md' ? '16px' : size === 'lg' ? '20px' : '12px';

  return (
    <span className="stars">
      {[1, 2, 3, 4, 5].map(s => (
        <span
          key={s}
          className={`star ${s <= Math.round(rating) ? 'filled' : 'empty'}`}
          style={{ fontSize }}
        >
          ★
        </span>
      ))}
      {rating > 0 && <span className="rating-val">{rating.toFixed(1)}</span>}
      {count !== undefined && <span className="rating-count">({count})</span>}
    </span>
  );
}

/* ── StarPicker (interactive input) ─────────────────────────── */
export function StarPicker({ value, onChange }) {
  const [hover, setHover] = useState(0);
  const active = hover || value;

  return (
    <div className="star-picker">
      {[1, 2, 3, 4, 5].map(s => (
        <span
          key={s}
          className={`star-pick ${s <= active ? 'active' : 'inactive'}`}
          onMouseEnter={() => setHover(s)}
          onMouseLeave={() => setHover(0)}
          onClick={() => onChange(s)}
          role="button"
          aria-label={`${s} bintang`}
          title={`${s} bintang`}
        >
          ★
        </span>
      ))}
    </div>
  );
}
