import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../contexts/AuthContext';
import { API_BASE_URL } from '../../config/api';
import { Pin, Image as ImageIcon, Newspaper } from 'lucide-react';

const formatDate = (val) => {
  if (!val) return '-';
  return new Date(val).toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' });
};

const Thumb = ({ path }) => (
  path
    ? <img src={`${API_BASE_URL}/${path}`} alt="" className="w-16 h-16 object-cover rounded-lg flex-shrink-0" />
    : (
      <div className="w-16 h-16 rounded-lg bg-gray-200 dark:bg-gray-700 flex items-center justify-center flex-shrink-0">
        <ImageIcon className="w-5 h-5 text-gray-400" />
      </div>
    )
);

const InformasiWargaSection = () => {
  const { token } = useAuth();
  const navigate = useNavigate();
  const [pinned, setPinned] = useState([]);
  const [kategoriList, setKategoriList] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!token) return;
    axios.get(`${API_BASE_URL}/api/informasi/warga/dashboard`, {
      headers: { Authorization: `Bearer ${token}` }
    }).then(res => {
      setPinned(res.data.pinned || []);
      setKategoriList(res.data.kategori || []);
    }).catch(() => {
      setPinned([]);
      setKategoriList([]);
    }).finally(() => setLoading(false));
  }, [token]);

  if (loading) return null;
  if (pinned.length === 0 && kategoriList.length === 0) return null;

  return (
    <div className="space-y-6">
      {pinned.length > 0 && (
        <div className="bg-[var(--rw-bg-card)] dark:bg-gray-800 rounded-lg border border-[var(--rw-border)] dark:border-gray-700 p-5">
          <h3 className="text-base font-semibold text-gray-900 dark:text-gray-100 flex items-center gap-2 mb-4">
            <Pin className="w-4 h-4 text-[var(--rw-primary)]" /> Pin Informasi
          </h3>
          <div className="space-y-3">
            {pinned.map(item => (
              <button
                key={item.id}
                onClick={() => navigate(`/informasi-warga/${item.id}`)}
                className="w-full flex items-center gap-3 bg-white dark:bg-gray-900 rounded-lg p-3 border border-[var(--rw-border)] dark:border-gray-700 hover:shadow-sm transition text-left"
              >
                <Thumb path={item.gambar_header} />
                <div className="min-w-0">
                  <p className="text-sm font-semibold text-gray-900 dark:text-gray-100 truncate">{item.judul}</p>
                  <p className="text-xs text-blue-600 dark:text-blue-400 mt-0.5">Selengkapnya</p>
                </div>
              </button>
            ))}
          </div>
        </div>
      )}

      {kategoriList.map(kat => (
        <div key={kat.kategori} className="bg-[var(--rw-bg-card)] dark:bg-gray-800 rounded-lg border border-[var(--rw-border)] dark:border-gray-700 p-5">
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-base font-semibold text-gray-900 dark:text-gray-100 flex items-center gap-2">
              <Newspaper className="w-4 h-4 text-blue-500" /> {kat.kategori}
            </h3>
            {kat.total > 5 && (
              <button
                onClick={() => navigate(`/informasi-warga/kategori/${encodeURIComponent(kat.kategori)}`)}
                className="text-sm font-medium text-blue-600 dark:text-blue-400 hover:underline"
              >
                Tampilkan Semua
              </button>
            )}
          </div>
          <div className="space-y-3">
            {kat.data.map(item => (
              <button
                key={item.id}
                onClick={() => navigate(`/informasi-warga/${item.id}`)}
                className="w-full flex items-center gap-3 bg-white dark:bg-gray-900 rounded-lg p-3 border border-[var(--rw-border)] dark:border-gray-700 hover:shadow-sm transition text-left"
              >
                <Thumb path={item.gambar_header} />
                <div className="min-w-0 flex-1">
                  <p className="text-sm font-semibold text-gray-900 dark:text-gray-100 truncate">{item.judul}</p>
                  <p className="text-xs text-gray-500 dark:text-gray-400">{formatDate(item.tanggal)}</p>
                </div>
              </button>
            ))}
          </div>
        </div>
      ))}
    </div>
  );
};

export default InformasiWargaSection;
