import React, { useEffect, useMemo, useState } from 'react'
import { API_BASE_URL } from '../../config/api'

// Menu "Kelola" — direktori wilayah publik untuk customer yang belum tahu
// alamat wilayahnya. Data diambil dari GET /api/tenant/public/wilayah, yang
// bersumber dari tabel Tenant yang sama dengan Vendor > Onboarding Wilayah
// (Kelurahan/Desa aktif + RW + RT). Klik "Masuk" membuka /{slug} lewat
// <a href> biasa (full page load) karena slug kelurahan dideteksi dari URL
// saat app pertama kali dimuat (lihat computeSlugBasename di App.js).
export default function Kelola() {
  const [data, setData] = useState([])
  const [status, setStatus] = useState('loading') // loading | ok | error
  const [query, setQuery] = useState('')
  const [open, setOpen] = useState(null)

  useEffect(() => {
    let cancelled = false
    fetch(`${API_BASE_URL}/api/tenant/public/wilayah`)
      .then((r) => (r.ok ? r.json() : Promise.reject(new Error('HTTP ' + r.status))))
      .then((d) => {
        if (cancelled) return
        setData(Array.isArray(d?.kelurahan) ? d.kelurahan : [])
        setStatus('ok')
      })
      .catch(() => { if (!cancelled) setStatus('error') })
    return () => { cancelled = true }
  }, [])

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase()
    if (!q) return data
    return data.filter((k) =>
      [k.name, k.city, k.province, k.address].some((v) => (v || '').toLowerCase().includes(q))
    )
  }, [data, query])

  const origin = typeof window !== 'undefined' ? window.location.host : 'situs-anda'

  return (
    <section className="section" id="kelola" style={{ paddingTop: 40, paddingBottom: 80 }}>
      <div className="container">
        <div className="section-head">
          <span className="kicker">Kelola</span>
          <h2>Temukan <span className="ital">wilayah</span> Anda.</h2>
          <p>
            Belum tahu alamat wilayah Anda? Pilih Kelurahan/Desa di bawah ini,
            lalu masuk langsung ke halamannya. Sudah tahu? Cukup ketik
            {' '}<span className="mono">{origin}/nama-wilayah</span> di browser.
          </p>
        </div>

        <div className="kelola-search">
          <input
            type="search"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="Cari kelurahan/desa, kota, atau kabupaten…"
            aria-label="Cari wilayah"
          />
        </div>

        {status === 'loading' && <div className="kelola-empty">Memuat daftar wilayah…</div>}
        {status === 'error' && <div className="kelola-empty">Daftar wilayah belum dapat dimuat. Silakan coba lagi nanti.</div>}
        {status === 'ok' && filtered.length === 0 && (
          <div className="kelola-empty">
            {data.length === 0 ? 'Belum ada wilayah yang terdaftar.' : 'Wilayah tidak ditemukan.'}
          </div>
        )}

        <div className="kelola-grid">
          {filtered.map((k) => {
            const isOpen = open === k.slug
            const totalRT = k.rw.reduce((n, r) => n + r.rt.length, 0) + k.rt_langsung.length
            const place = [k.city, k.province].filter(Boolean).join(', ')
            return (
              <article className={'kelola-card' + (isOpen ? ' open' : '')} key={k.slug}>
                <div className="kelola-card-top">
                  <div>
                    <h4>{k.name}</h4>
                    {place && <div className="kelola-place">{place}</div>}
                    <div className="kelola-count mono">{k.rw.length} RW · {totalRT} RT</div>
                  </div>
                  <a href={`/${k.slug}`} className="btn btn-primary">Masuk</a>
                </div>

                {(k.rw.length > 0 || k.rt_langsung.length > 0) && (
                  <>
                    <button
                      type="button"
                      className="kelola-toggle"
                      onClick={() => setOpen(isOpen ? null : k.slug)}
                      aria-expanded={isOpen}
                    >
                      {isOpen ? 'Sembunyikan wilayah' : 'Lihat RW & RT'} <span aria-hidden="true">{isOpen ? '−' : '+'}</span>
                    </button>
                    {isOpen && (
                      <div className="kelola-detail">
                        {k.rw.map((rw, i) => (
                          <div className="kelola-rw" key={i}>
                            <strong>{rw.name}</strong>
                            <div className="kelola-rts">
                              {rw.rt.length === 0
                                ? <span className="kelola-chip muted">Belum ada RT</span>
                                : rw.rt.map((n, j) => <span className="kelola-chip" key={j}>{n}</span>)}
                            </div>
                          </div>
                        ))}
                        {k.rt_langsung.length > 0 && (
                          <div className="kelola-rw">
                            <strong>RT lainnya</strong>
                            <div className="kelola-rts">
                              {k.rt_langsung.map((n, j) => <span className="kelola-chip" key={j}>{n}</span>)}
                            </div>
                          </div>
                        )}
                      </div>
                    )}
                  </>
                )}
              </article>
            )
          })}
        </div>
      </div>
    </section>
  )
}
