import React, { useState, useEffect } from 'react'
import { useCMS } from './cmsContent.jsx'
import { useAppSettings } from '../../contexts/AppSettingsContext'

// Nav landingpage3 — sama seperti landingpage2, kecuali: logo brand-mark
// ambil dari Vendor > Settings > Parameter Aplikasi (bukan huruf "R" statis),
// dan tombol "Masuk"/"Coba Gratis" + link "Harga" dihilangkan.
export default function Nav() {
  const c = useCMS('nav')
  const { logoUrl, appName } = useAppSettings()
  const [scrolled, setScrolled] = useState(false)
  const [open, setOpen] = useState(false)
  useEffect(() => {
    const on = () => setScrolled(window.scrollY > 8)
    window.addEventListener('scroll', on, { passive: true })
    return () => window.removeEventListener('scroll', on)
  }, [])
  // Tutup menu mobile dengan Esc, dan kunci scroll halaman saat menu terbuka
  useEffect(() => {
    if (!open) return undefined
    const onKey = (e) => { if (e.key === 'Escape') setOpen(false) }
    const prev = document.body.style.overflow
    document.body.style.overflow = 'hidden'
    window.addEventListener('keydown', onKey)
    return () => {
      document.body.style.overflow = prev
      window.removeEventListener('keydown', onKey)
    }
  }, [open])
  // Menu "Kelola" (direktori wilayah) ditambahkan di kode, bukan lewat CMS,
  // supaya selalu ada walau konten CMS tersimpan lama tidak memuatnya.
  const base = (c.links || []).filter((l) => (l.label || '').toLowerCase() !== 'harga')
  const links = base.some((l) => (l.label || '').toLowerCase() === 'kelola')
    ? base
    : (() => {
        const i = base.findIndex((l) => (l.href || '') === '#cara')
        const at = i >= 0 ? i + 1 : base.length
        return [...base.slice(0, at), { label: 'Kelola', href: '#kelola' }, ...base.slice(at)]
      })()
  return (
    <header className={'nav ' + (scrolled || open ? 'scrolled ' : '') + (open ? 'nav-open' : '')}>
      <div className="container nav-inner">
        <a href="#" className="brand">
          {logoUrl ? (
            <img src={logoUrl} alt={appName} className="brand-mark-img" />
          ) : (
            <div className="brand-mark">R</div>
          )}
          <div className="brand-name">
            <span>{c.brand_name}</span>
            <small>{c.brand_version}</small>
          </div>
        </a>
        <nav id="nav-links" className="nav-links">
          {links.map((l, i) => (
            <a key={i} href={l.href} onClick={() => setOpen(false)}>{l.label}</a>
          ))}
        </nav>
        <button
          type="button"
          className="nav-toggle"
          aria-label={open ? 'Tutup menu' : 'Buka menu'}
          aria-expanded={open}
          aria-controls="nav-links"
          onClick={() => setOpen((v) => !v)}
        >
          <span /><span /><span />
        </button>
      </div>
    </header>
  )
}
