import axios from 'axios';
import { API_BASE_URL } from '../config/api';

// Download surat terbit sebagai DOCX native dari backend (tampilan setara PDF).
export async function downloadSuratDocx(item, token) {
  if (!item?.id) return;
  const res = await axios.get(`${API_BASE_URL}/api/surat-resmi/permohonan/${item.id}/docx`, {
    headers: { Authorization: `Bearer ${token}` },
    responseType: 'blob',
  });
  const url = URL.createObjectURL(res.data);
  const a = document.createElement('a');
  a.href = url;
  a.download = `${item.nomor_surat?.replace(/\//g, '-') || 'surat'}.docx`;
  a.click();
  URL.revokeObjectURL(url);
}
