import React, { useState, useEffect, useMemo, useRef } from 'react';
import { useAppSettings } from '../contexts/AppSettingsContext';

/**
 * Banner gambar vendor — memanjang mengikuti lebar box (card), auto-slide
 * antar gambar (png/jpg/gif/webp). Dipakai di:
 *  - Dashboard RT/RW/Kelurahan: variant="dashboard" (di bawah header)
 *
 * Sudut kotak dibuat siku-siku (bukan rounded, seperti unit iklan pada
 * umumnya), dan di mode Fit sisa ruang kiri/kanan atau atas/bawah diisi
 * abu-abu tipis semi-transparan (bukan blur, bukan tembus pandang penuh).
 *
 * Ukuran (tinggi/lebar) BISA DICUSTOM vendor lewat menu Settings — lihat
 * `bannerConfig` di AppSettingsContext (dashboard_height, login_height,
 * login_max_width, disimpan dalam px). Di sini nilai tsb dipakai lewat
 * CSS `clamp()` supaya tetap responsif (menyusut proporsional di layar
 * kecil) tapi tidak pernah melebihi ukuran yang diset vendor.
 *
 * Transisi antar banner JUGA bisa dicustom vendor — `bannerConfig.transitionType`
 * (fade / slide / zoom / none) dan `bannerConfig.transitionDurationMs` (lama
 * animasi dalam ms). Lihat helper `getSlideStyle` di bawah untuk detail tiap mode.
 *
 * Fitur:
 *  - Tiap banner bisa disematkan link (link_url) — kalau ada, banner bisa
 *    diklik untuk membuka halaman web tersebut di tab baru.
 *  - Tiap banner punya toggle show_on_login / show_on_dashboard sendiri
 *    (diatur vendor), jadi satu banner bisa dipilih tampil di salah satu
 *    halaman saja, atau keduanya.
 *  - Dot indikator di bawah banner mewakili tiap gambar (mis. 3 banner =
 *    3 dot) dan bisa diklik untuk lompat langsung ke banner tersebut.
 *  - Bisa di-swipe/touch-scroll (geser jari ke kiri/kanan) untuk pindah
 *    banner secara manual, selain auto-slide dan klik dot.
 *
 * Dioptimasi supaya ringan:
 *  - Hanya gambar aktif yang di-render penuh; gambar lain di-preload
 *    dengan `loading="lazy"` lewat elemen tersembunyi.
 *  - Tidak melakukan fetch tambahan — data banner & ukuran sudah diambil
 *    sekali lewat AppSettingsContext saat aplikasi dimuat.
 *  - GIF disajikan langsung sebagai <img> sehingga animasinya tetap
 *    berjalan natural dari browser (tidak di-decode ulang).
 */
export default function VendorImageBanner({ variant = 'dashboard', intervalMs = 4500, className = '' }) {
  const { banners, bannerConfig } = useAppSettings();
  const [active, setActive] = useState(0);
  const dragRef = useRef({ startX: 0, startY: 0, dragging: false, swiped: false });

  const images = useMemo(() => {
    const all = Array.isArray(banners) ? banners : [];
    const flag = variant === 'login' ? 'show_on_login' : 'show_on_dashboard';
    // Default true kalau field belum ada (data lama sebelum fitur ini) supaya tidak tiba-tiba hilang.
    return all.filter(b => b[flag] !== false);
  }, [banners, variant]);

  useEffect(() => {
    setActive(0);
  }, [images.length]);

  useEffect(() => {
    if (images.length <= 1) return;
    const t = setInterval(() => {
      setActive(i => (i + 1) % images.length);
    }, intervalMs);
    return () => clearInterval(t);
  }, [images.length, intervalMs]);

  if (!images.length) return null;

  const dashboardH = bannerConfig?.dashboardHeight ?? 160;
  const loginH     = bannerConfig?.loginHeight ?? 56;
  const loginW     = bannerConfig?.loginMaxWidth ?? 384;
  const stretch    = bannerConfig?.stretchMode !== false; // default true (stretch)
  const transitionType = bannerConfig?.transitionType || 'fade'; // fade / slide / zoom / none
  const transitionMs   = bannerConfig?.transitionDurationMs ?? 700;

  // clamp(min, preferred-berbasis-viewport, max-dari-config) — tetap responsif
  // di layar kecil tapi tidak pernah melebihi ukuran yang diset vendor.
  // Sisi kiri/kanan yang tidak tertutup gambar (mode Fit) diisi abu-abu tipis
  // semi-transparan — persis seperti unit iklan Google/media lain (kotak
  // rectangle, bukan konten di baliknya yang tembus pandang penuh).
  const boxStyle = variant === 'login'
    ? { height: `clamp(40px, 10vw, ${loginH}px)`, width: '100%', maxWidth: `${loginW}px`, background: 'rgba(120,120,120,0.08)' }
    : { height: `clamp(64px, 16vw, ${dashboardH}px)`, width: '100%', background: 'rgba(120,120,120,0.08)' };

  const activeImg = images[active];

  const goTo = (idx) => setActive(((idx % images.length) + images.length) % images.length);

  const handleBannerClick = () => {
    if (dragRef.current.swiped) { dragRef.current.swiped = false; return; }
    if (activeImg?.link_url) {
      window.open(activeImg.link_url, '_blank', 'noopener,noreferrer');
    }
  };

  const SWIPE_THRESHOLD = 40; // px minimal geser supaya dianggap swipe, bukan tap

  const onPointerDown = (e) => {
    if (images.length <= 1) return;
    dragRef.current.startX = e.clientX;
    dragRef.current.startY = e.clientY;
    dragRef.current.dragging = true;
    dragRef.current.swiped = false;
  };

  const onPointerMove = (e) => {
    if (!dragRef.current.dragging) return;
    const dx = e.clientX - dragRef.current.startX;
    const dy = e.clientY - dragRef.current.startY;
    // Kalau gesernya lebih vertikal (scroll halaman), biarkan browser handle — jangan ganggu.
    if (Math.abs(dy) > Math.abs(dx)) return;
  };

  const endDrag = (clientX, clientY) => {
    if (!dragRef.current.dragging) return;
    dragRef.current.dragging = false;
    const dx = clientX - dragRef.current.startX;
    const dy = clientY - dragRef.current.startY;
    if (Math.abs(dx) >= SWIPE_THRESHOLD && Math.abs(dx) > Math.abs(dy)) {
      dragRef.current.swiped = true;
      goTo(active + (dx < 0 ? 1 : -1)); // geser kiri -> banner berikutnya, geser kanan -> sebelumnya
    }
  };

  const onPointerUp = (e) => endDrag(e.clientX, e.clientY);
  const onPointerLeave = (e) => { if (dragRef.current.dragging) endDrag(e.clientX, e.clientY); };

  const onTouchStart = (e) => {
    if (images.length <= 1) return;
    const t = e.touches[0];
    dragRef.current.startX = t.clientX;
    dragRef.current.startY = t.clientY;
    dragRef.current.dragging = true;
    dragRef.current.swiped = false;
  };
  const onTouchEnd = (e) => {
    const t = e.changedTouches[0];
    endDrag(t.clientX, t.clientY);
  };

  // Style per-gambar sesuai tipe transisi yang dipilih vendor.
  // - fade: crossfade opacity (default, paling halus & aman untuk semua kasus)
  // - slide: geser horizontal seperti carousel — tiap gambar diposisikan
  //   relatif terhadap slide aktif (jalur terpendek, jadi loop tetap mulus)
  // - zoom: fade + sedikit scale in/out
  // - none: langsung ganti tanpa animasi
  const getSlideStyle = (idx) => {
    const isActive = idx === active;
    const base = { pointerEvents: isActive ? 'auto' : 'none' };

    if (transitionType === 'slide') {
      const n = images.length;
      let diff = idx - active;
      if (diff > n / 2) diff -= n;
      if (diff < -n / 2) diff += n;
      return {
        ...base,
        transform: `translateX(${diff * 100}%)`,
        transition: `transform ${transitionMs}ms ease-in-out`,
        opacity: 1,
      };
    }

    if (transitionType === 'zoom') {
      return {
        ...base,
        opacity: isActive ? 1 : 0,
        transform: isActive ? 'scale(1)' : 'scale(0.92)',
        transition: `opacity ${transitionMs}ms ease-in-out, transform ${transitionMs}ms ease-in-out`,
      };
    }

    if (transitionType === 'none') {
      return {
        ...base,
        opacity: isActive ? 1 : 0,
        transition: 'none',
      };
    }

    // fade (default)
    return {
      ...base,
      opacity: isActive ? 1 : 0,
      transition: `opacity ${transitionMs}ms ease-in-out`,
    };
  };

  return (
    <div
      className={`relative overflow-hidden select-none touch-pan-y ${className} ${activeImg?.link_url ? 'cursor-pointer' : ''}`}
      style={boxStyle}
      role="img"
      aria-label="Banner pengumuman"
      onClick={handleBannerClick}
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={onPointerUp}
      onPointerLeave={onPointerLeave}
      onTouchStart={onTouchStart}
      onTouchEnd={onTouchEnd}
    >
      {images.map((img, idx) => (
        <div
          key={img.id || idx}
          className="absolute inset-0"
          style={getSlideStyle(idx)}
        >
          {stretch ? (
            /* Mode Stretch — gambar mengisi penuh kotak mengikuti panjang & lebarnya
               (tidak dipotong, tidak ada blur, tapi rasio gambar ikut menyesuaikan bentuk kotak). */
            <img
              src={img.image_url}
              alt={img.judul || 'Banner'}
              loading={idx === active ? 'eager' : 'lazy'}
              className="absolute inset-0 w-full h-full object-fill"
              draggable={false}
            />
          ) : (
            /* Mode Fit — rasio gambar asli dijaga (tidak dipotong, tidak stretch),
               sisa ruang kiri/kanan atau atas/bawah diisi abu-abu tipis semi-transparan
               (kotak rectangle seperti unit iklan pada umumnya). */
            <img
              src={img.image_url}
              alt={img.judul || 'Banner'}
              loading={idx === active ? 'eager' : 'lazy'}
              className="absolute inset-0 w-full h-full object-contain"
              draggable={false}
            />
          )}
        </div>
      ))}

      {images.length > 1 && (
        <div className="absolute bottom-1 left-1/2 -translate-x-1/2 flex gap-1.5 z-10">
          {images.map((_, idx) => (
            <button
              key={idx}
              type="button"
              onClick={(e) => { e.stopPropagation(); goTo(idx); }}
              aria-label={`Banner ${idx + 1}`}
              className="p-1 -m-1 flex items-center justify-center"
            >
              <span
                className="rounded-full transition-all duration-300 block"
                style={{
                  width: idx === active ? 12 : 5,
                  height: 5,
                  background: idx === active ? 'rgba(255,255,255,0.95)' : 'rgba(255,255,255,0.5)',
                }}
              />
            </button>
          ))}
        </div>
      )}
    </div>
  );
}
